                            <span className="text-[11px] text-slate-500 uppercase">Download .txt</span>
                        </div>
                    </button>
                </div>
            )}
        </div>
    );
};

import React from 'react';
import GameCanvas from './components/GameCanvas';

// UI Components
import { ShowcaseOverlay } from './components/ui/ShowcaseOverlay';
import { PlaybackHUD } from './components/ui/PlaybackHUD';
import { MapEditorToolbar } from './components/ui/MapEditorToolbar';
import { UnitInspectorHUD } from './components/ui/UnitInspectorHUD';
import { SystemMenu } from './components/ui/SystemMenu';
import { ModalManager } from './components/ui/ModalManager';
import { Icons } from './components/ui/icons';

// Hook
import { useGameApp } from './hooks/useGameApp';

function App() {
  const { engineRef, state, setters, actions } = useGameApp();

  const isGameOver = state.winner !== null;
  const hideHUD = state.isShowcaseMode || isGameOver;

  return (
    <div className="h-[100dvh] w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans flex flex-col relative select-none touch-none">

      {/* WARNING NOTIFICATION */}
      {state.showFactionWarning && (
            <div className="absolute top-24 left-1/2 -translate-x-1/2 z-50 animate-bounce-in pointer-events-none w-[90%] max-w-md">
                <div className="liquid-glass px-6 py-3 rounded-full border-red-500/50 flex items-center gap-3 shadow-xl text-red-200 bg-red-950/80">
                    <Icons.Warning className="w-6 h-6 text-red-400" />
                    <div className="flex flex-col">
                        <span className="text-xs font-bold tracking-widest text-red-400 uppercase">部署錯誤</span>
                        <span className="text-xs">請部署雙方單位以開始戰鬥。</span>
                    </div>
                </div>
            </div>
      )}

      {/* SHOWCASE OVERLAY */}
      {state.isShowcaseMode && (
        <ShowcaseOverlay 
            onEnter={actions.enterManualMode} 
            timeScale={state.timeScale} 
            setTimeScale={setters.setTimeScale} 
        />
      )}

      {/* --- HUD LAYERS --- */}

      {/* 1. Playback Controls */}
      <PlaybackHUD 
          hidden={hideHUD}
          isPlaying={state.isPlaying}
          winner={state.winner}
          timeScale={state.timeScale}
          onTogglePlay={actions.togglePlay}
          onRestart={actions.handleReset}
          onRandom={actions.handleRandomBattlefield} 
          onSetTimeScale={setters.setTimeScale}
          onShowcase={() => { setters.setIsShowcaseMode(true); actions.startShowcaseMatch(); }}
      />

      {/* 2. System Menu */}
      {!hideHUD && (
          <SystemMenu 
              onToggleLogs={() => setters.setShowLogs(!state.showLogs)}
              onToggleDB={() => setters.setShowDB(!state.showDB)}
              onToggleVFXMap={() => setters.setShowVFXMap(!state.showVFXMap)}
              onDownloadSpec={actions.downloadSpec}
          />
      )}

      {/* 3. Unit Inspector (Now receives Engine for direct BT rendering) */}
      {!hideHUD && state.selectedAgent && (
          <UnitInspectorHUD 
              agent={state.selectedAgent} 
              engine={engineRef.current}
              onClose={() => actions.handleSelectAgent(null)} 
          />
      )}

      {/* 4. Modals (Logs / DB / VFX Map) */}
      {!hideHUD && (
          <ModalManager 
              showLogs={state.showLogs}
              showDB={state.showDB}
              showVFXMap={state.showVFXMap}
              engine={engineRef.current}
              onClose={() => {
                  setters.setShowLogs(false);
                  setters.setShowDB(false);
                  setters.setShowVFXMap(false);
              }}
          />
      )}

      {/* MAIN GAME VIEW */}
      <div className="flex-1 relative z-0 bg-slate-900">
            <GameCanvas 
                engine={engineRef.current} 
                tool={state.tool}
                selectedObstacle={state.selectedObstacle}
                hpInput={state.hpInput}
                selectedAgent={state.selectedAgent}
                hoveredSkill={state.hoveredSkill}
                isShowcaseMode={state.isShowcaseMode}
                spawnMode={state.spawnMode}
                draftRole={state.draftRole}
                onSelect={actions.handleSelectAgent} 
                winner={state.winner}
                rematch={actions.rematch}
                nextLevel={actions.handleNextLevel} 
                transitionPhase={state.transitionPhase}
            />
      </div>

      {/* 5. Map Editor Dock */}
      {!hideHUD && (
          <MapEditorToolbar 
              tool={state.tool}
              setTool={setters.setTool}
              mapW={state.mapW} setMapW={(w) => actions.handleUpdateMapSize(w, state.mapH)}
              mapH={state.mapH} setMapH={(h) => actions.handleUpdateMapSize(state.mapW, h)}
              currentSceneId={state.currentSceneId}
              onSetScene={actions.handleSetScene}
              spawnMode={state.spawnMode} setSpawnMode={setters.setSpawnMode}
              draftRole={state.draftRole} setDraftRole={setters.setDraftRole}
              hpInput={state.hpInput} setHpInput={setters.setHpInput}
              selectedObstacle={state.selectedObstacle} setSelectedObstacle={setters.setSelectedObstacle}
          />
      )}
    </div>
  );
}

export default App;

import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../../types";
import { SpriteManager } from "../../../sprites";
import { THEME_IMPERIAL, THEME_COVENANT } from "../../../../constants";

// =========================================================================================
// 🛠️ GENERIC / SHARED UTILS (Base Building Blocks)
// =========================================================================================

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE' | 'SHARD' | 'DEBRIS') {
    const safeCount = Math.min(type === 'SPARK' ? 12 : 6, count);
    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        const spd = Math.random() * 200 * speed;
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd; p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 200 + 100) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4); p.maxLife = life;
        p.color = color;
        p.size = type === 'SPARK' ? Math.random() * 4 + 3 : Math.random() * 20 + 20;
        if (type === 'SHARD' || type === 'DEBRIS') p.size = 5 + Math.random() * 5;
        p.type = type; p.delay = 0;
        system.state.particles.push(p);
    }
}

export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'RING' | 'BLAST' | 'SHOCKWAVE', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 30; // Default size
    p.type = type;
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0; p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; p.color = color; p.size = 4; p.type = 'BEAM'; p.delay = 0;
    system.state.particles.push(p);
}

export function spawnDeathRay(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0; 
    p.targetX = tx; p.targetY = ty;
    p.life = 0.3; p.maxLife = 0.3; 
    p.color = color; 
    p.size = 8; 
    p.type = 'DEATH_RAY'; 
    p.delay = 0;
    system.state.particles.push(p);
}

export function addDecal(system: VFXSystem, x: number, y: number, color: string) {
    system.state.decals.push({
        x, y, color, life: 5.0, scale: 0.5 + Math.random() * 0.3
    });
}

export function spawnDirectionalImpact(system: VFXSystem, x: number, y: number, z: number, dirX: number, dirY: number, color: string, type: 'PHYSICAL' | 'MAGICAL') {
    const isPhysical = type === 'PHYSICAL';
    const baseAngle = Math.atan2(dirY, dirX);
    const count = 10;
    const spread = 0.8; 

    for (let i = 0; i < count; i++) {
        const angle = baseAngle + (Math.random() - 0.5) * spread;
        const speed = 400 + Math.random() * 400; 
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 50 + Math.random() * 200; 

        p.life = 0.3 + Math.random() * 0.3; p.maxLife = p.life;
        p.color = isPhysical ? '#e2e8f0' : color; 
        p.size = 4 + Math.random() * 6; 
        p.type = 'SPARK'; 
        p.delay = 0;
        system.state.particles.push(p);
    }

    if (isPhysical) {
        spawnExplosion(system, x, y, z, 3, '#fff', 0.2, 0.4, 'SMOKE');
    } else {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = 0; p.vy = 0; p.vz = 0;
        p.life = 0.4; p.maxLife = 0.4;
        p.color = color;
        p.size = 20; 
        p.type = 'RING';
        system.state.particles.push(p);
    }
}

export function spawnConnectorSlash(system: VFXSystem, x1: number, y1: number, x2: number, y2: number, color: string, visual: string) {
    const p = system.state.getParticle();
    p.x = x1; p.y = y1 - 30; 
    p.targetX = x2; p.targetY = y2 - 30;
    p.z = 30;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = 0.25; p.maxLife = 0.25;
    p.color = color; p.size = 10;
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnGridImpact(system: VFXSystem, x: number, y: number, color: string, team: Team, delay: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.life = 1.2; p.maxLife = 1.2;
    p.color = color;
    p.size = 36; 
    p.type = 'GRID_FIELD'; 
    p.delay = delay;
    system.state.particles.push(p);

    if (Math.random() > 0.5) {
        const s = system.state.getParticle();
        s.x = x; s.y = y; s.z = 10;
        s.vx = 0; s.vy = 0; s.vz = 150; 
        s.life = 0.4; s.maxLife = 0.4;
        s.color = color; s.size = 20;
        s.type = 'SPARK';
        s.delay = delay;
        system.state.particles.push(s);
    }
}

export function spawnLingeringField(system: VFXSystem, x: number, y: number, color: string, type: string, duration: number, delay: number) {
    const count = 3;
    for(let i=0; i<count; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*20;
        p.y = y + (Math.random()-0.5)*15;
        p.z = 5;
        p.vx = (Math.random()-0.5) * 20;
        p.vy = (Math.random()-0.5) * 20;
        p.vz = 10 + Math.random() * 20; 
        p.life = duration + Math.random(); p.maxLife = p.life;
        p.color = color;
        p.size = 25 + Math.random() * 25; // Larger puffs
        p.type = 'SMOKE';
        p.delay = delay + Math.random() * 0.5;
        system.state.particles.push(p);
    }
}

export function spawnCastBreak(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    const blast = system.state.getParticle();
    blast.x = x; blast.y = y; blast.z = 20;
    blast.vx = 0; blast.vy = 0; blast.vz = 0;
    blast.life = 0.2; blast.maxLife = 0.2;
    blast.color = '#00ffff'; 
    blast.size = 100;
    blast.type = 'BLAST';
    system.state.particles.push(blast);

    const glitchCount = 8;
    for(let i=0; i<glitchCount; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*40;
        p.y = y + (Math.random()-0.5)*40;
        p.z = 40;
        p.vx = (Math.random()-0.5) * 50; 
        p.vy = (Math.random()-0.5) * 50;
        p.vz = 0;
        p.life = 0.3; p.maxLife = 0.3;
        p.color = Math.random() > 0.5 ? '#00ffff' : '#ff00ff';
        p.size = 4 + Math.random() * 4;
        p.type = 'CHIP'; 
        system.state.particles.push(p);
    }
}

export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    addImpact(system, x, y, 5, color, 'RING', 0.8);
    spawnExplosion(system, x, y, 10, 8, color, 0.5, 0.5, 'SPARK');
}

export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role) {
    const assets = SpriteManager.getUnitImages(role, team);
    const isBlue = team === Team.BLUE;

    const theme = isBlue ? THEME_IMPERIAL : THEME_COVENANT;
    const baseColor = isBlue ? '#94a3b8' : '#27272a';
    const armorColor = theme.primary;
    const glowColor = isBlue ? THEME_IMPERIAL.energy : theme.secondary;

    // 1. Icon Sprite
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 60; 
    const angle = Math.random() * Math.PI * 2;
    p.vx = Math.cos(angle) * 150; 
    p.vy = Math.sin(angle) * 150; 
    p.vz = 350; 
    p.life = 1.5; p.maxLife = 1.5;
    p.color = '#fff'; p.size = 64 * 0.6; 
    p.type = 'SPRITE'; p.image = assets.icon;
    p.rotation = Math.random() * Math.PI * 2; 
    p.vRotation = (Math.random() - 0.5) * 40; 
    system.state.particles.push(p);

    // 2. Base Debris
    for (let i = 0; i < 5; i++) {
        const p = system.state.getParticle();
        const angle = (i / 5) * Math.PI * 2;
        p.x = x; p.y = y; p.z = 10;
        const speed = 150 + Math.random() * 100;
        p.vx = Math.cos(angle) * speed; 
        p.vy = Math.sin(angle) * speed; 
        p.vz = 150 + Math.random() * 150; 
        p.life = 2.0; p.maxLife = 2.0;
        p.color = baseColor; 
        p.size = 8 + Math.random() * 8; 
        p.type = 'DEBRIS'; 
        p.rotation = angle; 
        p.vRotation = (Math.random()-0.5)*15;
        system.state.particles.push(p);
    }

    // 3. Armor Shards
    for (let i = 0; i < 8; i++) {
        const p = system.state.getParticle();
        const angle = Math.random() * Math.PI * 2;
        p.x = x; p.y = y; p.z = 40;
        const speed = 200 + Math.random() * 200;
        p.vx = Math.cos(angle) * speed; 
        p.vy = Math.sin(angle) * speed; 
        p.vz = 250 + Math.random() * 250; 
        p.life = 1.5; p.maxLife = 1.5;
        p.color = Math.random() > 0.5 ? armorColor : theme.secondary; 
        p.size = 5 + Math.random() * 5; 
        p.type = 'SHARD'; 
        p.rotation = angle; 
        p.vRotation = (Math.random()-0.5)*25;
        system.state.particles.push(p);
    }

    // 4. Soul Release
    const soul = system.state.getParticle();
    soul.x = x; soul.y = y; soul.z = 10;
    soul.vx = 0; soul.vy = 0; soul.vz = 30; 
    soul.life = 1.0; soul.maxLife = 1.0;
    soul.color = glowColor;
    soul.size = 80;
    soul.type = 'GLOW'; 
    system.state.particles.push(soul);

    // 5. Ground Scorch
    addDecal(system, x, y, '#000'); 
    spawnShockwave(system, x, y, glowColor, 0.4);
    spawnExplosion(system, x, y, 40, 15, baseColor, 0.8, 0.8, 'SMOKE');
}

// 🏛️ DIVINE PILLAR (Helper for Pillar effects)
export function spawnDivinePillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.life = life; p.maxLife = life;
    p.color = color; 
    p.size = 20; 
    p.type = 'PILLAR'; 
    p.delay = delay;
    system.state.particles.push(p);
}

// 🩸 BLOOD RITUAL (Helper for non-pillar ground effects)
export function spawnBloodRitual(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 120; 
    p.type = 'DOMAIN'; 
    p.delay = 0;
    system.state.particles.push(p);

    for(let i=0; i<8; i++) {
        const d = system.state.getParticle();
        d.x = x + (Math.random()-0.5)*50; 
        d.y = y + (Math.random()-0.5)*30; 
        d.z = 0;
        d.vx = (Math.random()-0.5)*50;
        d.vy = (Math.random()-0.5)*50;
        d.vz = 100 + Math.random() * 200; 
        d.life = life * 0.8; d.maxLife = life * 0.8;
        d.color = '#000'; 
        d.size = 5 + Math.random() * 8;
        d.type = 'DEBRIS';
        d.rotation = Math.random();
        d.vRotation = Math.random();
        system.state.particles.push(d);
    }
}

// =========================================================================================
// 🌍 NEUTRAL / GENERIC ULTIMATES
// =========================================================================================

// ☢️ TACTICAL NUKE (rr_u2)
export function spawnTacticalNuke(system: VFXSystem, x: number, y: number, color: string) {
    const flash = system.state.getParticle();
    flash.x = x; flash.y = y; flash.z = 50;
    flash.life = 0.2; flash.maxLife = 0.2;
    flash.color = '#fff'; flash.size = 800; 
    flash.type = 'GLOW'; 
    system.state.particles.push(flash);

    // Mushroom Stem
    for(let i=0; i<8; i++) {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = 10;
        p.vx = (Math.random()-0.5) * 20;
        p.vy = (Math.random()-0.5) * 20;
        p.vz = 100 + i * 80;
        p.life = 2.0; p.maxLife = 2.0;
        p.color = i < 3 ? '#fbbf24' : '#4b5563';
        p.size = 40 + i * 5;
        p.type = 'SMOKE';
        p.delay = 0.1;
        system.state.particles.push(p);
    }

    // Mushroom Cap
    for(let i=0; i<12; i++) {
        const p = system.state.getParticle();
        const angle = Math.random() * Math.PI * 2;
        const dist = Math.random() * 30;
        p.x = x + Math.cos(angle)*dist; 
        p.y = y + Math.sin(angle)*dist; 
        p.z = 250; 
        p.vx = Math.cos(angle) * 80;
        p.vy = Math.sin(angle) * 80;
        p.vz = 20 + Math.random() * 40; 
        p.life = 2.5; p.maxLife = 2.5;
        p.color = Math.random() > 0.5 ? '#ef4444' : '#1f2937';
        p.size = 60 + Math.random() * 40;
        p.type = 'SMOKE';
        p.rotation = Math.random() * Math.PI;
        p.delay = 0.3; 
        system.state.particles.push(p);
    }

    // Ground Rings
    for(let i=0; i<3; i++) {
        const p = system.state.getParticle();
