    for(let i=0; i<25; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5) * 250;
        p.y = y + (Math.random()-0.5) * 250;
        p.z = 10;

        p.vx = (Math.random()-0.5) * 50;
        p.vy = (Math.random()-0.5) * 50;
        p.vz = 80 + Math.random() * 100;

        p.life = 2.5; p.maxLife = 2.5;
        p.color = '#84cc16';
        p.size = 20 + Math.random() * 20;
        p.type = 'GLOW';
        system.state.particles.push(p);
    }
}

import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";

// Modular Spawners
import * as Generic from "../vfx/spawners/generic";
import * as Imperial from "../vfx/spawners/imperial";
import * as Covenant from "../vfx/spawners/covenant";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                }
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'IMPACT_AOE':
                if (event.skill) {
                    const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                    const radius = event.skill.aoeRadius || 1;
                    const affectedHexes = HexUtils.range(centerHex, radius);

                    const id = event.skill.id;
                    const color = event.color || '#fff';

                    // =================================================================
                    // 🔵 IMPERIAL (BLUE) ULTIMATE VFX MAPPING
                    // =================================================================

                    // 🛡️ TANK: Divine Territory (Sanctuary)
                    if (id === 'tb_u1') {
                        Imperial.spawnImperialSanctuary(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.7);
                        return;
                    }
                    // 🛡️ TANK: Kings Blessing (Invuln)
                    if (id === 'tb_u2') {
                        Imperial.spawnImperialKingsBlessing(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3);
                        return;
                    }
                    // ⚔️ WARRIOR: Thunder Jump (Shockwave)
                    if (id === 'wb_u1') {
                        Imperial.spawnImperialThunder(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6);
                        return;
                    }
                    // ⚔️ WARRIOR: Daybreak (Sun Strike)
                    if (id === 'wb_u2') {
                        Imperial.spawnImperialDaybreak(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8);
                        return;
                    }
                    // 🏹 RANGER: Crystal Arrow (Shatter)
                    if (id === 'rb_u1') {
                        Imperial.spawnImperialCrystalArrow(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6);
                        return;
                    }
                    // 🏹 RANGER: Starfall (Rain)
                    if (id === 'rb_u2') {
                        Imperial.spawnImperialStarfall(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.4);
                        return;
                    }
                    // 🔮 MAGE: Black Hole (Gravity)
                    if (id === 'mb_u1') {
                        Generic.spawnBlackHoleCollapse(vfx, event.pos.x, visualGroundY, '#0f172a');
                        camera.addTrauma(0.5);
                        return;
                    }
                    // 🔮 MAGE: Absolute Zero (Frostfall)
                    if (id === 'mb_u2') {
                        Imperial.spawnImperialFrostfall(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.5);
                        return;
                    }
                    // ⚕️ SUPPORT: Divine Intervention (Miracle)
                    if (id === 'sb_u1') {
                        Imperial.spawnImperialIntervention(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3);
                        return;
                    }
                    // ⚕️ SUPPORT: Resurrection (Full Heal)
                    if (id === 'sb_u2') {
                        Imperial.spawnImperialResurrection(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.4);
                        return;
                    }

                    // =================================================================
                    // 🔴 COVENANT (RED) ULTIMATE VFX MAPPING
                    // =================================================================

                    // 🛡️ TANK: Guillotine (Vertical Slash)
                    if (id === 'tr_u1') {
                        Covenant.spawnCovenantGuillotine(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8);
                        return;
                    }
                    // 🛡️ TANK: Undead Army (Necrotic Ground)
                    if (id === 'tr_u2') {
                        Covenant.spawnCovenantUndeadArmy(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.5);
                        return;
                    }
                    // ⚔️ WARRIOR: Ragnarok (Magma Eruption)
                    if (id === 'wr_u1') {
                        Covenant.spawnCovenantRagnarok(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.9);
                        return;
                    }
                    // ⚔️ WARRIOR: Blood Storm (Tornado)
                    if (id === 'wr_u2') {
                        Covenant.spawnCovenantBloodStorm(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6);
                        return;
                    }
                    // 🏹 RANGER: Final Blast (Railgun)
                    if (id === 'rr_u1') {
                        // Railgun visual handled mostly by projectile trail, but here's the impact
                        Covenant.spawnCovenantRailgun(vfx, event.pos.x - 200, event.pos.y, event.pos.x, event.pos.y, color);
                        camera.addTrauma(0.8);
                        return;
                    }
                    // 🏹 RANGER: Nuke (Mushroom Cloud)
                    if (id === 'rr_u2') {
                        Generic.spawnTacticalNuke(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8); 
                        return;
                    }
                    // 🔮 MAGE: Meteor (Falling Rock)
                    if (id === 'mr_u1') {
                        Generic.spawnMeteorImpact(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6);
                        return;
                    }
                    // 🔮 MAGE: Finger of Death (Already handled in Beam, but here for AOE fallback)
                    if (id === 'mr_u2') {
                        Generic.spawnDeathRay(vfx, event.pos.x, event.pos.y - 200, event.pos.x, event.pos.y, color);
                        camera.addTrauma(0.7);
                        return;
                    }
                    // ⚕️ SUPPORT: Soul Link (Void Web)
                    if (id === 'sr_u1') {
                        Covenant.spawnCovenantSoulLink(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3);
                        return;
                    }
                    // ⚕️ SUPPORT: Ancestral Spirit (Rising Spirits)
                    if (id === 'sr_u2') {
                        Covenant.spawnCovenantAncestors(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3);
                        return;
                    }

                    // Generic Grid Reaction
                    affectedHexes.forEach(h => {
                        if (engine.map.isValid(h.q, h.r)) {
                            const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                            const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                            const tileVisualY = tilePos.y - hHeight;
                            const dist = HexUtils.dist(centerHex, h);
                            const delay = dist * 0.06;

                            Generic.spawnGridImpact(vfx, tilePos.x, tileVisualY, event.color || '#fff', Team.BLUE, delay);
                        }
                    });
                }

                // Generic Fallback
                Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 0, 20, event.color || '#fff', 2.0, 0.6, 'SPARK');
                Generic.addImpact(vfx, event.pos.x, visualGroundY, 0, event.color || '#fff', 'BLAST', 0.5);
                Generic.spawnShockwave(vfx, event.pos.x, visualGroundY, event.color || '#fff', 0.6);
                camera.addTrauma(0.25); 
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                } else {
                    const hitColor = event.skill?.color || '#fff';
                    Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 20, 8, hitColor, 1.0, 0.3, 'SPARK');
                }
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) Generic.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role);
                camera.addTrauma(0.05);
                break;

            case 'SPAWN':
                Generic.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                Generic.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                Generic.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                // Red Mage Death Finger (mr_u2) - Single Target Special
                if (event.skill?.id === 'mr_u2') {
                    Generic.spawnDeathRay(vfx, source.px, source.py - sH - 45, event.pos.x, visualGroundY - 30, event.color || '#be123c');
                    return;
                }

                Generic.spawnBeam(vfx, source.px, source.py - sH - 40, event.pos.x, visualGroundY - 30, event.color || '#fff');
                Generic.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';
                    Generic.spawnDirectionalImpact(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, event.color || '#fff', type);
                }
            }
        } else {
            Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
        }

        if (dmg > 50) camera.addTrauma(0.05); 
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.15); 

            // Death Finger target hit check
            if (skill && skill.id === 'mr_u2') {
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#000', 3.0, 0.5, 'SPARK');
                Generic.addImpact(vfx, event.pos.x, visualY, 20, '#be123c', 'BLAST', 0.5);
                Generic.spawnShockwave(vfx, event.pos.x, visualY, '#000', 0.5);
                return; 
            }

            // FACTION RITUAL (Ult Hit)
            if (faction === Team.BLUE) {
                // Remove Pillar fallback. Use pure explosion/shockwave.
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.5, 0.8, 'SPARK');
                Generic.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 0.8);
            } else {
                // Red faction uses Blood Ritual
                Generic.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            if (skill && skill.id === 'wr_u1') { // Ragnarok Hit
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#991b1b', 2.0, 1.0, 'DEBRIS');
                Generic.addImpact(vfx, event.pos.x, visualY, 0, '#ef4444', 'BLAST', 0.8);
                camera.addTrauma(0.5);
            } 

        } else {
            // Standard Hits
            if (visualType === 'SMASH') {
                Generic.addImpact(vfx, event.pos.x, centerVisualY, 0, color, 'SHOCKWAVE', 0.4);
                Generic.spawnExplosion(vfx, event.pos.x, centerVisualY, 0, 8, color, 0.5, 0.6, 'SHARD'); 
            } 
            else if (visualType === 'SLASH') {
                if (source) {
                    const dx = event.pos.x - source.px;
                    const dy = event.pos.y - source.py;
                    const len = Math.sqrt(dx*dx + dy*dy) || 1;
                    Generic.spawnDirectionalImpact(vfx, event.pos.x, visualY, 30, dx/len, dy/len, color, 'PHYSICAL');
                } else {
                    Generic.spawnExplosion(vfx, event.pos.x, visualY, 30, 8, color, 1.5, 0.4, 'SPARK');
                }
            }
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                Generic.addImpact(vfx, event.pos.x, visualY, 20, color, 'BLAST', 0.5);
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 20, 5, color, 0.5, 1.0, 'SMOKE');
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 20, 8, '#fff', 1.0, 0.3, 'SPARK');
            }
            else {
                Generic.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.4);
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 2.0, 0.4, 'SPARK');
            }
        }
    }
}

import { Agent, GameEngine } from "../game";
import { Projectile, Skill, BattleField } from "../../types";
import { ProjectileSystem } from "./combat/ProjectileSystem";
import { SkillResolutionSystem } from "./combat/SkillResolutionSystem";
import { HexUtils, Vector } from "../utils";
import { HEX_SIZE } from "../../constants";
import * as GenericVFX from "./vfx/spawners/generic";

const FIELD_TICK_RATE = 0.5; // Damage every 0.5s

export class CombatSystem {
    public projectileSystem: ProjectileSystem;
    public skillResolution: SkillResolutionSystem;

    constructor() {
        this.projectileSystem = new ProjectileSystem();
        this.skillResolution = new SkillResolutionSystem();
    }

    // Proxy for accessors to maintain GameEngine compatibility
    get projectiles(): Projectile[] { return this.projectileSystem.projectiles; }
    set projectiles(v: Projectile[]) { this.projectileSystem.projectiles = v; }

    public reset() {
        this.projectileSystem.projectiles = [];
    }

    public update(dt: number, engine: GameEngine) {
        // 1. Casting Updates (Logic)
        engine.agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.castingSkillIdx !== -1) {
                this.skillResolution.updateCasting(a, dt, engine);
            }
        });

        // 2. Projectile Physics & Impacts
        this.projectileSystem.update(dt, engine, this.skillResolution);

        // 3. Update Persistent Ground Fields (Poison clouds, etc.)
        this.updateFields(dt, engine);

        // 4. Update Field Physics (Gravity/Suction - Per Frame)
        this.updateFieldPhysics(dt, engine);
    }

    private updateFields(dt: number, engine: GameEngine) {
        // Reverse iterate to remove expired fields safely
        for (let i = engine.fields.length - 1; i >= 0; i--) {
            const field = engine.fields[i];

            field.duration -= dt;
            field.tickTimer -= dt;

            // Handle Logic Tick
            if (field.tickTimer <= 0) {
                field.tickTimer = FIELD_TICK_RATE;
                this.resolveFieldTick(field, engine);
            }

            // Expiry
            if (field.duration <= 0) {
                engine.fields.splice(i, 1);
            }
        }
    }

    private updateFieldPhysics(dt: number, engine: GameEngine) {
        // Optimized physics loop for continuous effects (Black Hole / Gravity)
        // This runs every frame, unlike damage ticks.

        for (const field of engine.fields) {
            // Only 'PULL' fields generate gravity
            if (field.skill.ccType !== 'PULL' && field.skill.ccType2 !== 'PULL') continue;

            const rPxSq = field.radiusPx * field.radiusPx;
            const pullForce = (field.skill.ccForce || 5) * 150; // Base force multiplier

            engine.agents.forEach(agent => {
                if (agent.hp <= 0 || agent.banished || agent.team === field.team) return;

                const dx = field.pos.x - agent.px;
                const dy = field.pos.y - agent.py;
                const distSq = dx * dx + dy * dy;

                if (distSq <= rPxSq && distSq > 100) { // Don't pull if already at center (jitter fix)
                    // 1. GRAVITY: Apply force towards center
                    // We calculate a normalized vector
                    const dist = Math.sqrt(distSq);
                    const nx = dx / dist;
                    const ny = dy / dist;

                    // Apply continuous acceleration
                    // We rely on PhysicsEngine damping to prevent infinite speed
                    agent.physics.vx += nx * pullForce * dt;
                    agent.physics.vy += ny * pullForce * dt;

                    // 2. EVENT HORIZON: Massive Slow
                    // If you are in a black hole, you can barely walk away
                    agent.moveSpeedMult = 0.3; // 70% Slow override
                }
            });
        }
    }

    private resolveFieldTick(field: BattleField, engine: GameEngine) {
        const source = engine.agents.find(a => a.id === field.sourceId);

        const rPx = field.radiusPx * field.radiusPx;

        engine.agents.forEach(agent => {
            if (agent.hp <= 0 || agent.banished || agent.team === field.team) return; // Friendly fire OFF

            const dx = agent.px - field.pos.x;
            const dy = agent.py - field.pos.y;
            const distSq = dx * dx + dy * dy;

            if (distSq <= rPx) {
                // Determine damage. 
                // Use ccForce if available, otherwise 20% of power.
                // For Black Holes, damage is usually low per tick but high utility.
                const damage = (field.skill.power * 0.2) || 10;

                // Direct HP modification
                agent.hp = Math.max(0, agent.hp - damage);

                // Add tiny floating text
                engine.events.push({ 
                    type: 'DAMAGE', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: -Math.floor(damage), 
                    color: field.color 
                });

                // Apply Status Effect if applicable (Refresh DoT timer)
                // Note: We don't apply PULL here, that's handled in updateFieldPhysics
                if (field.skill.ccType && field.skill.ccType !== 'PULL') {
                    this.skillResolution.applyCC(
                        source || agent, agent, field.skill, 
                        field.skill.ccType, 1.0, 0, undefined, engine
                    );
                }
            }
        });
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        this.projectileSystem.spawnProjectile(source, skill, engine);
    }

    public spawnField(source: Agent, skill: Skill, pos: {x: number, y: number}, engine: GameEngine) {
        // Convert radius to pixels
        const radiusGrid = skill.aoeRadius || 1;
        const radiusPx = radiusGrid * HEX_SIZE * 1.5; // Approximation for coverage

        // Determine Duration: Use ccDur if > 0, else default 5s
        const duration = (skill.ccDur && skill.ccDur > 0) ? skill.ccDur : 5.0;

        // Calculate Q, R from Pos for Grid Lookup
        const hex = HexUtils.fromPx(pos.x, pos.y, engine.mapConfig);

        const field: BattleField = {
            id: Math.random().toString(36).substr(2, 5),
            pos: pos,
            q: hex.q, 
            r: hex.r, 
            radius: radiusGrid,
            radiusPx: radiusPx,
            skill: skill,
            sourceId: source.id,
            team: source.team,
            duration: duration,
            tickTimer: 0, // Tick immediately on spawn
            visualType: skill.visual || 'SMOKE',
            color: skill.color
        };

        engine.fields.push(field);

        // Spawn Visuals immediately (Just initial puff, persistent zone handled by ZoneRenderer)
        GenericVFX.spawnLingeringField(engine.renderer!.vfx, pos.x, pos.y, skill.color, 'SMOKE', 1.0, 0);
    }
}

import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../../types";
import { SpriteManager } from "../../../sprites";
import { THEME_IMPERIAL, THEME_COVENANT } from "../../../../constants";

// =========================================================================================
// 🛠️ GENERIC / SHARED UTILS (Base Building Blocks)
// =========================================================================================

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE' | 'SHARD' | 'DEBRIS') {
    const safeCount = Math.min(type === 'SPARK' ? 12 : 6, count);
    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        const spd = Math.random() * 200 * speed;
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd; p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 200 + 100) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4); p.maxLife = life;
        p.color = color;
        p.size = type === 'SPARK' ? Math.random() * 4 + 3 : Math.random() * 20 + 20;
        if (type === 'SHARD' || type === 'DEBRIS') p.size = 5 + Math.random() * 5;
        p.type = type; p.delay = 0;
        system.state.particles.push(p);
    }
}

export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'RING' | 'BLAST' | 'SHOCKWAVE', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 30; // Default size
    p.type = type;
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0; p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; p.color = color; p.size = 4; p.type = 'BEAM'; p.delay = 0;
    system.state.particles.push(p);
}

export function spawnDeathRay(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
