        const speed = 200 + Math.random() * 400;

        p.x = x; p.y = y; p.z = 20;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 100 + Math.random() * 200;

        p.life = 1.5; p.maxLife = 1.5;
        p.color = '#60a5fa'; // Blue Crystal
        p.size = 8 + Math.random() * 12;
        p.type = 'SHARD';
        p.rotation = Math.random();
        p.vRotation = Math.random() * 10;
        system.state.particles.push(p);
    }

    // 2. Ice Mist
    spawnExplosion(system, x, y, 10, 8, '#e0f2fe', 1.5, 1.0, 'SMOKE');

    // 3. Impact Ring
    addImpact(system, x, y, 10, color, 'RING', 0.8);
}

// 🏹 RANGER: STARFALL (rb_u2) - "AOE Rain"
// Concept: Multiple small beams striking random points in area.
export function spawnImperialStarfall(system: VFXSystem, x: number, y: number, color: string) {
    const radius = 150;
    // Spawn 10 stars falling
    for(let i=0; i<10; i++) {
        const p = system.state.getParticle();
        const angle = Math.random() * Math.PI * 2;
        const dist = Math.random() * radius;
        const px = x + Math.cos(angle) * dist;
        const py = y + Math.sin(angle) * dist;

        p.x = px; p.y = py; p.z = 800; // Sky
        p.vx = 0; p.vy = 0; p.vz = -1800; // Fall fast
        p.life = 0.5; p.maxLife = 0.5;
        p.color = '#fef08a'; // Star yellow
        p.size = 5;
        p.type = 'SPARK'; // Use spark as the star projectile
        p.delay = i * 0.1;
        system.state.particles.push(p);

        // Impact trigger (fake logic, just timing)
        setTimeout(() => {
            addImpact(system, px, py, 0, '#fff', 'BLAST', 0.3);
        }, (p.delay + 0.4) * 1000);
    }

    // Area Glow
    const area = system.state.getParticle();
    area.x = x; area.y = y; area.z = 0;
    area.life = 1.5; area.maxLife = 1.5;
    area.color = '#1e3a8a'; // Night blue
    area.size = radius * 1.5;
    area.type = 'DOMAIN';
    system.state.particles.push(area);
}

