// 🛡️ TANK: GUILLOTINE (tr_u1) - "Execute"
// Concept: A giant red blade slams down vertically.
export function spawnCovenantGuillotine(system: VFXSystem, x: number, y: number, color: string) {
    // 1. The Blade (Composed of particles)
    const height = 600;
    for(let i=0; i<15; i++) {
        const p = system.state.getParticle();
        p.x = x; 
        p.y = y + (i - 7) * 10; // Line width
        p.z = height + i * 20;

        p.vx = 0; p.vy = 0; p.vz = -2500; // Hyper fast drop
        p.life = 0.3; p.maxLife = 0.3;
        p.color = '#7f1d1d'; // Deep Blood
        p.size = 25; 
        p.type = 'SHARD'; 
        p.rotation = Math.PI / 2; // Vertical orientation
        p.delay = 0;
        system.state.particles.push(p);
    }

    // 2. Ground Blood Splash
    spawnExplosion(system, x, y, 10, 20, '#b91c1c', 1.5, 0.8, 'SMOKE'); 

