// ⚔️ WARRIOR: BLOOD STORM (wr_u2) - "Red Tornado"
// Concept: Particles spiraling upward in a funnel shape.
export function spawnCovenantBloodStorm(system: VFXSystem, x: number, y: number, color: string) {
    const layers = 10;
    for(let i=0; i<layers; i++) {
        // Create rings of particles
        const count = 6;
        for(let j=0; j<count; j++) {
            const p = system.state.getParticle();
            const angle = (j / count) * Math.PI * 2 + (i * 0.5); // Twisted
            const height = i * 25; // Stacked
            const radius = 30 + i * 10; // Funnel expands up

            p.x = x + Math.cos(angle) * radius;
            p.y = y + Math.sin(angle) * radius;
            p.z = height;

            // Orbital Velocity
            const speed = 300;
            p.vx = -Math.sin(angle) * speed;
            p.vy = Math.cos(angle) * speed;
            p.vz = 50; // Rise

            p.life = 2.0; p.maxLife = 2.0;
            p.color = '#b91c1c'; // Blood
            p.size = 20 + Math.random() * 10;
            p.type = 'SMOKE'; 
            p.delay = i * 0.1;
            system.state.particles.push(p);
        }
    }

    // Base suction
    addImpact(system, x, y, 0, '#7f1d1d', 'RING', 1.5);
}

// 🏹 RANGER: FINAL BLAST (rr_u1) - "Railgun"
// Concept: A thick, lingering horizontal beam with recoil rings.
export function spawnCovenantRailgun(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    // 1. The Beam
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 40; // Waist height
    p.targetX = tx; p.targetY = ty;
    p.life = 0.6; p.maxLife = 0.6; 
    p.color = '#000'; // Black core
    p.size = 20; // Thick
    p.type = 'DEATH_RAY'; 
    system.state.particles.push(p);

    // 2. Muzzle Flash Rings
    const dx = tx - sx; const dy = ty - sy;
    const angle = Math.atan2(dy, dx);

    for(let i=0; i<5; i++) {
        const dist = 50 + i * 80; // Rings along the path
        const px = sx + Math.cos(angle) * dist;
        const py = sy + Math.sin(angle) * dist;

        const r = system.state.getParticle();
        r.x = px; r.y = py; r.z = 40;
        r.vx = 0; r.vy = 0; r.vz = 0;
        r.life = 0.4; r.maxLife = 0.4;
        r.color = '#ef4444';
        r.size = 40;
        r.type = 'RING'; // Vertical ring? No, flat ring facing up is fine for abstract
        r.delay = i * 0.05;
        system.state.particles.push(r);
    }
}

// ⚕️ SUPPORT: SOUL LINK (sr_u1) - "Void Web"
// Concept: Dark void center with connecting purple chains.
export function spawnCovenantSoulLink(system: VFXSystem, x: number, y: number, color: string) {
