// Export the core version to maintain API compatibility for other VFX modules
export { getTransitionOffset };

// Helper: Determine if a color is "Chaos" (Red/Purple/Dark/Fire) vs "Order" (Blue/Gold/White)
// Updated to include Orange/Magma tones (#ea, #f9) and deep crimson (#be)
export function isChaosStyle(color: string): boolean {
    const c = color.toLowerCase();
    return c.includes('#dc') || c.includes('#ef') || c.includes('#b9') || c.includes('#45') || 
           c.includes('#7f') || c.includes('#4c') || c.includes('#a3') || c.includes('#58') || 
           c.includes('#1c') || c.includes('#ea') || c.includes('#f9') || c.includes('#be') ||
           c.includes('#78') || c.includes('#000');
}

// Helper: Ensure 6-digit hex for alpha appending logic
export function normalizeHex(color: string): string {
    if (color.startsWith('#') && color.length === 4) {
        return '#' + color[1] + color[1] + color[2] + color[2] + color[3] + color[3];
    }
    return color;
}

import { createCanvas } from "./CanvasUtils";
import { isChaosStyle } from "../systems/vfx/utils";

// Dimensions
const VFX_SIZE = 64;
const MAGIC_CIRCLE_SIZE = 256; // Increased resolution for crisp runes
const PROJ_WIDTH = 96;
const PROJ_HEIGHT = 64;
const BLAST_WIDTH = 128;
const BLAST_HEIGHT = 64;
const FOG_SIZE = 256;

export const VFXFactory = {

    generateGlowOrb(color: string, size: number = VFX_SIZE): HTMLCanvasElement {
         const { canvas, ctx } = createCanvas(size, size);
         const cx = size / 2;
         const cy = size / 2;
         const r = size / 2;
         const isChaos = isChaosStyle(color);

         // Clear previous styles
         ctx.globalCompositeOperation = 'source-over';

         if (isChaos) {
             // CHAOS: Unstable Plasma Core
             // Darker center, jagged edges
             const grad = ctx.createRadialGradient(cx, cy, r*0.1, cx, cy, r);
             grad.addColorStop(0, '#ffffff');
             grad.addColorStop(0.3, color);
             grad.addColorStop(0.6, 'rgba(0,0,0,0.8)'); // Dark halo
             grad.addColorStop(1, 'transparent');

             ctx.fillStyle = grad;

             // Jagged star shape
             ctx.beginPath();
             const spikes = 12;
             for(let i=0; i<spikes*2; i++) {
                 const angle = (i / (spikes*2)) * Math.PI * 2;
                 const rad = (i % 2 === 0) ? r : r * 0.4;
                 const x = cx + Math.cos(angle) * rad;
                 const y = cy + Math.sin(angle) * rad;
                 if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
             }
             ctx.closePath();
             ctx.fill();

         } else {
             // ORDER: Perfect Lens Flare / Star
             // Soft gaussian feel with distinct cross spike
             const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
             grad.addColorStop(0, '#ffffff');        
             grad.addColorStop(0.15, color);          
             grad.addColorStop(0.5, color);          
             grad.addColorStop(1, 'rgba(0,0,0,0)');  

             ctx.fillStyle = grad;
             ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.fill();

             // Cross flare
             ctx.fillStyle = '#fff';
             ctx.globalAlpha = 0.8;
             ctx.beginPath();
             ctx.ellipse(cx, cy, r * 0.8, r * 0.1, 0, 0, Math.PI*2);
             ctx.ellipse(cx, cy, r * 0.1, r * 0.8, 0, 0, Math.PI*2);
             ctx.fill();
         }

         return canvas;
    },

    generateFogCloud(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(FOG_SIZE, FOG_SIZE);
        const cx = FOG_SIZE / 2;
        const cy = FOG_SIZE / 2;

        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, FOG_SIZE / 2);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.15; // Very subtle

        // Organic irregular blobs
        for(let i=0; i<12; i++) {
            const angle = Math.random() * Math.PI * 2;
            const dist = Math.random() * (FOG_SIZE * 0.3);
            const r = FOG_SIZE * (0.15 + Math.random() * 0.2);

            ctx.beginPath(); 
            ctx.ellipse(
                cx + Math.cos(angle)*dist, 
                cy + Math.sin(angle)*dist, 
                r, r * 0.6, 
                Math.random() * Math.PI, 
                0, Math.PI*2
            ); 
            ctx.fill();
        }

        return canvas;
    },

    generateMagicCircle(color: string, isUlt: boolean): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(MAGIC_CIRCLE_SIZE, MAGIC_CIRCLE_SIZE);
        const cx = MAGIC_CIRCLE_SIZE / 2;
        const cy = MAGIC_CIRCLE_SIZE / 2;
        const radius = MAGIC_CIRCLE_SIZE * 0.45;
        const isChaos = isChaosStyle(color);

        ctx.strokeStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 15;
        ctx.lineWidth = 3;
        ctx.lineJoin = 'round';

        if (isChaos) {
            // CHAOS: Jagged, Ancient Runes, Broken Circles
            // Outer Ring (Broken)
            ctx.beginPath();
            for(let i=0; i<8; i++) {
                const start = (i / 8) * Math.PI * 2;
                ctx.arc(cx, cy, radius, start + 0.1, start + (Math.PI*2/8) - 0.1);
            }
            ctx.stroke();

            // Inner Pentagram-ish mess
            ctx.lineWidth = 2;
            ctx.beginPath();
            const points = 7; 
            for(let i=0; i<=points; i++) {
                const angle = i * (Math.PI * 4 / points); // Skip points
                const r = radius * 0.8;
                const x = cx + Math.cos(angle) * r;
                const y = cy + Math.sin(angle) * r;
                if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            ctx.stroke();

            // Blood/Dark fill center
            const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, radius);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');
            ctx.globalAlpha = 0.2;
            ctx.fillStyle = grad;
            ctx.fill();

        } else {
            // ORDER: Geometric, Tech/Holy, Concentric
            // Outer double ring
            ctx.beginPath(); 
            ctx.arc(cx, cy, radius, 0, Math.PI * 2); 
            ctx.stroke();

            ctx.lineWidth = 1;
            ctx.beginPath(); 
            ctx.arc(cx, cy, radius * 0.95, 0, Math.PI * 2); 
            ctx.stroke();

            // Geometric Pattern (Square + Rotated Square)
            ctx.lineWidth = 2;
            const drawPoly = (sides: number, r: number, offset: number) => {
                ctx.beginPath();
                for (let i = 0; i <= sides; i++) {
                    const angle = offset + (i * Math.PI * 2) / sides;
                    const x = cx + Math.cos(angle) * r;
                    const y = cy + Math.sin(angle) * r;
                    if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                }
                ctx.closePath();
                ctx.stroke();
            };

            drawPoly(4, radius * 0.7, 0);
            drawPoly(4, radius * 0.7, Math.PI/4);

            // Inner Tech Circle
            ctx.beginPath(); ctx.arc(cx, cy, radius * 0.3, 0, Math.PI*2); ctx.stroke();

            // Runes (Dots)
            ctx.fillStyle = '#fff';
            for(let i=0; i<12; i++) {
                const a = (i/12) * Math.PI*2;
                const px = cx + Math.cos(a) * radius * 0.85;
                const py = cy + Math.sin(a) * radius * 0.85;
                ctx.beginPath(); ctx.arc(px, py, 2, 0, Math.PI*2); ctx.fill();
            }
        }

        return canvas;
    },

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(PROJ_WIDTH, PROJ_HEIGHT);
        const cx = PROJ_WIDTH / 2;
        const cy = PROJ_HEIGHT / 2;

        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        switch (visual) {
            case 'ARROW':
                // Energy Arrow
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.beginPath(); ctx.moveTo(10, cy); ctx.lineTo(80, cy); ctx.stroke();

                // Head
                ctx.fillStyle = color;
                ctx.beginPath();
                ctx.moveTo(90, cy); ctx.lineTo(70, cy - 8); ctx.lineTo(75, cy); ctx.lineTo(70, cy + 8);
                ctx.fill();
                // Fletching
                ctx.strokeStyle = color;
                ctx.beginPath();
                ctx.moveTo(20, cy); ctx.lineTo(10, cy - 6);
                ctx.moveTo(20, cy); ctx.lineTo(10, cy + 6);
                ctx.stroke();
                break;

            case 'FIREBALL':
            case 'BOMB':
                // Magma Core
                const coreGrad = ctx.createRadialGradient(cx+20, cy, 0, cx+20, cy, 20);
                coreGrad.addColorStop(0, '#fff');
                coreGrad.addColorStop(0.2, color);
                coreGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = coreGrad;
                ctx.beginPath(); ctx.arc(cx + 20, cy, 18, 0, Math.PI * 2); ctx.fill();
                break;

            case 'SLASH':
                // Crescent Wave
                ctx.translate(cx, cy);
                ctx.fillStyle = color;
                ctx.beginPath();
                ctx.arc(0, 0, 30, -Math.PI/2, Math.PI/2, false);
                ctx.bezierCurveTo(10, 20, 10, -20, 0, -30);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                break;

            case 'BOLT':
            case 'BEAM':
            default:
                // Magic Missile (Tapered slug)
                const grad = ctx.createLinearGradient(0, 0, PROJ_WIDTH, 0);
                grad.addColorStop(0, 'transparent');
                grad.addColorStop(0.5, color);
                grad.addColorStop(1, '#fff');

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.ellipse(cx, cy, 30, 8, 0, 0, Math.PI*2);
                ctx.fill();

                // Core
                ctx.fillStyle = '#fff';
                ctx.beginPath();
                ctx.ellipse(cx + 15, cy, 10, 3, 0, 0, Math.PI*2);
                ctx.fill();
                break;
        }

        return canvas;
    },

    generateBlastZone(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BLAST_WIDTH, BLAST_HEIGHT); 
        const cx = BLAST_WIDTH / 2;
        const cy = BLAST_HEIGHT / 2;
        const isChaos = isChaosStyle(color);

        ctx.scale(1, 0.5); // Perspective squash

        if (isChaos) {
            // Chaos: Cracks and Scorch
            ctx.fillStyle = '#1a0505'; // Dark scorch
            ctx.globalAlpha = 0.8;
            ctx.beginPath();
            ctx.arc(cx, cy*2, 40, 0, Math.PI*2);
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.6;
            ctx.beginPath();
            ctx.moveTo(cx, cy*2); ctx.lineTo(cx+30, cy*2-20);
            ctx.moveTo(cx, cy*2); ctx.lineTo(cx-20, cy*2+30);
            ctx.moveTo(cx, cy*2); ctx.lineTo(cx+10, cy*2+40);
            ctx.stroke();

        } else {
            // Order: Clean Energy Residual
            const grad = ctx.createRadialGradient(cx, cy * 2, 10, cx, cy * 2, 50);
            grad.addColorStop(0, color); 
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.4;
            ctx.beginPath(); ctx.arc(cx, cy * 2, 50, 0, Math.PI*2); ctx.fill();

            // Ring
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.3;
            ctx.beginPath(); ctx.arc(cx, cy * 2, 40, 0, Math.PI*2); ctx.stroke();
        }

        return canvas;
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../../constants";

// Optimization: Precompute Hex Polygon Offsets
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

// Procedural Noise function
function noise(q: number, r: number) {
    return Math.sin(q * 12.9898 + r * 78.233) * 43758.5453 - Math.floor(Math.sin(q * 12.9898 + r * 78.233) * 43758.5453);
}

export const TerrainRenderer = {

    drawBlockGeometry(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number // NEW: Time injection for animation
    ) {
        const BASE_THICKNESS = 12; 
        const topY = height; 

        // 1. Draw Side Faces (The Stack)
        const visibleIndices = [5, 0, 1];

        for (const i of visibleIndices) {
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            const x1 = x + c1.x;
            const y1_top = y + c1.y - topY;
            const x2 = x + c2.x;
            const y2_top = y + c2.y - topY;

            const y1_bottom = y + c1.y + BASE_THICKNESS;
            const y2_bottom = y + c2.y + BASE_THICKNESS;

            const grad = ctx.createLinearGradient(0, y - topY, 0, y + BASE_THICKNESS);
            const baseColor = (i === 0) ? theme.sideDark : theme.sideLight; 

            grad.addColorStop(0, baseColor);
            grad.addColorStop(0.7, baseColor);
            grad.addColorStop(1, '#020617');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.closePath();
            ctx.fill();

            // Layer Lines
            if (height > BLOCK_HEIGHT) {
                ctx.strokeStyle = 'rgba(0,0,0,0.2)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                for (let hStep = BLOCK_HEIGHT; hStep < height; hStep += BLOCK_HEIGHT) {
                    ctx.moveTo(x1, y + c1.y - hStep);
                    ctx.lineTo(x2, y + c2.y - hStep);
                }
                ctx.stroke();
            }

            ctx.strokeStyle = 'rgba(0,0,0,0.3)'; 
            ctx.lineWidth = 1; 
            ctx.stroke();
        }

        // 2. Draw Top Face (Base)
        this.traceTopFace(ctx, x, y - topY);

        // --- BASE MATERIAL ---
        // Static Gradient for base material to ensure solid look
        const topGrad = ctx.createLinearGradient(x - size, y - topY - size, x + size, y - topY + size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.3, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // --- DYNAMIC OVERLAYS (Texture 2.0) ---
        if (type === 'MAGMA') {
            // OPTIMIZATION: Flat fill instead of gradient
            const pulse = Math.sin(globalTime * 1.5 + x * 0.1 + y * 0.1); 
            if (pulse > 0.2) {
                const heatAlpha = (pulse - 0.2) * 0.3; 
                ctx.fillStyle = `rgba(239, 68, 68, ${heatAlpha})`; 
                ctx.fill();
            }

        } else if (type === 'ICE') {
            // Glossy Specular Band
            const bandPos = (globalTime * 50 + x + y) % (size * 4) - size * 2;

            ctx.save();
            ctx.clip(); // Clip to hex

            const specGrad = ctx.createLinearGradient(x - size, y - topY - size, x + size, y - topY + size);
            specGrad.addColorStop(0, 'transparent');
            specGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.2)'); // Subtle highlight
            specGrad.addColorStop(1, 'transparent');

            ctx.translate(bandPos * 0.5, 0); 
            ctx.fillStyle = specGrad;
            ctx.fill();
            ctx.restore();
        } 

        // 3. Rim Light
        ctx.lineCap = 'round';
        ctx.lineWidth = 2;
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.3)';
        ctx.globalAlpha = 0.6;

        ctx.beginPath();
        const c4 = HEX_CORNERS[4];
        const c3 = HEX_CORNERS[3];
        const c2 = HEX_CORNERS[2];

        ctx.moveTo(x + c4.x, y - topY + c4.y);
        ctx.lineTo(x + c3.x, y - topY + c3.y);
        ctx.lineTo(x + c2.x, y - topY + c2.y); 
        ctx.stroke();

        ctx.globalAlpha = 1.0;

        // 4. Subtle Outline
        ctx.lineWidth = 1;
        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        ctx.beginPath();
        ctx.moveTo(x + HEX_CORNERS[2].x, y - topY + HEX_CORNERS[2].y);
        ctx.lineTo(x + HEX_CORNERS[1].x, y - topY + HEX_CORNERS[1].y);
        ctx.lineTo(x + HEX_CORNERS[0].x, y - topY + HEX_CORNERS[0].y);
        ctx.lineTo(x + HEX_CORNERS[5].x, y - topY + HEX_CORNERS[5].y);
        ctx.lineTo(x + HEX_CORNERS[4].x, y - topY + HEX_CORNERS[4].y);
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        ctx.save();
        ctx.fillStyle = detailColor;
        ctx.strokeStyle = detailColor;

        const n = noise(q, r);
        const time = performance.now() / 1000;

        if (type === 'MAGMA') {
            // Charred Cracks
            const pulse = 0.5 + Math.sin(time + n * 10) * 0.5;

            ctx.strokeStyle = 'rgba(40, 5, 5, 0.7)'; // Dark crack
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(cx - 12, cy + 5);
            ctx.lineTo(cx - 5, cy - 2);
            ctx.lineTo(cx + 8, cy + 3);
            ctx.lineTo(cx + 15, cy - 5);
            ctx.stroke();

            if (pulse > 0.8) {
                ctx.fillStyle = '#ef4444';
                ctx.globalAlpha = (pulse - 0.8) * 3; 
                ctx.beginPath(); ctx.arc(cx - 5, cy - 2, 2, 0, Math.PI*2); ctx.fill();
            }

        } else if (type === 'VOID') {
            // Digital Circuitry
            ctx.globalAlpha = 0.3;

            if (n > 0.3) {
                ctx.fillStyle = '#38bdf8';
                ctx.beginPath(); ctx.arc(cx, cy, 2, 0, Math.PI*2); ctx.fill();

                ctx.strokeStyle = '#38bdf8';
                ctx.lineWidth = 1;
                ctx.beginPath();
                if (n > 0.6) { ctx.moveTo(cx, cy); ctx.lineTo(cx + 15, cy - 8); }
                if (n < 0.4) { ctx.moveTo(cx, cy); ctx.lineTo(cx - 15, cy + 8); }
                ctx.stroke();
            }

            const packetTime = (time * 0.5 + n) % 2; 
            if (packetTime < 1.0) {
                ctx.globalAlpha = 1.0 - packetTime; 
                ctx.fillStyle = '#bae6fd';
                const px = cx + (Math.cos(n * 10) * 20 * packetTime);
                const py = cy + (Math.sin(n * 10) * 10 * packetTime);
                ctx.fillRect(px, py, 2, 2);
            }

        } else if (type === 'FOREST') {
            // Moving Grass
            ctx.globalAlpha = 0.6;
            const tufts = Math.floor(n * 3) + 2;

            for(let i=0; i<tufts; i++) {
                const ox = (noise(q+i, r) - 0.5) * 20;
                const oy = (noise(r, q+i) - 0.5) * 12;

                const wind = Math.sin(time * 2 + cx * 0.05 + i) * 3;

                ctx.beginPath();
                ctx.moveTo(cx + ox, cy + oy);
                ctx.quadraticCurveTo(cx + ox - 2 + wind, cy + oy - 6, cx + ox - 4 + wind * 1.5, cy + oy - 8);
                ctx.moveTo(cx + ox, cy + oy);
                ctx.quadraticCurveTo(cx + ox + 2 + wind, cy + oy - 5, cx + ox + 4 + wind * 1.5, cy + oy - 7);

                ctx.lineWidth = 1.5;
                ctx.strokeStyle = i % 2 === 0 ? '#4ade80' : '#22c55e';
                ctx.stroke();
            }

        } else if (type === 'ICE') {
            ctx.globalAlpha = 0.3;
            ctx.fillStyle = '#fff';
            if (n > 0.4) {
                ctx.beginPath();
                ctx.moveTo(cx - 15, cy + 2);
                ctx.lineTo(cx + 5, cy - 8);
                ctx.lineTo(cx + 15, cy - 4);
                ctx.lineTo(cx - 5, cy + 8);
                ctx.fill();
            }

        } else if (type === 'DESERT') {
            // Moving Sand Ripples
            ctx.globalAlpha = 0.2;
            ctx.strokeStyle = '#92400e';
            ctx.lineWidth = 2;

            const offset = (time * 5) % 20; 

            ctx.beginPath();
            for(let i=0; i<2; i++) {
                const yBase = cy - 10 + i * 15;
                const shift = offset + (n * 20); 
                const xStart = cx - 15 + (shift % 10);

                ctx.moveTo(xStart, yBase);
                ctx.quadraticCurveTo(xStart + 10, yBase - 3, xStart + 20, yBase);
            }
            ctx.stroke();
        }

        ctx.restore();
    },

    traceTopFace(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }
};

