            const offset = (time * 5) % 20; 

            ctx.beginPath();
            for(let i=0; i<2; i++) {
                const yBase = cy - 10 + i * 15;
                const shift = offset + (n * 20); 
                const xStart = cx - 15 + (shift % 10);

                ctx.moveTo(xStart, yBase);
                ctx.quadraticCurveTo(xStart + 10, yBase - 3, xStart + 20, yBase);
            }
            ctx.stroke();
        }

        ctx.restore();
    },

    // =================================================================================
    // ☢️ FIELD EFFECTS (Active Zones)
    // =================================================================================

    // Helper to determine visual ID from Skill Data
    resolveFieldVisual(skill: Skill, defaultVisual: string): string {
        // High Priority Logic Overrides
        if (skill.ccType === 'PULL' || skill.name.includes("黑洞") || skill.name.includes("事件視界")) {
            return 'BLACK_HOLE';
        } 
        if (skill.visual === 'FIREBALL' || skill.name.includes("烈焰") || skill.name.includes("燃燒") || skill.name.includes("隕石")) {
            return 'BURNING_GROUND';
        }
        if (skill.name.includes("毒") || skill.name.includes("腐化") || skill.name.includes("瘟疫")) {
            return 'POISON_SWAMP';
        }
        if (skill.name.includes("雪") || skill.name.includes("冰") || skill.name.includes("凍")) {
            return 'FROST_FIELD';
        }
        return defaultVisual || 'GENERIC_FIELD';
    },

    drawFieldEffect(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        visual: string, 
        color: string,
        time: number, 
        traceFn: () => void
    ) {
        ctx.save();

        if (visual === 'BLACK_HOLE' || visual === 'PULL') {
            // --- GRAVITY / VOID ---
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;

            const seed = Math.abs(x + y * 13);

            // Vertical Suction Lines
            for(let i=0; i<2; i++) {
                const offsetX = ((seed + i*50) % 20) - 10;
                const speed = 20 + (seed % 10);
                const h = 40;
                const py = (time * speed + i * 20) % h;
                const alpha = 1 - Math.abs((py - h/2) / (h/2));

                ctx.globalAlpha = alpha * 0.5;
                ctx.beginPath();
                ctx.moveTo(x + offsetX, y - h + py);
                ctx.lineTo(x + offsetX, y - h + py + 5);
                ctx.stroke();
            }

            ctx.globalAlpha = 0.3;
            traceFn();
            ctx.stroke();

        } else if (visual === 'BURNING_GROUND' || visual === 'FIREBALL') {
            // --- MAGMA / FIRE ---
            const seed = Math.abs(x + y);
            const emberY = (time * 60 + seed) % 50;
            const emberAlpha = 1 - (emberY / 50);

            ctx.globalCompositeOperation = 'lighter';
            ctx.fillStyle = '#fbbf24'; // Ember Gold
            ctx.globalAlpha = emberAlpha;

            ctx.beginPath();
            ctx.arc(x + Math.sin(time*3 + seed)*5, y - emberY + 10, 1.5, 0, Math.PI*2);
            ctx.fill();

            // Heat Haze
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.2 + Math.sin(time*5 + x)*0.1;
            traceFn();
            ctx.stroke();

        } else if (visual === 'FROST_FIELD') {
            // --- ICE / SNOW ---
            const seed = Math.abs(x * 11 + y);
            ctx.globalCompositeOperation = 'screen';
            ctx.fillStyle = '#fff';

            // Sparkling Ice Crystals
            const sparkle = Math.sin(time * 5 + seed) > 0.8;
            if (sparkle) {
                const sx = x + (Math.sin(seed) * 15);
                const sy = y + (Math.cos(seed) * 8);
                ctx.globalAlpha = 0.8;
                ctx.beginPath(); 
                ctx.moveTo(sx, sy-3); ctx.lineTo(sx, sy+3);
                ctx.moveTo(sx-3, sy); ctx.lineTo(sx+3, sy);
                ctx.stroke();
            }

            ctx.fillStyle = color;
            ctx.globalAlpha = 0.15;
            traceFn(); 
            ctx.fill();

        } else {
            // --- GENERIC / POISON / SWAMP ---
            // Bubbles
            const seed = Math.abs(x * 7 + y * 13); 
            const count = (seed % 2) + 1;

            ctx.globalCompositeOperation = 'lighter';
            ctx.fillStyle = color;

            for(let i=0; i<count; i++) {
                const speed = 15 + (seed % 10);
                const offset = (seed * i * 100);
                const bY = (time * speed + offset) % 40; 
                const bAlpha = 1 - (bY / 40); 
                const bX = Math.sin(time * 2 + offset) * 8;

                ctx.globalAlpha = bAlpha * 0.6;
                ctx.beginPath();
                ctx.arc(x + bX, y - bY + 15, 1.5 + i, 0, Math.PI * 2);
                ctx.fill();
            }

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.2;
            traceFn();
            ctx.stroke();
        }

        ctx.restore();
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../../constants";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";

// Optimization: Precompute Hex Polygon Offsets
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

export const TerrainRenderer = {

    drawBlockGeometry(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number
    ) {
        const BASE_THICKNESS = 12; 
        const topY = height; 

        // 1. Draw Side Faces (The Stack)
        const visibleIndices = [5, 0, 1];

        for (const i of visibleIndices) {
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            const x1 = x + c1.x;
            const y1_top = y + c1.y - topY;
            const x2 = x + c2.x;
            const y2_top = y + c2.y - topY;

            const y1_bottom = y + c1.y + BASE_THICKNESS;
            const y2_bottom = y + c2.y + BASE_THICKNESS;

            const grad = ctx.createLinearGradient(0, y - topY, 0, y + BASE_THICKNESS);
            const baseColor = (i === 0) ? theme.sideDark : theme.sideLight; 

            grad.addColorStop(0, baseColor);
            grad.addColorStop(0.7, baseColor);
            grad.addColorStop(1, '#020617');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.closePath();
            ctx.fill();

            // Layer Lines
            if (height > BLOCK_HEIGHT) {
                ctx.strokeStyle = 'rgba(0,0,0,0.2)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                for (let hStep = BLOCK_HEIGHT; hStep < height; hStep += BLOCK_HEIGHT) {
                    ctx.moveTo(x1, y + c1.y - hStep);
                    ctx.lineTo(x2, y + c2.y - hStep);
                }
                ctx.stroke();
            }

            ctx.strokeStyle = 'rgba(0,0,0,0.3)'; 
            ctx.lineWidth = 1; 
            ctx.stroke();
        }

        // 2. Draw Top Face (Base)
        this.traceTopFace(ctx, x, y - topY);

        // --- BASE MATERIAL ---
        const topGrad = ctx.createLinearGradient(x - size, y - topY - size, x + size, y - topY + size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.3, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // --- DYNAMIC OVERLAYS ---
        if (type === 'MAGMA') {
            const pulse = Math.sin(globalTime * 1.5 + x * 0.1 + y * 0.1); 
            if (pulse > 0.2) {
                const heatAlpha = (pulse - 0.2) * 0.3; 
                ctx.fillStyle = `rgba(239, 68, 68, ${heatAlpha})`; 
                ctx.fill();
            }
        } else if (type === 'ICE') {
            const bandPos = (globalTime * 50 + x + y) % (size * 4) - size * 2;
            ctx.save();
            ctx.clip(); 
            const specGrad = ctx.createLinearGradient(x - size, y - topY - size, x + size, y - topY + size);
            specGrad.addColorStop(0, 'transparent');
            specGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.2)'); 
            specGrad.addColorStop(1, 'transparent');
            ctx.translate(bandPos * 0.5, 0); 
            ctx.fillStyle = specGrad;
            ctx.fill();
            ctx.restore();
        } 

        // 3. Rim Light
        ctx.lineCap = 'round';
        ctx.lineWidth = 2;
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.3)';
        ctx.globalAlpha = 0.6;

        ctx.beginPath();
        const c4 = HEX_CORNERS[4];
        const c3 = HEX_CORNERS[3];
        const c2 = HEX_CORNERS[2];

        ctx.moveTo(x + c4.x, y - topY + c4.y);
        ctx.lineTo(x + c3.x, y - topY + c3.y);
        ctx.lineTo(x + c2.x, y - topY + c2.y); 
        ctx.stroke();

        ctx.globalAlpha = 1.0;

        // 4. Subtle Outline
        ctx.lineWidth = 1;
        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        ctx.beginPath();
        ctx.moveTo(x + HEX_CORNERS[2].x, y - topY + HEX_CORNERS[2].y);
        ctx.lineTo(x + HEX_CORNERS[1].x, y - topY + HEX_CORNERS[1].y);
        ctx.lineTo(x + HEX_CORNERS[0].x, y - topY + HEX_CORNERS[0].y);
        ctx.lineTo(x + HEX_CORNERS[5].x, y - topY + HEX_CORNERS[5].y);
        ctx.lineTo(x + HEX_CORNERS[4].x, y - topY + HEX_CORNERS[4].y);
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        // Delegate to SurfaceAssets to keep Renderer pure
        SurfaceAssets.drawTexture(ctx, cx, cy, q, r, type, detailColor, performance.now() / 1000);
    },

    traceTopFace(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }
};

import { TerrainRenderer } from "./TerrainRenderer";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";

export const ZoneRenderer = {

    draw(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Center of the tile face
        size: number,
        color: string,
        type: 'CAST' | 'FIELD',
        visual: string,
        progress: number, 
        globalTime: number,
        dist: number, 
        maxRadius: number
    ) {
        // Use trace for outlines, but avoid fills!
        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        if (type === 'CAST') {
            this.drawRipple(ctx, x, y, size, color, visual, progress, dist, maxRadius, trace);
        } else if (type === 'FIELD') {
            // Delegated to SurfaceAssets for consistent VFX library usage
            SurfaceAssets.drawFieldEffect(ctx, x, y, visual, color, globalTime, trace);
        }
    },

    // 1. RIPPLE EFFECT (The Wave)
    drawRipple(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, 
        color: string, 
        visual: string,
        progress: number, 
        dist: number, 
        maxRadius: number,
        traceFn: () => void
    ) {
        // Calculate radius
        const currentRadius = maxRadius * (progress * 1.2); 
        const waveWidth = 1.5; 
        const distDiff = currentRadius - dist;

        ctx.save();

        // A. WAVE FRONT (Only Outline)
        if (distDiff >= 0 && distDiff < waveWidth) {
            const intensity = distDiff / waveWidth; 
            const alpha = Math.sin(intensity * Math.PI); 

            ctx.globalCompositeOperation = 'lighter';

            // Just a thick glowy outline, NO FILL
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.globalAlpha = alpha;
            traceFn();
            ctx.stroke();

            // Thin white inner
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            traceFn();
            ctx.stroke();
        }

        // B. RESIDUAL GROUND (Faint Marks)
        if (dist < currentRadius && dist <= maxRadius) {
            const fade = 1.0 - progress;
            ctx.globalCompositeOperation = 'source-over';
            ctx.globalAlpha = 0.4 * fade;
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;

            if (visual === 'SMASH' || visual === 'BOMB') {
                // Small cracks
                ctx.beginPath();
                ctx.moveTo(x - 5, y); ctx.lineTo(x + 2, y + 2); ctx.lineTo(x + 5, y - 2);
                ctx.stroke();
            } else if (visual === 'ARROW') {
                // Crosshair corners
                ctx.beginPath();
                ctx.moveTo(x - 5, y - 5); ctx.lineTo(x - 2, y - 5);
                ctx.moveTo(x + 5, y + 5); ctx.lineTo(x + 2, y + 5);
                ctx.stroke();
            }
        }

        ctx.restore();
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils, getTransitionOffset } from "../utils";
import { Hex, Skill, Projectile } from "../../types";
import { RenderList, RenderOpType } from "../renderers/RenderList";
import { SurfaceAssets } from "../graphics/SurfaceAssets";

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
}

// Lightweight struct to track Zones (Both Instant Casts & Persistent Fields)
interface ZoneSource {
    type: 'CAST' | 'FIELD';
    q: number;
    r: number;
    radius: number; // Hex radius
    radiusSq: number; // For fast distance check (cached)
    color: string;
    visual: string;
    progress: number; // 0-1 for CAST, 1.0 for FIELD
}

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_ANCHOR_Y = 95; 

export class GridSystem {
    // Cache
    private _tileCache: CachedTile[] = [];
    private _lastMapVersion: number = -1;

    // Optimization: Reuse buffers
    private _activeZones: ZoneSource[] = [];
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public reset() {
        this._activeZones.length = 0;
        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        // Force tile cache rebuild on next frame just in case
        this._lastMapVersion = -1; 
    }

    getTerrainHeight(q: number, r: number, engine?: GameEngine): number {
        if(engine) return engine.map.getTerrainHeight(q, r);
        return 0; 
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileCache.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileCache = [];
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            this._tileCache.push({ q, r, px: pos.x, py: pos.y, h });
        });
    }

    getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine): Hex | null {
        this.ensureCache(engine);
        const limit = HEX_SIZE * 2; 

        // Find closest tile visual center
        let bestTile: CachedTile | null = null;
        let bestDist = Infinity;

        for (const tile of this._tileCache) {
            const visualY = tile.py - tile.h;
            const dist = Math.abs(wx - tile.px) + Math.abs(wy - visualY);
            if (dist < limit && dist < bestDist) { 
                bestDist = dist;
                bestTile = tile;
            }
        }

        if (bestTile) {
            const testHex = HexUtils.fromPx(wx, wy + bestTile.h, engine.mapConfig);
            const rounded = HexUtils.round(testHex.q, testHex.r);
            if (rounded.q === bestTile.q && rounded.r === bestTile.r) {
                return { q: bestTile.q, r: bestTile.r };
            }
        }
        return null;
    }

    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];
        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;
            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = engine.map.getTerrainHeight(a.q, a.r);
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    if (nPx.y > uPx.y) {
                         const nHeight = engine.map.getTerrainHeight(n.q, n.r);
                         if (nHeight > uHeight) {
                             occluded.push(a);
                             break;
                         }
                    }
                }
            }
        });
        return occluded;
    }

    submitRenderables(
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        this.ensureCache(engine);

        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // Reset buffers
        this._activeZones.length = 0;
        this._unitPresence.clear();
        this._unitVisualStatus.clear();

        // 1. COLLECT ZONES (Casting & Fields)

        // A. Casting Agents (Telegraphs)
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);

                if (a.stunTimer <= 0 && a.silenceTimer <= 0 && !a.banished && a.castingSkillIdx !== -1) {
                    const s = a.skills[a.castingSkillIdx];
                    if (s && s.type === 'AOE') {
                        let tq = a.q, tr = a.r;
                        if (a.targetHex) { tq = a.targetHex.q; tr = a.targetHex.r; }
                        else if (a.target) { tq = a.target.q; tr = a.target.r; }

                        const progress = 1 - (a.castTimer / s.cast);
                        const radius = (s.aoeRadius || 1);

                        this._activeZones.push({
                            type: 'CAST',
                            q: tq, r: tr,
                            radius: radius,
                            radiusSq: radius + 0.5, 
                            color: s.color,
                            visual: s.visual || 'BOLT',
                            progress: progress
                        });
                    }
                }
            }
        }

        // B. Persistent Fields (Poison, Gravity, etc.)
        for (const f of engine.fields) {
            // Decoupled Visual Logic: Ask the Asset Library what this should look like
            const visual = SurfaceAssets.resolveFieldVisual(f.skill, f.visualType);

            this._activeZones.push({
                type: 'FIELD',
                q: f.q, r: f.r, 
                radius: f.radius,
                radiusSq: f.radius + 0.5,
                color: f.color,
                visual: visual,
                progress: 1.0 
            });
        }

        // 2. ITERATE TILES
        const PROJ_LIGHT_RADIUS_SQ = 1600; // 40^2

        for (const tile of this._tileCache) {
            const { q, r, px, py, h } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            const visualY = py + offset;

            if (visualY > py + 800) continue;

            const k = `${q},${r}`;

            // --- SUBMIT OBSTACLE ---
            const obstacleType = engine.obstacles.get(k);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = visualY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                op.ty = visualY - h - OBSTACLE_ANCHOR_Y; 
                op.ttype = obstacleType;
            }

            // --- SUBMIT TERRAIN ---

            let zoneInfo = undefined;

            // Iterate zones to find overlap
            for (const zone of this._activeZones) {
                const dist = (Math.abs(q - zone.q) + Math.abs(q + r - zone.q - zone.r) + Math.abs(r - zone.r)) / 2;

                if (dist <= zone.radius) {
                    zoneInfo = {
                        type: zone.type,
                        color: zone.color,
                        visual: zone.visual,
                        progress: zone.progress,
                        centerQ: zone.q, 
                        centerR: zone.r, 
                        radius: zone.radius,
                        dist: dist 
                    };
                    if (zone.type === 'FIELD') break; 
                }
            }

            let isRange = false;
            let rangeColor = '';

            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const bonus = Math.max(0, Math.floor((agentH - h) / BLOCK_HEIGHT));
                const effRange = hoveredSkill.range + bonus;
                const dist = (Math.abs(q - highlightAgent.q) + Math.abs(q + r - highlightAgent.q - highlightAgent.r) + Math.abs(r - highlightAgent.r)) / 2;

                if (dist <= effRange) {
                    isRange = true; 
                    rangeColor = hoveredSkill.color;
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;

            // UX UPDATE: Only show unit footprint indicators when NOT running (Planning phase)
            const hasUnit = !engine.isRunning && this._unitPresence.has(k);

            const specialStatus = this._unitVisualStatus.get(k);

            let lightColor = null;
            let lightIntensity = 0;

            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = visualY; 
            op.z = 0;

            op.tx = px; 
            op.ty = visualY; 
            op.th = h;
            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q;
            op.tr = r;

            // Overlays
            op.oStatus = specialStatus;
            op.oDanger = zoneInfo; 
            op.oLightCol = lightColor;
            op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange;
            op.oRangeCol = rangeColor;
            op.oHover = isHover;
            op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { Skill } from "../../types";
import { isChaosStyle } from "../systems/vfx/utils";

// Procedural Noise function reuse
function noise(q: number, r: number) {
    return Math.sin(q * 12.9898 + r * 78.233) * 43758.5453 - Math.floor(Math.sin(q * 12.9898 + r * 78.233) * 43758.5453);
}

// Precomputed Hex for Geometry
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

export const SurfaceAssets = {

    // =================================================================================
    // 🌍 TERRAIN TEXTURES (Static Details)
    // =================================================================================

    drawTexture(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        color: string,
        globalTime: number
    ) {
        ctx.save();
        ctx.fillStyle = color;
        ctx.strokeStyle = color;

        const n = noise(q, r);
        const time = globalTime;

        if (type === 'MAGMA') {
            const pulse = 0.5 + Math.sin(time + n * 10) * 0.5;
            ctx.strokeStyle = 'rgba(40, 5, 5, 0.7)'; 
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(cx - 12, cy + 5); ctx.lineTo(cx - 5, cy - 2);
            ctx.lineTo(cx + 8, cy + 3); ctx.lineTo(cx + 15, cy - 5);
            ctx.stroke();

            if (pulse > 0.8) {
                ctx.fillStyle = '#ef4444';
                ctx.globalAlpha = (pulse - 0.8) * 3; 
                ctx.beginPath(); ctx.arc(cx - 5, cy - 2, 2, 0, Math.PI*2); ctx.fill();
            }

        } else if (type === 'VOID') {
            ctx.globalAlpha = 0.3;
            if (n > 0.3) {
                ctx.fillStyle = '#38bdf8';
                ctx.beginPath(); ctx.arc(cx, cy, 2, 0, Math.PI*2); ctx.fill();
                ctx.strokeStyle = '#38bdf8';
                ctx.lineWidth = 1;
                ctx.beginPath();
                if (n > 0.6) { ctx.moveTo(cx, cy); ctx.lineTo(cx + 15, cy - 8); }
                if (n < 0.4) { ctx.moveTo(cx, cy); ctx.lineTo(cx - 15, cy + 8); }
                ctx.stroke();
            }
            const packetTime = (time * 0.5 + n) % 2; 
            if (packetTime < 1.0) {
                ctx.globalAlpha = 1.0 - packetTime; 
                ctx.fillStyle = '#bae6fd';
                const px = cx + (Math.cos(n * 10) * 20 * packetTime);
                const py = cy + (Math.sin(n * 10) * 10 * packetTime);
                ctx.fillRect(px, py, 2, 2);
            }

        } else if (type === 'FOREST') {
            ctx.globalAlpha = 0.6;
            const tufts = Math.floor(n * 3) + 2;
            for(let i=0; i<tufts; i++) {
                const ox = (noise(q+i, r) - 0.5) * 20;
                const oy = (noise(r, q+i) - 0.5) * 12;
                const wind = Math.sin(time * 2 + cx * 0.05 + i) * 3;
                ctx.beginPath();
                ctx.moveTo(cx + ox, cy + oy);
                ctx.quadraticCurveTo(cx + ox - 2 + wind, cy + oy - 6, cx + ox - 4 + wind * 1.5, cy + oy - 8);
                ctx.lineWidth = 1.5;
                ctx.strokeStyle = i % 2 === 0 ? '#4ade80' : '#22c55e';
                ctx.stroke();
            }

        } else if (type === 'ICE') {
            ctx.globalAlpha = 0.3; ctx.fillStyle = '#fff';
            if (n > 0.4) {
                ctx.beginPath();
                ctx.moveTo(cx - 15, cy + 2); ctx.lineTo(cx + 5, cy - 8);
                ctx.lineTo(cx + 15, cy - 4); ctx.lineTo(cx - 5, cy + 8);
                ctx.fill();
            }

        } else if (type === 'DESERT') {
            ctx.globalAlpha = 0.2; ctx.strokeStyle = '#92400e'; ctx.lineWidth = 2;
            const offset = (time * 5) % 20; 
            ctx.beginPath();
            for(let i=0; i<2; i++) {
                const yBase = cy - 10 + i * 15;
                const shift = offset + (n * 20); 
                const xStart = cx - 15 + (shift % 10);
                ctx.moveTo(xStart, yBase);
                ctx.quadraticCurveTo(xStart + 10, yBase - 3, xStart + 20, yBase);
            }
            ctx.stroke();
        }
        ctx.restore();
    },

    // =================================================================================
    // 🌀 CASTING RUNES (Unified Visuals for Units & Grid)
    // =================================================================================

    drawCastRune(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        t: number, 
        progress: number, 
        skillRadius: number, 
        type: 'BASIC' | 'ACTIVE' | 'ULT', 
        isAOE: boolean
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.globalCompositeOperation = 'lighter'; 

        // Target size logic
        const targetPx = isAOE ? (skillRadius * HEX_SIZE) : (HEX_SIZE * 1.5);
        const ease = 1 - Math.pow(1 - progress, 4); 
        const r = targetPx * ease;

        ctx.save();
        ctx.scale(1, ISO_SCALE_Y); // Isometric Projection

        if (type === 'ULT') {
            // --- ULTIMATE: GRAND OCTAGRAM ---
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2);
            ctx.lineWidth = 4; ctx.strokeStyle = color; ctx.globalAlpha = 0.8 * progress;
            ctx.stroke();

            ctx.save();
            ctx.rotate(t * 0.5);
            ctx.beginPath();
            const points = 8;
            const innerR = r * 0.85;
            for(let i=0; i<=points; i++) {
                const angle = i * (Math.PI * 2 / points);
                ctx.lineTo(Math.cos(angle) * innerR, Math.sin(angle) * innerR);
                const nextAngle = angle + (Math.PI / points);
                ctx.lineTo(Math.cos(nextAngle) * (innerR * 0.5), Math.sin(nextAngle) * (innerR * 0.5));
            }
            ctx.closePath();
            ctx.lineWidth = 2; ctx.strokeStyle = '#fff'; ctx.globalAlpha = 0.5 * progress; ctx.stroke();
            ctx.restore();

            // Beacon
            ctx.restore(); // Un-squash
            const beamH = 600;
            const beamGrad = ctx.createLinearGradient(0, 0, 0, -beamH);
            beamGrad.addColorStop(0, color); beamGrad.addColorStop(0.3, 'transparent');
            ctx.fillStyle = beamGrad; ctx.globalAlpha = 0.3 * progress;
            const w = r * 1.5;
            ctx.fillRect(-r, -beamH, w * 1.33, beamH);

        } else if (type === 'ACTIVE') {
            // --- ACTIVE: ROTATING SQUARE ---
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2);
            ctx.lineWidth = 2; ctx.strokeStyle = color; ctx.globalAlpha = 0.6 * progress;
            ctx.setLineDash([10, 5]);
            ctx.stroke();
            ctx.setLineDash([]);

            ctx.save();
            ctx.rotate(-t); 
            ctx.beginPath();
            const sqSize = r * 0.7;
            ctx.rect(-sqSize, -sqSize, sqSize*2, sqSize*2);
            ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.globalAlpha = 0.4 * progress;
            ctx.stroke();
            ctx.restore();

            ctx.restore(); // Un-squash
            const beamH = 200;
            const beamGrad = ctx.createLinearGradient(0, 0, 0, -beamH);
            beamGrad.addColorStop(0, color); beamGrad.addColorStop(1, 'transparent');
            ctx.fillStyle = beamGrad; ctx.globalAlpha = 0.2 * progress;
            ctx.fillRect(-r*0.5, -beamH, r, beamH);

        } else {
            // --- BASIC: BRACKETS ---
            ctx.save();
            ctx.rotate(t * 0.5);
            const bR = r * 0.8;
            const bLen = r * 0.3;
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.4 * progress;
            for(let i=0; i<4; i++) {
                ctx.rotate(Math.PI / 2);
                ctx.beginPath();
                ctx.moveTo(bR - bLen, -bR); ctx.lineTo(bR, -bR); ctx.lineTo(bR, -bR + bLen);
                ctx.stroke();
            }
            ctx.restore();
            ctx.restore(); 
        }

        ctx.restore(); // End Global
    },

    // =================================================================================
    // ☢️ FIELD EFFECTS (Active Zones)
    // =================================================================================

    resolveFieldVisual(skill: Skill, defaultVisual: string): string {
        if (skill.ccType === 'PULL' || skill.name.includes("黑洞") || skill.name.includes("事件視界")) return 'BLACK_HOLE';
        if (skill.visual === 'FIREBALL' || skill.name.includes("烈焰") || skill.name.includes("燃燒") || skill.name.includes("隕石")) return 'BURNING_GROUND';
        if (skill.name.includes("毒") || skill.name.includes("腐化") || skill.name.includes("瘟疫")) return 'POISON_SWAMP';
        if (skill.name.includes("雪") || skill.name.includes("冰") || skill.name.includes("凍")) return 'FROST_FIELD';
        return defaultVisual || 'GENERIC_FIELD';
    },

    drawFieldEffect(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        visual: string, 
        color: string,
        time: number, 
        traceFn: () => void
    ) {
        ctx.save();

        if (visual === 'BLACK_HOLE' || visual === 'PULL') {
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = color; ctx.lineWidth = 1;
            const seed = Math.abs(x + y * 13);
            for(let i=0; i<2; i++) {
                const offsetX = ((seed + i*50) % 20) - 10;
                const speed = 20 + (seed % 10);
                const h = 40;
                const py = (time * speed + i * 20) % h;
                const alpha = 1 - Math.abs((py - h/2) / (h/2));
                ctx.globalAlpha = alpha * 0.5;
                ctx.beginPath(); ctx.moveTo(x + offsetX, y - h + py); ctx.lineTo(x + offsetX, y - h + py + 5); ctx.stroke();
            }
            ctx.globalAlpha = 0.3; traceFn(); ctx.stroke();

        } else if (visual === 'BURNING_GROUND' || visual === 'FIREBALL') {
            const seed = Math.abs(x + y);
            const emberY = (time * 60 + seed) % 50;
            const emberAlpha = 1 - (emberY / 50);
            ctx.globalCompositeOperation = 'lighter';
            ctx.fillStyle = '#fbbf24'; ctx.globalAlpha = emberAlpha;
            ctx.beginPath(); ctx.arc(x + Math.sin(time*3 + seed)*5, y - emberY + 10, 1.5, 0, Math.PI*2); ctx.fill();
            ctx.strokeStyle = color; ctx.lineWidth = 1; ctx.globalAlpha = 0.2 + Math.sin(time*5 + x)*0.1;
            traceFn(); ctx.stroke();

        } else if (visual === 'FROST_FIELD') {
            const seed = Math.abs(x * 11 + y);
            ctx.globalCompositeOperation = 'screen';
            ctx.fillStyle = '#fff';
            const sparkle = Math.sin(time * 5 + seed) > 0.8;
            if (sparkle) {
                const sx = x + (Math.sin(seed) * 15); const sy = y + (Math.cos(seed) * 8);
                ctx.globalAlpha = 0.8;
                ctx.beginPath(); ctx.moveTo(sx, sy-3); ctx.lineTo(sx, sy+3); ctx.moveTo(sx-3, sy); ctx.lineTo(sx+3, sy); ctx.stroke();
            }
            ctx.fillStyle = color; ctx.globalAlpha = 0.15; traceFn(); ctx.fill();

        } else {
            const seed = Math.abs(x * 7 + y * 13); 
            const count = (seed % 2) + 1;
            ctx.globalCompositeOperation = 'lighter';
            ctx.fillStyle = color;
            for(let i=0; i<count; i++) {
                const speed = 15 + (seed % 10);
                const offset = (seed * i * 100);
                const bY = (time * speed + offset) % 40; 
                const bAlpha = 1 - (bY / 40); 
                const bX = Math.sin(time * 2 + offset) * 8;
                ctx.globalAlpha = bAlpha * 0.6;
                ctx.beginPath(); ctx.arc(x + bX, y - bY + 15, 1.5 + i, 0, Math.PI * 2); ctx.fill();
            }
            ctx.strokeStyle = color; ctx.lineWidth = 1; ctx.globalAlpha = 0.2; traceFn(); ctx.stroke();
        }
        ctx.restore();
    }
};

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { SpriteManager } from "../../sprites";
import { Team } from "../../../types";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";

// =================================================================================
// 🧚 UNIT VISUAL EFFECTS (Flight, Casting, Status)
// =================================================================================

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171';

    const feetX = physX;
    const feetY = physY - physZ; 

    ctx.save();

    // 1. Ground Anchor (The Base)
    ctx.save();
    ctx.scale(1, 0.58); 
    ctx.lineDashOffset = -t * 20;

    // Outer dashed ring (Tech style)
    ctx.globalAlpha = 0.6;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.setLineDash([8, 4]);
    ctx.beginPath();
    ctx.arc(0, 0, 18, 0, Math.PI * 2);
    ctx.stroke();

    // Inner solid ring/plate
    ctx.setLineDash([]);
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.3;
    ctx.beginPath();
    ctx.arc(0, 0, 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // 2. Holographic Tether (The Lift)
    if (physZ > 5) {
        const grad = ctx.createLinearGradient(0, 0, feetX, feetY);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent'); 

        ctx.strokeStyle = grad;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.5;

        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(feetX, feetY);
        ctx.stroke();

        const pulseCount = 3;
        ctx.fillStyle = isBlue ? '#e0f2fe' : '#fecaca';
        ctx.globalAlpha = 0.8;

        for(let i=0; i<pulseCount; i++) {
            const p = (t * 0.8 + i / pulseCount) % 1.0; 
            const px = feetX * p;
            const py = feetY * p;
            const scale = 1 - p * 0.5;
            ctx.beginPath();
            ctx.ellipse(px, py, 4 * scale, 2 * scale, 0, 0, Math.PI*2);
            ctx.fill();
        }
    }

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 

    ctx.save();
    ctx.translate(0, 5); 
    ctx.scale(1, 0.5); 

    // Rotating Wind/Energy Swirl at Feet
    ctx.rotate(t * 8); 

    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.6;
    ctx.stroke();

    ctx.beginPath();
    for(let i=0; i<3; i++) {
        const offset = i * (Math.PI * 2 / 3);
        const arcLen = Math.PI / 2;
        ctx.moveTo(Math.cos(offset) * 18, Math.sin(offset) * 18);
        ctx.arc(0, 0, 18, offset, offset + arcLen);
    }

    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.5 + Math.sin(t * 20) * 0.2; 
    ctx.stroke();

    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    if (skill.tag === 'ULT') {
        drawUltimateChantVFX(ctx, agent, t);
        return;
    }

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    // 1. Rising Energy Lines
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 3; 
    const lineCount = 5 + Math.floor(progress * 8); 
    for(let i=0; i<lineCount; i++) {
        const h = (t * 150 + i * 40) % 90; 
        const alpha = 1 - (h / 90);
        const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
    }

    // 2. Converging Rings
    if (progress > 0.2) {
        const ringScale = (1 - progress) * 2.5; 
        ctx.globalAlpha = progress;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

        ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
        ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. Hand Glow
    ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

    // 4. Final Flash
    if (progress > 0.9) {
        ctx.globalAlpha = (progress - 0.9) * 10;
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
    }

    ctx.restore();
}

// 🌀 ULTIMATE BODY GLOW (Intense Core Accumulation)
export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    ctx.globalCompositeOperation = 'lighter';

    // Intense Core Glow (Chest)
    // Pulsing increases speed as cast finishes
    const pulseSpeed = 10 + progress * 20; 
    const pulse = 1 + Math.sin(t * pulseSpeed) * (0.1 + progress * 0.2);

    // Outer Aura
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.3 * progress;
    ctx.beginPath();
    ctx.arc(0, -40, 45 * pulse, 0, Math.PI*2);
    ctx.fill();

    // Inner Core
    ctx.globalAlpha = 0.6 * progress;
    ctx.beginPath();
    ctx.arc(0, -40, 25 * pulse, 0, Math.PI*2);
    ctx.fill();

    // White Hot Center (Critical Mass)
    ctx.fillStyle = '#fff';
    ctx.globalAlpha = 0.8 * progress * progress; // Quadratic ramp up
    ctx.beginPath();
    ctx.arc(0, -40, 10 * pulse, 0, Math.PI*2);
    ctx.fill();

    // Rising Particles (Spirit Bomb style)
    if (progress > 0.2) {
        const pCount = 5;
        for(let i=0; i<pCount; i++) {
            const angle = (t * 5 + i) % (Math.PI*2);
            const dist = 60 * (1 - ((t + i*0.2) % 1)); // Suck INWARD
            const px = Math.cos(angle) * dist;
            const py = -40 + Math.sin(angle) * dist;

            ctx.fillStyle = color;
            ctx.globalAlpha = 0.5 * progress;
            ctx.beginPath(); ctx.arc(px, py, 2, 0, Math.PI*2); ctx.fill();
        }
    }

    ctx.restore();
}

// Proxy to SurfaceAssets for backward compatibility and unified visual style
export function drawSkillGroundIndicator(ctx: CanvasRenderingContext2D, x: number, y: number, color: string, t: number, progress: number, skillRadius: number, type: 'BASIC' | 'ACTIVE' | 'ULT', isAOE: boolean) {
    SurfaceAssets.drawCastRune(ctx, x, y, color, t, progress, skillRadius, type, isAOE);
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, -110);

            const glow = AssetManager.getGlowSprite(skill.color);
            ctx.globalCompositeOperation = 'lighter';
            const pulse = 0.5 + Math.sin(t * 10) * 0.1;
            ctx.globalAlpha = 0.3 * pulse;
            ctx.drawImage(glow, -40, -40, 80, 80);

            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    const HEAD_Y = -60; 

    // 1. FROZEN - ICE PRISM
    if (agent.visualStatus === 'FROZEN') {
        ctx.save();
        ctx.translate(0, -40); 

        const w = 30; const h = 50;

        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = 'rgba(186, 230, 253, 0.4)'; 
        ctx.beginPath();
        ctx.moveTo(-w, -h); ctx.lineTo(w, -h); ctx.lineTo(w, h); ctx.lineTo(-w, h);
        ctx.fill();

        const grad = ctx.createLinearGradient(-w, -h, w, h);
        grad.addColorStop(0, 'rgba(255,255,255,0.6)');
        grad.addColorStop(0.5, 'rgba(56, 189, 248, 0.3)');
        grad.addColorStop(1, 'rgba(14, 165, 233, 0.5)');

        ctx.fillStyle = grad;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;

        ctx.beginPath();
        ctx.moveTo(0, -h - 10); 
        ctx.lineTo(w + 5, -h + 10); ctx.lineTo(w, h); ctx.lineTo(0, h + 10); 
        ctx.lineTo(-w, h); ctx.lineTo(-w - 5, -h + 10);
        ctx.closePath();
        ctx.fill(); ctx.stroke();

        ctx.globalCompositeOperation = 'lighter';
        ctx.beginPath(); ctx.moveTo(0, -h-10); ctx.lineTo(0, h+10);
        ctx.strokeStyle = 'rgba(255,255,255,0.5)'; ctx.stroke();

        ctx.restore();
    }

    // 2. BANISH - GHOSTLY CAGE
    if (agent.banished && agent.visualStatus !== 'POLYMORPH' && agent.visualStatus !== 'STASIS') {
        ctx.translate(0, -30); 

        ctx.globalCompositeOperation = 'source-over';
        ctx.strokeStyle = '#c084fc';
        ctx.lineWidth = 3;
        ctx.globalAlpha = 0.8;

        const bars = 5; const radius = 25; const height = 50;

        for(let i=0; i<bars; i++) {
            const angle = t * 2 + (i / bars) * Math.PI * 2;
            const x = Math.cos(angle) * radius;
            const z = Math.sin(angle); 

            const alpha = 0.5 + (z + 1) * 0.25; 

            ctx.globalAlpha = alpha;
            ctx.beginPath(); ctx.moveTo(x, -height); ctx.lineTo(x, height); ctx.stroke();

            if (i % 2 === 0) {
                ctx.fillStyle = '#d8b4fe';
                ctx.beginPath(); ctx.arc(x, -height/2 + Math.sin(t*3+i)*10, 3, 0, Math.PI*2); ctx.fill();
            }
        }

        ctx.globalAlpha = 0.6;
        ctx.save();
        ctx.scale(1, 0.3); 
        ctx.beginPath(); ctx.arc(0, -height / 0.3, radius, 0, Math.PI*2); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, height / 0.3, radius, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. STUN - 3D DIZZY RING
    if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
        ctx.translate(0, HEAD_Y - 10);
        ctx.globalCompositeOperation = 'lighter';
        ctx.lineWidth = 3;
        const count = 5; const radius = 25;

        for(let i=0; i<count; i++) {
            const angle = t * 4 + (i / count) * Math.PI * 2;
            const x = Math.cos(angle) * radius;
            const y = Math.sin(angle) * radius * 0.3;
            const scale = 1 + Math.sin(angle) * 0.3;

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(scale, scale);

            ctx.fillStyle = '#facc15';
            ctx.beginPath();
            const starPts = 5;
            for(let j=0; j<starPts*2; j++) {
                const r = j%2===0 ? 6 : 2;
                const a = j * Math.PI / starPts;
                ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
            }
            ctx.fill();

            ctx.globalAlpha = 0.4;
            ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }
    }

    // 4. SILENCE
    if (agent.silenceTimer > 0) {
        ctx.translate(0, HEAD_Y - 15);
        const scale = 1 + Math.sin(t * 5) * 0.1;
        ctx.scale(scale, scale);

        ctx.fillStyle = '#1e1b4b'; 
        ctx.strokeStyle = '#a855f7';
        ctx.globalCompositeOperation = 'lighter';

        const drawRune = (width: number, alpha: number) => {
            ctx.lineWidth = width;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.rect(-15, -10, 30, 20);
            ctx.fill(); ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(-8, -5); ctx.lineTo(8, 5);
            ctx.moveTo(8, -5); ctx.lineTo(-8, 5);
            ctx.stroke();
        };
        drawRune(4, 0.3); drawRune(2, 1.0);
    }

    // 5. DoT
    if (agent.dotTimer > 0) {
        ctx.translate(0, -40);
        const count = 3;
        for(let i=0; i<count; i++) {
            const phase = (t + i/count) % 1;
            const y = -phase * 40;
            const x = Math.sin(phase * 10 + i) * 10;
            const size = (1-phase) * 6;

            ctx.fillStyle = i%2===0 ? '#10b981' : '#a855f7'; 
            ctx.globalAlpha = (1-phase);
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
    }

    // 6. HoT
    if (agent.hotTimer > 0) {
        ctx.translate(0, -30);
        const angle = -t * 3;
        const radius = 25;
        const x = Math.cos(angle) * radius;
        const y = Math.sin(angle) * radius * 0.3; 

        ctx.fillStyle = '#4ade80';
        ctx.font = 'bold 16px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('+', x, y);
    }

    ctx.restore();
}

