export const ZoneRenderer = {

    draw(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Center of the tile face
        size: number,
        color: string,
        type: 'CAST' | 'FIELD',
        visual: string,
        progress: number, 
        globalTime: number,
        dist: number, 
        maxRadius: number
    ) {
        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        if (type === 'CAST') {
            // New System: Single Hex Tacticals
            // If dist == 0, it's the center tile of the AOE
            const isCenter = dist === 0;
            SurfaceAssets.drawTacticalGrid(ctx, x, y, color, progress, isCenter);

        } else if (type === 'FIELD') {
            SurfaceAssets.drawFieldEffect(ctx, x, y, visual, color, globalTime, trace);
        }
    }
};

