import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../../types";
import { SpriteManager } from "../../../sprites";
import { THEME_IMPERIAL, THEME_COVENANT } from "../../../../constants";

// =========================================================================================
// 🛠️ GENERIC / SHARED UTILS (2.5D Volumetric Building Blocks)
// =========================================================================================

// 1. STANDARD EXPLOSION (Physical Debris + Flash)
export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE' | 'SHARD' | 'DEBRIS') {
    const safeCount = Math.min(type === 'SPARK' ? 15 : 8, count);
    for (let i = 0; i < safeCount; i++) {
        const theta = Math.random() * Math.PI * 2;
        const phi = (Math.random() - 0.5) * Math.PI; // 3D Spread
        const spd = Math.random() * 200 * speed;

        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;

        // 3D Velocity Vector
        const cosPhi = Math.cos(phi);
        p.vx = Math.cos(theta) * cosPhi * spd;
        p.vy = Math.sin(theta) * cosPhi * spd;
        p.vz = Math.sin(phi) * spd + (100 * speed); // Bias upwards

        p.life = life * (0.6 + Math.random() * 0.4); p.maxLife = life;
        p.color = color;
        p.size = type === 'SPARK' ? Math.random() * 3 + 2 : Math.random() * 15 + 10;
        if (type === 'SHARD') p.size = 6 + Math.random() * 6;

        p.type = type; 
        p.delay = 0;

        // Random rotation for debris
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random() - 0.5) * 10;

        system.state.particles.push(p);
    }
}

// 2. GROUND IMPACT RINGS (Shockwaves)
export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    // Inner Flash
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 5;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0; // Starts small, renderer expands it
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);

    // Outer Distortion Ring
    const r = system.state.getParticle();
    r.x = x; r.y = y; r.z = 2;
    r.life = life * 1.5; r.maxLife = r.life;
    r.color = color; r.size = 50; 
    r.type = 'RING';
    system.state.particles.push(r);
}

// 3. VOLUMETRIC BEAM (Cylinder)
export function spawnBeam(system: VFXSystem, sx: number, sy: number, sz: number, tx: number, ty: number, tz: number, color: string, duration: number = 0.4, size: number = 4) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = sz;
    p.targetX = tx; p.targetY = ty; // Note: Particle struct needs Z target support ideally, but standard beam assumes ground target usually. 
    // Hack: We map Z into the render logic or just keep it simple for now. 
    // The renderer uses (targetX, targetY) for the end point on ground.

    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = duration; p.maxLife = duration; 
    p.color = color; p.size = size; 
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

// 4. RISING SPIKES (From Underground)
export function spawnRisingSpikes(system: VFXSystem, x: number, y: number, count: number, radius: number, color: string, type: 'SHARD' | 'DEBRIS') {
    for(let i=0; i<count; i++) {
        const angle = Math.random() * Math.PI * 2;
        const dist = Math.random() * radius;

        const p = system.state.getParticle();
        p.x = x + Math.cos(angle) * dist;
        p.y = y + Math.sin(angle) * dist;
        p.z = -50; // Start underground

        p.vx = 0; p.vy = 0;
        p.vz = 300 + Math.random() * 200; // Shoot up

        p.life = 2.0; p.maxLife = 2.0;
        p.color = color;
        p.size = 10 + Math.random() * 15;
        p.type = type;
        p.rotation = 0; // Vertical orientation usually
        p.delay = dist * 0.005; // Ripple effect from center
        system.state.particles.push(p);
    }
}

// 5. DIRECTIONAL IMPACT (Cone Splash)
export function spawnDirectionalImpact(system: VFXSystem, x: number, y: number, z: number, dirX: number, dirY: number, color: string, type: 'PHYSICAL' | 'MAGICAL') {
    const isPhysical = type === 'PHYSICAL';
    const baseAngle = Math.atan2(dirY, dirX);
    const count = 8;
    const spread = 0.6; 

    for (let i = 0; i < count; i++) {
        const angle = baseAngle + (Math.random() - 0.5) * spread;
        const speed = 300 + Math.random() * 300; 
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 50 + Math.random() * 150; 

        p.life = 0.4; p.maxLife = p.life;
        p.color = isPhysical ? '#cbd5e1' : color; 
        p.size = 3 + Math.random() * 4; 
        p.type = 'SPARK'; 
        p.delay = 0;
        system.state.particles.push(p);
    }

    // Backsplash ring
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.life = 0.3; p.maxLife = 0.3;
    p.color = color; p.size = 20; p.type = 'RING';
    system.state.particles.push(p);
}

// 6. UNIT DEATH (Shatter Model)
export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role) {
    const assets = SpriteManager.getUnitImages(role, team);
    const isBlue = team === Team.BLUE;
    const theme = isBlue ? THEME_IMPERIAL : THEME_COVENANT;

    // 1. Icon Sprite (Spinning away)
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 40; 
    const angle = Math.random() * Math.PI * 2;
    p.vx = Math.cos(angle) * 100; p.vy = Math.sin(angle) * 100; p.vz = 300; 
    p.life = 1.5; p.maxLife = 1.5;
    p.color = '#fff'; p.size = 40; 
    p.type = 'SPRITE'; p.image = assets.icon;
    p.vRotation = (Math.random() - 0.5) * 20; 
    system.state.particles.push(p);

    // 2. Physical Debris
    spawnExplosion(system, x, y, 20, 8, isBlue ? '#94a3b8' : '#52525b', 1.0, 2.0, 'DEBRIS');

    // 3. Soul Release
    const soul = system.state.getParticle();
    soul.x = x; soul.y = y; soul.z = 10;
    soul.vz = 50; 
    soul.life = 1.5; soul.maxLife = 1.5;
    soul.color = theme.secondary;
    soul.size = 100;
    soul.type = 'GLOW'; 
    system.state.particles.push(soul);
}

// 7. TELEPORT / SPAWN
export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    // Vertical light shaft
    const beam = system.state.getParticle();
    beam.x = x; beam.y = y; beam.z = 0;
    beam.life = 0.5; beam.maxLife = 0.5;
    beam.color = color; beam.size = 40; beam.type = 'PILLAR';
    system.state.particles.push(beam);

    spawnShockwave(system, x, y, color, 0.5);
}

// 8. LINGERING FOG/CLOUD
export function spawnLingeringField(system: VFXSystem, x: number, y: number, color: string, type: string, duration: number, delay: number) {
    const count = 4;
    for(let i=0; i<count; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*30;
        p.y = y + (Math.random()-0.5)*20;
        p.z = 5;
        p.vx = (Math.random()-0.5) * 15;
        p.vy = (Math.random()-0.5) * 15;
        p.vz = 5 + Math.random() * 15; // Slow rise
        p.life = duration + Math.random(); p.maxLife = p.life;
        p.color = color;
        p.size = 30 + Math.random() * 20; 
        p.type = 'SMOKE';
        p.delay = delay + Math.random() * 0.5;
        system.state.particles.push(p);
    }
}

// 9. CAST INTERRUPT
export function spawnCastBreak(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    const blast = system.state.getParticle();
    blast.x = x; blast.y = y; blast.z = 40;
    blast.life = 0.25; blast.maxLife = 0.25;
    blast.color = '#00ffff'; blast.size = 80;
    blast.type = 'BLAST';
    system.state.particles.push(blast);

    for(let i=0; i<6; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*20; p.y = y + (Math.random()-0.5)*20; p.z = 40;
        p.vx = (Math.random()-0.5) * 100; p.vy = (Math.random()-0.5) * 100;
        p.life = 0.4; p.maxLife = 0.4;
        p.color = '#ff00ff'; p.size = 5; p.type = 'CHIP'; 
        system.state.particles.push(p);
    }
}

// 10. GRID IMPACT (Tile Highlight)
export function spawnGridImpact(system: VFXSystem, x: number, y: number, color: string, team: Team, delay: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.life = 1.0; p.maxLife = 1.0;
    p.color = color;
    p.size = 36; 
    p.type = 'GRID_FIELD'; 
    p.delay = delay;
    system.state.particles.push(p);
