// "Red Tornado": Spiraling particles in funnel shape.
export function spawnCovenantBloodStorm(system: VFXSystem, x: number, y: number, color: string) {
    const layers = 12;
    // Create a funnel: Radius increases with Height
    for(let i=0; i<layers; i++) {
        const h = i * 40; // Height per layer
        const r = 40 + i * 15; // Cone shape
        const count = 5;

        for(let j=0; j<count; j++) {
            const p = system.state.getParticle();
            const angle = (j/count) * Math.PI * 2 + i; // Twist

            p.x = x + Math.cos(angle) * r;
            p.y = y + Math.sin(angle) * r;
            p.z = h;

            // Orbital Velocity
            const speed = 400;
            p.vx = -Math.sin(angle) * speed; 
            p.vy = Math.cos(angle) * speed;
            p.vz = 100; // Updraft

            p.life = 2.5; p.maxLife = 2.5;
            p.color = '#dc2626'; // Blood
            p.size = 30 + Math.random() * 10;
            p.type = 'SMOKE'; 
            p.delay = i * 0.1; // Grow up
            system.state.particles.push(p);
        }
    }

    // Base Suction Ring
    addImpact(system, x, y, 0, '#7f1d1d', 'RING', 2.0);
}

