// ⚔️ WARRIOR: BLOOD STORM (wr_u2)
// "Crimson Tornado": Spiraling particles forming a funnel.
export function spawnCovenantBloodStorm(system: VFXSystem, x: number, y: number, color: string) {
    const layers = 15;

    for(let i=0; i<layers; i++) {
        const progress = i / layers;
        const h = i * 35; // Height stack
        const r = 20 + (i * i * 0.8); // Funnel shape (exponential radius)

        // Particles per layer
        for(let j=0; j<4; j++) {
            const p = system.state.getParticle();
            const angle = (j/4) * Math.PI * 2 + (i * 0.5); // Twist

            p.x = x + Math.cos(angle) * r;
            p.y = y + Math.sin(angle) * r;
            p.z = h;

            // Tangential Velocity (Spin)
            const spinSpeed = 600;
            p.vx = -Math.sin(angle) * spinSpeed; 
            p.vy = Math.cos(angle) * spinSpeed;
            p.vz = 150; // Updraft

            p.life = 2.0; p.maxLife = 2.0;
            p.color = Math.random() > 0.5 ? '#b91c1c' : '#7f1d1d'; // Blood tones
            p.size = 20 + Math.random() * 10;
            p.type = 'SMOKE'; 
            p.delay = i * 0.05; // Growth animation
            system.state.particles.push(p);
        }
    }

    // Suction Base
    addImpact(system, x, y, 0, '#991b1b', 'RING', 2.0);
}

// 🏹 RANGER: FINAL BLAST (rr_u1)
// "Railgun": Black beam with red lightning core.
export function spawnCovenantRailgun(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    // 1. The Beam
    const beam = system.state.getParticle();
    beam.x = sx; beam.y = sy; beam.z = 40; 
    beam.targetX = tx; beam.targetY = ty;
    beam.life = 0.6; beam.maxLife = 0.6;
    beam.color = '#000000'; // Void Core
    beam.size = 12;
    beam.type = 'DEATH_RAY';
    system.state.particles.push(beam);

    // 2. Mach Cones (Recoil Rings)
    const dx = tx - sx; const dy = ty - sy;
    const dist = Math.sqrt(dx*dx + dy*dy);
    const angle = Math.atan2(dy, dx);
    const count = Math.floor(dist / 60);

    for(let i=1; i<count; i++) {
        const d = i * 60;
        const px = sx + Math.cos(angle) * d;
        const py = sy + Math.sin(angle) * d;

        const r = system.state.getParticle();
        r.x = px; r.y = py; r.z = 40;
        r.life = 0.4; r.maxLife = 0.4;
        r.color = '#ef4444'; // Red Shock
        r.size = 30;
        r.type = 'RING';
        r.delay = i * 0.02; // Super fast travel
        system.state.particles.push(r);
    }
}

