// Theme: Order, Geometry, Light, Technology
// =========================================================================================

// 🛡️ TANK: IMPERIAL SANCTUARY (tb_u1)
// "Holographic Fortress": Massive hexagonal shields rise instantly from the grid.
export function spawnImperialSanctuary(system: VFXSystem, x: number, y: number, color: string) {
    // 1. Grid Definition (The Base)
    const dome = system.state.getParticle();
    dome.x = x; dome.y = y; dome.z = 0;
    dome.life = 3.5; dome.maxLife = 3.5;
    dome.color = '#fbbf24'; // Gold
    dome.size = 280;
    dome.type = 'GRID_FIELD'; // Use clean hex grid
    system.state.particles.push(dome);

    // 2. Light Pillars (The Walls) - Six pillars forming a hexagon
    const radius = 160;
    for(let i=0; i<6; i++) {
        const angle = (i / 6) * Math.PI * 2;
        const px = x + Math.cos(angle) * radius;
        const py = y + Math.sin(angle) * radius;

        // Vertical Beams
        const p = system.state.getParticle();
        p.x = px; p.y = py; p.z = 0;
        p.life = 0.5 + Math.random() * 0.5; p.maxLife = p.life;
        p.color = '#fef3c7'; // Pale Gold
        p.size = 20; 
        p.type = 'PILLAR'; // Clean beam
        p.delay = i * 0.05; // Ripple activation
        system.state.particles.push(p);

        // Connection Beams (Laser Fence)
        const nextAngle = ((i+1) / 6) * Math.PI * 2;
        const nx = x + Math.cos(nextAngle) * radius;
        const ny = y + Math.sin(nextAngle) * radius;

        // Beam across
        const fence = system.state.getParticle();
        fence.x = px; fence.y = py; fence.z = 60; // Waist height
        fence.targetX = nx; fence.targetY = ny;
        fence.life = 3.0; fence.maxLife = 3.0;
        fence.color = '#f59e0b';
        fence.size = 3;
        fence.type = 'BEAM';
        fence.delay = 0.3 + (i * 0.05);
        system.state.particles.push(fence);
    }
}

