    beam.life = 2.0; beam.maxLife = 2.0;
    beam.color = '#4ade80'; 
    beam.size = 50; 
    beam.type = 'PILLAR';
    system.state.particles.push(beam);

    // 2. Falling Data Code (Inverse Sparks)
    for(let i=0; i<30; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*40;
        p.y = y + (Math.random()-0.5)*40;
