}

import { VFXSystem } from "../vfx";
import { spawnExplosion, spawnShockwave, addImpact, spawnBeam, spawnRisingSpikes, spawnLingeringField, spawnDeathRay } from "./generic";

// =========================================================================================
// 🔴 COVENANT (RED) ULTIMATES - CATACLYSM REDESIGN
// Theme: Chaos, Magma, Blood, Heavy Metal, Necromancy
// =========================================================================================

// 🛡️ TANK: GUILLOTINE (tr_u1)
// "Execution": A massive energetic blade slams down, causing a blood geyser.
export function spawnCovenantGuillotine(system: VFXSystem, x: number, y: number, color: string) {
    // 1. The Blade Drop (Fast vertical streak)
    const bladeHeight = 800;
    for(let i=0; i<5; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*20;
        p.y = y;
        p.z = bladeHeight + i * 50; 

        p.vx = 0; p.vy = 0; p.vz = -3000; // Terminal velocity
        p.life = 0.3; p.maxLife = 0.3;
        p.color = '#7f1d1d'; // Dark Blood
        p.size = 40; // Wide blade
        p.type = 'SHARD'; 
        p.rotation = Math.PI/2; // Vertical alignment
        system.state.particles.push(p);
    }

    // 2. Impact Blood Geyser (Timed to hit)
    setTimeout(() => {
        // Ground heavy crack
        addImpact(system, x, y, 0, '#ef4444', 'BLAST', 0.5);

        // Vertical blood spray
        for(let i=0; i<15; i++) {
            const p = system.state.getParticle();
            p.x = x; p.y = y; p.z = 10;
            const angle = Math.random() * Math.PI * 2;
            const speed = 100 + Math.random() * 100;

            p.vx = Math.cos(angle) * speed;
            p.vy = Math.sin(angle) * speed;
            p.vz = 400 + Math.random() * 400; // High spray

            p.life = 1.5; p.maxLife = 1.5;
            p.color = i % 2 === 0 ? '#b91c1c' : '#ef4444';
            p.size = 8 + Math.random() * 8;
            p.type = 'SMOKE'; // Liquid look
            system.state.particles.push(p);
        }
    }, 250);
}

// 🛡️ TANK: UNDEAD ARMY (tr_u2)
