// 🔮 MAGE: METEOR (mr_u1)
// "Extinction Event": Falling rock with trail.
export function spawnCovenantMeteor(system: VFXSystem, x: number, y: number, color: string) {
    // 1. The Meteor (Rendered as a huge projectile-like glowing ball)
    const meteor = system.state.getParticle();
    // Start high and offset
    const startZ = 1000;
    const offset = 400; 
    meteor.x = x - offset; meteor.y = y - offset; meteor.z = startZ;

    // Velocity aiming at target
    const time = 0.6;
    meteor.vx = offset / time;
    meteor.vy = offset / time;
    meteor.vz = -startZ / time;

    meteor.life = time; meteor.maxLife = time;
    meteor.color = '#f97316'; // Bright Orange
    meteor.size = 120; // Huge
    meteor.type = 'GLOW'; // Glowing ball
    system.state.particles.push(meteor);

    // 2. Trail (Smoke)
    for(let i=0; i<10; i++) {
        const p = system.state.getParticle();
        p.x = meteor.x; p.y = meteor.y; p.z = meteor.z; // Start pos (will be wrong, visual approximation)
        // Actually we just spawn them along the path in a loop
        const t = i / 10;
        p.x = (x - offset) + (offset * t);
        p.y = (y - offset) + (offset * t);
        p.z = startZ + (-startZ * t);

        p.vx = 0; p.vy = 0; p.vz = 50; // Smoke rises
        p.life = 1.5; p.maxLife = 1.5;
        p.color = '#7c2d12';
        p.size = 40;
        p.type = 'SMOKE';
        p.delay = i * 0.05;
        system.state.particles.push(p);
    }

    // 3. Impact
    setTimeout(() => {
        spawnExplosion(system, x, y, 0, 40, '#f97316', 3.0, 1.5, 'DEBRIS'); // Lava rocks
        spawnShockwave(system, x, y, '#ea580c', 0.8);
        addImpact(system, x, y, 0, '#fff', 'BLAST', 0.5);
    }, time * 1000);
}

// 🔮 MAGE: DEATH FINGER (mr_u2)
// "Red Laser": Thin intense beam.
export function spawnCovenantDeathFinger(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
