import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";

// Modular Spawners
import * as Generic from "../vfx/spawners/generic";
import * as Imperial from "../vfx/spawners/imperial";
import * as Covenant from "../vfx/spawners/covenant";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                }
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'IMPACT_AOE':
                if (event.skill) {
                    const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                    const radius = event.skill.aoeRadius || 1;
                    const affectedHexes = HexUtils.range(centerHex, radius);

                    const id = event.skill.id;
                    const color = event.color || '#fff';

                    // =================================================================
                    // 🔵 IMPERIAL (BLUE) ULTIMATE VFX MAPPING
                    // =================================================================

                    if (id === 'tb_u1') { // Sanctuary
                        Imperial.spawnImperialSanctuary(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.7); return;
                    }
                    if (id === 'tb_u2') { // Kings Blessing
                        Imperial.spawnImperialKingsBlessing(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3); return;
                    }
                    if (id === 'wb_u1') { // Thunder
                        Imperial.spawnImperialThunder(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6); return;
                    }
                    if (id === 'wb_u2') { // Daybreak
                        Imperial.spawnImperialDaybreak(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8); return;
                    }
                    if (id === 'rb_u1') { // Crystal Arrow
                        Imperial.spawnImperialCrystalArrow(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6); return;
                    }
                    if (id === 'rb_u2') { // Starfall
                        Imperial.spawnImperialStarfall(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.4); return;
                    }
                    if (id === 'mb_u1') { // Black Hole
                        Imperial.spawnImperialBlackHole(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.5); return;
                    }
                    if (id === 'mb_u2') { // Absolute Zero
                        Imperial.spawnImperialFrostfall(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.5); return;
                    }
                    if (id === 'sb_u1') { // Intervention
                        Imperial.spawnImperialIntervention(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3); return;
                    }
                    if (id === 'sb_u2') { // Resurrection
                        Imperial.spawnImperialResurrection(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.4); return;
                    }

                    // =================================================================
                    // 🔴 COVENANT (RED) ULTIMATE VFX MAPPING
                    // =================================================================

                    if (id === 'tr_u1') { // Guillotine
                        Covenant.spawnCovenantGuillotine(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8); return;
                    }
                    if (id === 'tr_u2') { // Undead Army
                        Covenant.spawnCovenantUndeadArmy(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.5); return;
                    }
                    if (id === 'wr_u1') { // Ragnarok
                        Covenant.spawnCovenantRagnarok(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.9); return;
                    }
                    if (id === 'wr_u2') { // Blood Storm
                        Covenant.spawnCovenantBloodStorm(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6); return;
                    }
                    if (id === 'rr_u1') { // Railgun
                        Covenant.spawnCovenantRailgun(vfx, event.pos.x - 200, event.pos.y, event.pos.x, event.pos.y, color);
                        camera.addTrauma(0.8); return;
                    }
                    if (id === 'rr_u2') { // Nuke
                        Covenant.spawnCovenantNuke(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8); return;
                    }
                    if (id === 'mr_u1') { // Meteor
                        Covenant.spawnCovenantMeteor(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.7); return;
                    }
                    if (id === 'mr_u2') { // Death Finger (AOE fallback)
                        Covenant.spawnCovenantDeathFinger(vfx, event.pos.x, event.pos.y - 200, event.pos.x, event.pos.y, color);
                        camera.addTrauma(0.7); return;
                    }
                    if (id === 'sr_u1') { // Soul Link
                        Covenant.spawnCovenantSoulLink(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3); return;
                    }
                    if (id === 'sr_u2') { // Ancestors
                        Covenant.spawnCovenantAncestors(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3); return;
                    }

                    // Generic Grid Reaction
                    affectedHexes.forEach(h => {
                        if (engine.map.isValid(h.q, h.r)) {
                            const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                            const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                            const tileVisualY = tilePos.y - hHeight;
                            const dist = HexUtils.dist(centerHex, h);
                            const delay = dist * 0.06;

                            Generic.spawnGridImpact(vfx, tilePos.x, tileVisualY, event.color || '#fff', Team.BLUE, delay);
                        }
                    });
                }

                // Generic Fallback
                Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 0, 20, event.color || '#fff', 2.0, 0.6, 'SPARK');
                Generic.addImpact(vfx, event.pos.x, visualGroundY, 0, event.color || '#fff', 'BLAST', 0.5);
                Generic.spawnShockwave(vfx, event.pos.x, visualGroundY, event.color || '#fff', 0.6);
                camera.addTrauma(0.25); 
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                } else {
                    const hitColor = event.skill?.color || '#fff';
                    Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 20, 8, hitColor, 1.0, 0.3, 'SPARK');
                }
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) Generic.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role);
                camera.addTrauma(0.05);
                break;

            case 'SPAWN':
                Generic.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                Generic.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                Generic.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                // Red Mage Death Finger (mr_u2) - Single Target Special
                if (event.skill?.id === 'mr_u2') {
                    Generic.spawnDeathRay(vfx, source.px, source.py - sH - 45, event.pos.x, visualGroundY - 30, event.color || '#be123c');
                    return;
                }

                Generic.spawnBeam(vfx, source.px, source.py - sH - 40, 0, event.pos.x, visualGroundY - 30, 0, event.color || '#fff');
                Generic.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';
                    Generic.spawnDirectionalImpact(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, event.color || '#fff', type);
                }
            }
        } else {
            Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
        }

        if (dmg > 50) camera.addTrauma(0.05); 
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.15); 

            // Death Finger target hit check
            if (skill && skill.id === 'mr_u2') {
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#000', 3.0, 0.5, 'SPARK');
                Generic.addImpact(vfx, event.pos.x, visualY, 20, '#be123c', 'BLAST', 0.5);
                Generic.spawnShockwave(vfx, event.pos.x, visualY, '#000', 0.5);
                return; 
            }

            // FACTION RITUAL (Ult Hit)
            if (faction === Team.BLUE) {
                // Remove Pillar fallback. Use pure explosion/shockwave.
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.5, 0.8, 'SPARK');
                Generic.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 0.8);
            } else {
                // Red faction uses Blood Ritual
                Generic.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            if (skill && skill.id === 'wr_u1') { // Ragnarok Hit
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#991b1b', 2.0, 1.0, 'DEBRIS');
                Generic.addImpact(vfx, event.pos.x, visualY, 0, '#ef4444', 'BLAST', 0.8);
                camera.addTrauma(0.5);
            } 

        } else {
            // Standard Hits
            if (visualType === 'SMASH') {
                Generic.addImpact(vfx, event.pos.x, centerVisualY, 0, color, 'SHOCKWAVE', 0.4);
                Generic.spawnExplosion(vfx, event.pos.x, centerVisualY, 0, 8, color, 0.5, 0.6, 'SHARD'); 
            } 
            else if (visualType === 'SLASH') {
                if (source) {
                    const dx = event.pos.x - source.px;
                    const dy = event.pos.y - source.py;
                    const len = Math.sqrt(dx*dx + dy*dy) || 1;
                    Generic.spawnDirectionalImpact(vfx, event.pos.x, visualY, 30, dx/len, dy/len, color, 'PHYSICAL');
                } else {
                    Generic.spawnExplosion(vfx, event.pos.x, visualY, 30, 8, color, 1.5, 0.4, 'SPARK');
                }
            }
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                Generic.addImpact(vfx, event.pos.x, visualY, 20, color, 'BLAST', 0.5);
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 20, 5, color, 0.5, 1.0, 'SMOKE');
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 20, 8, '#fff', 1.0, 0.3, 'SPARK');
            }
            else {
                Generic.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.4);
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 2.0, 0.4, 'SPARK');
            }
        }
    }
}

import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { Skill } from "../../types";
import { isChaosStyle } from "../systems/vfx/utils";

// Procedural Noise function reuse
function noise(q: number, r: number) {
    return Math.sin(q * 12.9898 + r * 78.233) * 43758.5453 - Math.floor(Math.sin(q * 12.9898 + r * 78.233) * 43758.5453);
}

// Precomputed Hex for Geometry
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

export const SurfaceAssets = {

    // =================================================================================
    // 🌍 TERRAIN TEXTURES (Static Details)
    // =================================================================================

    drawTexture(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        color: string,
        globalTime: number
    ) {
        ctx.save();
        ctx.fillStyle = color;
        ctx.strokeStyle = color;

        const n = noise(q, r);
        const time = globalTime;

        if (type === 'MAGMA') {
            const pulse = 0.5 + Math.sin(time + n * 10) * 0.5;
            ctx.strokeStyle = 'rgba(40, 5, 5, 0.7)'; 
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(cx - 12, cy + 5); ctx.lineTo(cx - 5, cy - 2);
            ctx.lineTo(cx + 8, cy + 3); ctx.lineTo(cx + 15, cy - 5);
            ctx.stroke();

            if (pulse > 0.8) {
                ctx.fillStyle = '#ef4444';
                ctx.globalAlpha = (pulse - 0.8) * 3; 
                ctx.beginPath(); ctx.arc(cx - 5, cy - 2, 2, 0, Math.PI*2); ctx.fill();
            }

        } else if (type === 'VOID') {
            ctx.globalAlpha = 0.3;
            if (n > 0.3) {
                ctx.fillStyle = '#38bdf8';
                ctx.beginPath(); ctx.arc(cx, cy, 2, 0, Math.PI*2); ctx.fill();
                ctx.strokeStyle = '#38bdf8';
                ctx.lineWidth = 1;
                ctx.beginPath();
                if (n > 0.6) { ctx.moveTo(cx, cy); ctx.lineTo(cx + 15, cy - 8); }
                if (n < 0.4) { ctx.moveTo(cx, cy); ctx.lineTo(cx - 15, cy + 8); }
                ctx.stroke();
            }
            const packetTime = (time * 0.5 + n) % 2; 
            if (packetTime < 1.0) {
                ctx.globalAlpha = 1.0 - packetTime; 
                ctx.fillStyle = '#bae6fd';
                const px = cx + (Math.cos(n * 10) * 20 * packetTime);
                const py = cy + (Math.sin(n * 10) * 10 * packetTime);
                ctx.fillRect(px, py, 2, 2);
            }

        } else if (type === 'FOREST') {
            ctx.globalAlpha = 0.6;
            const tufts = Math.floor(n * 3) + 2;
            for(let i=0; i<tufts; i++) {
                const ox = (noise(q+i, r) - 0.5) * 20;
                const oy = (noise(r, q+i) - 0.5) * 12;
                const wind = Math.sin(time * 2 + cx * 0.05 + i) * 3;
                ctx.beginPath();
                ctx.moveTo(cx + ox, cy + oy);
                ctx.quadraticCurveTo(cx + ox - 2 + wind, cy + oy - 6, cx + ox - 4 + wind * 1.5, cy + oy - 8);
                ctx.lineWidth = 1.5;
                ctx.strokeStyle = i % 2 === 0 ? '#4ade80' : '#22c55e';
                ctx.stroke();
            }

        } else if (type === 'ICE') {
            ctx.globalAlpha = 0.3; ctx.fillStyle = '#fff';
            if (n > 0.4) {
                ctx.beginPath();
                ctx.moveTo(cx - 15, cy + 2); ctx.lineTo(cx + 5, cy - 8);
                ctx.lineTo(cx + 15, cy - 4); ctx.lineTo(cx - 5, cy + 8);
                ctx.fill();
            }

        } else if (type === 'DESERT') {
            ctx.globalAlpha = 0.2; ctx.strokeStyle = '#92400e'; ctx.lineWidth = 2;
            const offset = (time * 5) % 20; 
            ctx.beginPath();
            for(let i=0; i<2; i++) {
                const yBase = cy - 10 + i * 15;
                const shift = offset + (n * 20); 
                const xStart = cx - 15 + (shift % 10);
                ctx.moveTo(xStart, yBase);
                ctx.quadraticCurveTo(xStart + 10, yBase - 3, xStart + 20, yBase);
            }
            ctx.stroke();
        }
        ctx.restore();
    },

    // =================================================================================
    // 🎯 TACTICAL GRID VISUALS (Redesigned v2.0)
    // =================================================================================

    drawTacticalGrid(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        progress: number, 
        isCenter: boolean
    ) {
        ctx.save();
        ctx.translate(x, y);

        const isChaos = isChaosStyle(color);
        const intensity = 0.3 + (progress * 0.7); // 0.3 -> 1.0

        if (isChaos) {
            // --- COVENANT STYLE (Jagged, Breathing) ---
            ctx.globalCompositeOperation = 'source-over';

            // 1. Fill (Darker, pulsing)
            ctx.beginPath();
            for (let i = 0; i < 6; i++) {
                const c = HEX_CORNERS[i];
                // Slight jitter for instability
                const jitter = Math.sin(progress * 10 + i) * 2;
                if (i === 0) ctx.moveTo(c.x + jitter, c.y + jitter);
                else ctx.lineTo(c.x + jitter, c.y + jitter);
            }
            ctx.closePath();

            ctx.fillStyle = color;
            ctx.globalAlpha = 0.1 + (Math.sin(Date.now() * 0.01) * 0.05);
            ctx.fill();

            // 2. Warning Border (Dashed)
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = intensity;
            ctx.setLineDash([10, 5]);
            ctx.stroke();

            // 3. Center Cracks
            if (isCenter) {
                ctx.setLineDash([]);
                ctx.beginPath();
                ctx.moveTo(-10, 0); ctx.lineTo(10, 0);
                ctx.moveTo(0, -5); ctx.lineTo(0, 5);
                ctx.stroke();
            }

        } else {
            // --- IMPERIAL STYLE (Holographic, Scanning) ---
            ctx.globalCompositeOperation = 'screen';

            // 1. Hex Border (Clean)
            ctx.beginPath();
            for (let i = 0; i < 6; i++) {
                const c = HEX_CORNERS[i];
                if (i === 0) ctx.moveTo(c.x, c.y);
                else ctx.lineTo(c.x, c.y);
            }
            ctx.closePath();

            ctx.lineWidth = 2;
            ctx.strokeStyle = color;
            ctx.globalAlpha = intensity * 0.8;
            ctx.shadowColor = color;
            ctx.shadowBlur = 5;
            ctx.stroke();
            ctx.shadowBlur = 0;

            // 2. Scanline Effect
            ctx.save();
            ctx.clip();

            // Moving scanline
            const scanY = ((Date.now() / 1500) % 1.0) * (HEX_SIZE * 2 * ISO_SCALE_Y) - (HEX_SIZE * ISO_SCALE_Y);
            ctx.beginPath();
            ctx.moveTo(-HEX_SIZE, scanY);
            ctx.lineTo(HEX_SIZE, scanY);
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.5;
            ctx.stroke();

            // Fill tint
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.1;
            ctx.fill();

            ctx.restore();

            // 3. Center Lock
            if (isCenter) {
                ctx.beginPath();
                ctx.arc(0, 0, 5, 0, Math.PI*2);
                ctx.fillStyle = '#fff';
                ctx.globalAlpha = 0.8;
                ctx.fill();
                ctx.strokeStyle = color;
                ctx.lineWidth = 1;
                ctx.beginPath(); ctx.arc(0, 0, 12, 0, Math.PI*2); ctx.stroke();
            }
        }

        ctx.restore();
    },

    // Kept for Unit Feet (Small personal rune)
    drawUnitRune(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        t: number, 
        progress: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); // Isometric

        const r = HEX_SIZE * 0.8;

        ctx.globalAlpha = 0.4 * progress;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;

        // Simple Spinning Ring
        ctx.beginPath();
        ctx.arc(0, 0, r, 0, Math.PI*2);
        ctx.stroke();

        // Inner spinning bits
        ctx.rotate(t);
        ctx.beginPath();
        ctx.rect(-r*0.6, -r*0.6, r*1.2, r*1.2);
        ctx.stroke();

        ctx.restore();
    },

    // =================================================================================
    // ☢️ FIELD EFFECTS (Active Zones)
    // =================================================================================

    resolveFieldVisual(skill: Skill, defaultVisual: string): string {
        if (skill.ccType === 'PULL' || skill.name.includes("黑洞") || skill.name.includes("事件視界")) return 'BLACK_HOLE';
        if (skill.visual === 'FIREBALL' || skill.name.includes("烈焰") || skill.name.includes("燃燒") || skill.name.includes("隕石")) return 'BURNING_GROUND';
        if (skill.name.includes("毒") || skill.name.includes("腐化") || skill.name.includes("瘟疫")) return 'POISON_SWAMP';
        if (skill.name.includes("雪") || skill.name.includes("冰") || skill.name.includes("凍")) return 'FROST_FIELD';
        return defaultVisual || 'GENERIC_FIELD';
    },

    drawFieldEffect(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        visual: string, 
        color: string,
        time: number, 
        traceFn: () => void
    ) {
        ctx.save();

        // 1. Border
        ctx.lineWidth = 1.5;
        ctx.strokeStyle = color;
        ctx.globalAlpha = 0.4;
        traceFn(); 
        ctx.stroke();

        // 2. Interior Effects (Clipped)
        ctx.clip();

        if (visual === 'BLACK_HOLE' || visual === 'PULL') {
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            ctx.fill();
            // Suction lines
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.3;
            const offset = (time * 20) % 20;
            ctx.beginPath();
            for(let i=0; i<4; i++) {
                // Lines moving inward
                ctx.moveTo(x - 20 + i*10, y - 20 + offset);
                ctx.lineTo(x - 10 + i*10, y + 10 + offset);
            }
            ctx.stroke();

        } else if (visual === 'BURNING_GROUND' || visual === 'FIREBALL') {
            ctx.fillStyle = 'rgba(255, 100, 0, 0.15)';
            ctx.fill();
            // Embers
            const seed = x + y;
            const py = y - (time * 30 + seed) % 30 + 15;
            ctx.fillStyle = '#fbbf24';
            ctx.globalAlpha = 0.6;
            ctx.beginPath(); ctx.arc(x + Math.sin(time)*5, py, 2, 0, Math.PI*2); ctx.fill();

        } else if (visual === 'FROST_FIELD') {
            ctx.fillStyle = 'rgba(200, 240, 255, 0.2)';
            ctx.fill();
            // Sparkles
            if (Math.random() > 0.9) {
                ctx.fillStyle = '#fff';
                ctx.globalAlpha = 0.8;
                ctx.fillRect(x + (Math.random()-0.5)*20, y + (Math.random()-0.5)*10, 2, 2);
            }

        } else {
            // Generic Poison/Swamp
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.1;
            ctx.fill();
            // Bubbles
            const by = y - (time * 20 + x) % 30 + 15;
            ctx.strokeStyle = color;
            ctx.beginPath(); ctx.arc(x, by, 3, 0, Math.PI*2); ctx.stroke();
        }

        ctx.restore();
    }
};

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { SpriteManager } from "../../sprites";
import { Team } from "../../../types";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";

// =================================================================================
// 🧚 UNIT VISUAL EFFECTS (Flight, Casting, Status)
// =================================================================================

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171';

    const feetX = physX;
    const feetY = physY - physZ; 

    ctx.save();

    // 1. Ground Anchor (The Base)
    ctx.save();
    ctx.scale(1, 0.58); 
    ctx.lineDashOffset = -t * 20;

    // Outer dashed ring (Tech style)
    ctx.globalAlpha = 0.6;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.setLineDash([8, 4]);
    ctx.beginPath();
    ctx.arc(0, 0, 18, 0, Math.PI * 2);
    ctx.stroke();

    // Inner solid ring/plate
    ctx.setLineDash([]);
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.3;
    ctx.beginPath();
    ctx.arc(0, 0, 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // 2. Holographic Tether (The Lift)
    if (physZ > 5) {
        const grad = ctx.createLinearGradient(0, 0, feetX, feetY);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent'); 

        ctx.strokeStyle = grad;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.5;

        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(feetX, feetY);
        ctx.stroke();

        const pulseCount = 3;
        ctx.fillStyle = isBlue ? '#e0f2fe' : '#fecaca';
        ctx.globalAlpha = 0.8;

        for(let i=0; i<pulseCount; i++) {
            const p = (t * 0.8 + i / pulseCount) % 1.0; 
            const px = feetX * p;
            const py = feetY * p;
            const scale = 1 - p * 0.5;
            ctx.beginPath();
            ctx.ellipse(px, py, 4 * scale, 2 * scale, 0, 0, Math.PI*2);
            ctx.fill();
        }
    }

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 

    ctx.save();
    ctx.translate(0, 5); 
    ctx.scale(1, 0.5); 

    // Rotating Wind/Energy Swirl at Feet
    ctx.rotate(t * 8); 

    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.6;
    ctx.stroke();

    ctx.beginPath();
    for(let i=0; i<3; i++) {
        const offset = i * (Math.PI * 2 / 3);
        const arcLen = Math.PI / 2;
        ctx.moveTo(Math.cos(offset) * 18, Math.sin(offset) * 18);
        ctx.arc(0, 0, 18, offset, offset + arcLen);
    }

    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.5 + Math.sin(t * 20) * 0.2; 
    ctx.stroke();

    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    if (skill.tag === 'ULT') {
        drawUltimateChantVFX(ctx, agent, t);
        return;
    }

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    // 1. Rising Energy Lines
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 3; 
    const lineCount = 5 + Math.floor(progress * 8); 
    for(let i=0; i<lineCount; i++) {
        const h = (t * 150 + i * 40) % 90; 
        const alpha = 1 - (h / 90);
        const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
    }

    // 2. Converging Rings
    if (progress > 0.2) {
        const ringScale = (1 - progress) * 2.5; 
        ctx.globalAlpha = progress;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

        ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
        ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. Hand Glow
    ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

    // 4. Final Flash
    if (progress > 0.9) {
        ctx.globalAlpha = (progress - 0.9) * 10;
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
    }

    ctx.restore();
}

// 🌀 DOMAIN EXPANSION (Pre-Cast Chant)
// Renders a barrier/sphere that gathers energy
export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();

    // Calculate Sphere Pulse (Expands as cast nears completion)
    // 0.0 -> 0.8 scale (Starts small, expands to encompass unit)
    const size = 60 * (0.2 + progress * 0.8);
    const distortion = Math.sin(t * 20) * 2;

    ctx.translate(0, -40); // Chest/Center height

    // 1. The Domain Boundary (Sphere)
    // Using lighter composite for energy look
    ctx.globalCompositeOperation = 'screen';

    const grad = ctx.createRadialGradient(0, 0, size * 0.8, 0, 0, size);
    grad.addColorStop(0, 'rgba(0,0,0,0)');
    grad.addColorStop(0.5, color);
    grad.addColorStop(1, 'transparent');

    ctx.fillStyle = grad;
    ctx.globalAlpha = 0.4 + (progress * 0.4);
    ctx.beginPath();
    ctx.arc(0, 0, size + distortion, 0, Math.PI*2);
    ctx.fill();

    // 2. High-Speed Electrons (Orbiting particles)
    const particles = 3 + Math.floor(progress * 5);
    ctx.fillStyle = '#fff';

    for(let i=0; i<particles; i++) {
        // Orbit on different axes
        ctx.save();
        ctx.rotate(t * 2 + i * (Math.PI/particles));
        ctx.scale(1, 0.3); // Flatten to create 3D ring effect

        const px = Math.cos(t * 10 + i) * size;
        const py = Math.sin(t * 10 + i) * size;

        ctx.globalAlpha = 0.8;
        ctx.beginPath(); ctx.arc(px, py, 3, 0, Math.PI*2); ctx.fill();

        // Trail
        ctx.strokeStyle = color;
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.arc(0, 0, size, 0, Math.PI*2); ctx.stroke();

        ctx.restore();
    }

    // 3. Core Compression (Imploding energy)
    // Only visible near end
    if (progress > 0.6) {
        ctx.globalCompositeOperation = 'lighter';
        const implodeSize = 100 * (1 - progress);
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.globalAlpha = progress;

        ctx.beginPath();
        for(let i=0; i<4; i++) {
            ctx.moveTo(implodeSize, 0); ctx.lineTo(0,0);
            ctx.rotate(Math.PI/2);
        }
        ctx.stroke();
    }

    ctx.restore();
}

// Replaced complex rune with simple unit rune
export function drawSkillGroundIndicator(ctx: CanvasRenderingContext2D, x: number, y: number, color: string, t: number, progress: number, skillRadius: number, type: 'BASIC' | 'ACTIVE' | 'ULT', isAOE: boolean) {
