// 🛡️ TANK: IMPERIAL SANCTUARY (tb_u1)
// "Holographic Fortress": Six massive pillars form a hexagon, connecting with laser walls.
export function spawnImperialSanctuary(system: VFXSystem, x: number, y: number, color: string) {
    const radius = 160;

    // 1. Central Command Node
    const center = system.state.getParticle();
    center.x = x; center.y = y; center.z = 0;
    center.life = 3.5; center.maxLife = 3.5;
    center.color = '#fbbf24'; // Gold
    center.size = radius * 1.8;
    center.type = 'GRID_FIELD'; // Use clean hex grid
    system.state.particles.push(center);

    // 2. The Six Pillars
    for(let i=0; i<6; i++) {
        const angle = (i / 6) * Math.PI * 2;
        const px = x + Math.cos(angle) * radius;
        const py = y + Math.sin(angle) * radius;

        // Vertical Light Pillar
        const p = system.state.getParticle();
        p.x = px; p.y = py; p.z = 0;
        p.life = 0.5 + Math.random() * 0.5; p.maxLife = p.life;
        p.color = '#fef3c7'; // Pale Gold
        p.size = 20; 
        p.type = 'PILLAR'; // Uses the new clean beam style
        p.delay = i * 0.08; // Cascading activation
        system.state.particles.push(p);

        // Connection Lasers (The Walls)
        const nextAngle = ((i+1) / 6) * Math.PI * 2;
        const nx = x + Math.cos(nextAngle) * radius;
        const ny = y + Math.sin(nextAngle) * radius;

        const fence = system.state.getParticle();
        fence.x = px; fence.y = py; fence.z = 80; // Waist/Head height
        fence.targetX = nx; fence.targetY = ny;
        fence.life = 3.0; fence.maxLife = 3.0;
        fence.color = '#f59e0b';
        fence.size = 4;
        fence.type = 'BEAM';
        fence.delay = 0.3 + (i * 0.05);
        system.state.particles.push(fence);
    }
}

// 🛡️ TANK: KINGS BLESSING (tb_u2)
// "Ascension": Digital rings scan upward, granting invulnerability.
