// 🏹 RANGER: STARFALL (rb_u2)
// "Orbital Bombardment": Precision strikes in a pattern.
export function spawnImperialStarfall(system: VFXSystem, x: number, y: number, color: string) {
    const count = 12;
    const radius = 200;

    for(let i=0; i<count; i++) {
        // Spiral pattern
        const angle = (i / count) * Math.PI * 4; 
        const dist = (i / count) * radius;

        const px = x + Math.cos(angle) * dist;
        const py = y + Math.sin(angle) * dist;

        // Thin Lasers
        const beam = system.state.getParticle();
        beam.x = px; beam.y = py; beam.z = 0;
        beam.life = 0.2; beam.maxLife = 0.2;
        beam.color = '#fcd34d';
        beam.size = 6;
        beam.type = 'PILLAR';
        beam.delay = i * 0.08; 
        system.state.particles.push(beam);

        // Small Impacts
        setTimeout(() => {
            spawnExplosion(system, px, py, 0, 3, '#fff', 0.5, 0.3, 'SPARK');
        }, (i * 0.08) * 1000);
    }
}

