// 🛡️ TANK: GUILLOTINE (tr_u1)
// "Execution": Giant blade slams down, physical debris.
export function spawnCovenantGuillotine(system: VFXSystem, x: number, y: number, color: string) {
    // 1. The Blade (Fast vertical streak)
    // Modeled as a few large SHARD particles moving together
    const bladeHeight = 1000;
    for(let i=0; i<3; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*10;
        p.y = y;
        p.z = bladeHeight + i * 100; 

        p.vx = 0; p.vy = 0; p.vz = -4000; // Terminal velocity
        p.life = 0.25; p.maxLife = 0.25;
        p.color = '#7f1d1d'; // Dark Blood
        p.size = 60; // Huge blade
        p.type = 'SHARD'; 
        p.rotation = Math.PI/2; 
        system.state.particles.push(p);
    }

    // 2. Impact Blood Geyser (Timed to hit)
    setTimeout(() => {
        // Ground heavy crack
        addImpact(system, x, y, 0, '#ef4444', 'BLAST', 0.8);
        spawnExplosion(system, x, y, 0, 10, '#000', 1.0, 1.0, 'DEBRIS'); // Ground churn

        // Vertical blood spray
