        p.size = 30 + Math.random() * 20; 
        p.type = 'SMOKE';
        p.delay = delay + Math.random() * 0.5;
        system.state.particles.push(p);
    }
}

// 9. CAST INTERRUPT
export function spawnCastBreak(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    const blast = system.state.getParticle();
    blast.x = x; blast.y = y; blast.z = 40;
    blast.life = 0.25; blast.maxLife = 0.25;
    blast.color = '#00ffff'; blast.size = 80;
    blast.type = 'BLAST';
    system.state.particles.push(blast);

    for(let i=0; i<6; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*20; p.y = y + (Math.random()-0.5)*20; p.z = 40;
        p.vx = (Math.random()-0.5) * 100; p.vy = (Math.random()-0.5) * 100;
        p.life = 0.4; p.maxLife = 0.4;
        p.color = '#ff00ff'; p.size = 5; p.type = 'CHIP'; 
        system.state.particles.push(p);
    }
}

// 10. GRID IMPACT (Tile Highlight)
export function spawnGridImpact(system: VFXSystem, x: number, y: number, color: string, team: Team, delay: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.life = 1.0; p.maxLife = 1.0;
    p.color = color;
    p.size = 36; 
    p.type = 'GRID_FIELD'; 
    p.delay = delay;
    system.state.particles.push(p);
}

// 11. CONNECTOR SLASH (Melee)
export function spawnConnectorSlash(system: VFXSystem, x1: number, y1: number, x2: number, y2: number, color: string, visual: string) {
    // Not actually a particle, but a quick beam for now
    const p = system.state.getParticle();
    p.x = x1; p.y = y1 - 30; p.z = 30;
    p.targetX = x2; p.targetY = y2 - 30;
    p.life = 0.2; p.maxLife = 0.2;
    p.color = color; p.size = 12;
    p.type = 'BEAM'; 
    system.state.particles.push(p);
}

// 12. HELPER: Add generic impact
export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'RING' | 'BLAST' | 'SHOCKWAVE', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 30;
    p.type = type;
    system.state.particles.push(p);
}

// 13. DEATH RAY (Generic Beam)
export function spawnDeathRay(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 40;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.5; p.maxLife = 0.5;
    p.color = color;
    p.size = 10;
    p.type = 'DEATH_RAY';
    system.state.particles.push(p);
}

// 14. BLOOD RITUAL (Red Faction Ult Hit)
export function spawnBloodRitual(system: VFXSystem, x: number, y: number, color: string, scale: number) {
    // Impact Flash
    addImpact(system, x, y, 0, color, 'BLAST', 0.5);

    // Blood Mist
    for(let i=0; i<10; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*30 * scale;
        p.y = y + (Math.random()-0.5)*30 * scale;
        p.z = 5;
        p.vx = (Math.random()-0.5)*20;
        p.vy = (Math.random()-0.5)*20;
        p.vz = 50 + Math.random() * 100;
        p.life = 1.5; p.maxLife = 1.5;
        p.color = color;
        p.size = 20 + Math.random() * 10;
        p.type = 'SMOKE';
        system.state.particles.push(p);
    }
}

import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";

// Modular Spawners
import * as Generic from "../vfx/spawners/generic";
import * as Imperial from "../vfx/spawners/imperial";
import * as Covenant from "../vfx/spawners/covenant";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                }
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'IMPACT_AOE':
                if (event.skill) {
                    const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                    const radius = event.skill.aoeRadius || 1;
                    const affectedHexes = HexUtils.range(centerHex, radius);

                    const id = event.skill.id;
                    const color = event.color || '#fff';

                    // =================================================================
                    // 🔵 IMPERIAL (BLUE) ULTIMATE VFX MAPPING
                    // =================================================================

                    if (id === 'tb_u1') { // Sanctuary
                        Imperial.spawnImperialSanctuary(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.7); return;
                    }
                    if (id === 'tb_u2') { // Kings Blessing
                        Imperial.spawnImperialKingsBlessing(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3); return;
                    }
                    if (id === 'wb_u1') { // Thunder
                        Imperial.spawnImperialThunder(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6); return;
                    }
                    if (id === 'wb_u2') { // Daybreak
                        Imperial.spawnImperialDaybreak(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8); return;
                    }
                    if (id === 'rb_u1') { // Crystal Arrow
                        Imperial.spawnImperialCrystalArrow(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6); return;
                    }
                    if (id === 'rb_u2') { // Starfall
                        Imperial.spawnImperialStarfall(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.4); return;
                    }
                    if (id === 'mb_u1') { // Black Hole
                        Imperial.spawnImperialBlackHole(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.5); return;
                    }
                    if (id === 'mb_u2') { // Absolute Zero
                        Imperial.spawnImperialFrostfall(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.5); return;
                    }
                    if (id === 'sb_u1') { // Intervention
                        Imperial.spawnImperialIntervention(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3); return;
                    }
                    if (id === 'sb_u2') { // Resurrection
                        Imperial.spawnImperialResurrection(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.4); return;
                    }

                    // =================================================================
                    // 🔴 COVENANT (RED) ULTIMATE VFX MAPPING
                    // =================================================================

                    if (id === 'tr_u1') { // Guillotine
                        Covenant.spawnCovenantGuillotine(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8); return;
                    }
                    if (id === 'tr_u2') { // Undead Army
                        Covenant.spawnCovenantUndeadArmy(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.5); return;
                    }
                    if (id === 'wr_u1') { // Ragnarok
                        Covenant.spawnCovenantRagnarok(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.9); return;
                    }
                    if (id === 'wr_u2') { // Blood Storm
                        Covenant.spawnCovenantBloodStorm(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6); return;
                    }
                    if (id === 'rr_u1') { // Railgun
                        Covenant.spawnCovenantRailgun(vfx, event.pos.x - 200, event.pos.y, event.pos.x, event.pos.y, color);
                        camera.addTrauma(0.8); return;
                    }
                    if (id === 'rr_u2') { // Nuke
                        Covenant.spawnCovenantNuke(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8); return;
                    }
                    if (id === 'mr_u1') { // Meteor
                        Covenant.spawnCovenantMeteor(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.7); return;
                    }
                    if (id === 'mr_u2') { // Death Finger (AOE fallback)
                        Covenant.spawnCovenantDeathFinger(vfx, event.pos.x, event.pos.y - 200, event.pos.x, event.pos.y, color);
                        camera.addTrauma(0.7); return;
                    }
                    if (id === 'sr_u1') { // Soul Link
                        Covenant.spawnCovenantSoulLink(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3); return;
                    }
                    if (id === 'sr_u2') { // Ancestors
                        Covenant.spawnCovenantAncestors(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.3); return;
                    }

                    // Generic Grid Reaction
                    affectedHexes.forEach(h => {
                        if (engine.map.isValid(h.q, h.r)) {
                            const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                            const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                            const tileVisualY = tilePos.y - hHeight;
                            const dist = HexUtils.dist(centerHex, h);
                            const delay = dist * 0.06;

                            Generic.spawnGridImpact(vfx, tilePos.x, tileVisualY, event.color || '#fff', Team.BLUE, delay);
                        }
                    });
                }

                // Generic Fallback
                Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 0, 20, event.color || '#fff', 2.0, 0.6, 'SPARK');
                Generic.addImpact(vfx, event.pos.x, visualGroundY, 0, event.color || '#fff', 'BLAST', 0.5);
                Generic.spawnShockwave(vfx, event.pos.x, visualGroundY, event.color || '#fff', 0.6);
                camera.addTrauma(0.25); 
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                } else {
                    const hitColor = event.skill?.color || '#fff';
                    Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 20, 8, hitColor, 1.0, 0.3, 'SPARK');
                }
                break;

            case 'DEATH':
                // Look for the agent in the engine (it might still exist in the array briefly)
                // OR we pass the team/role/velocity directly in the event data if agent is already gone from array.
                // The AgentManager handles 'fullyDead' later, so agent *should* still be findable by ID.
                const dAgent = engine.agents.find(a => a.id === event.sourceId);

                if (dAgent) {
                    // Extract physics momentum to give the ragdoll debris direction
                    const vx = dAgent.physics.vx || 0;
                    const vy = dAgent.physics.vy || 0;

                    Generic.spawnUnitShatter(
                        vfx, 
                        event.pos.x, 
                        visualGroundY, 
                        dAgent.team, 
                        dAgent.role,
                        vx,
                        vy
                    );
                }
                camera.addTrauma(0.15); // Increased trauma on death
                break;

            case 'SPAWN':
                Generic.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                Generic.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                Generic.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                // Red Mage Death Finger (mr_u2) - Single Target Special
                if (event.skill?.id === 'mr_u2') {
                    Generic.spawnDeathRay(vfx, source.px, source.py - sH - 45, event.pos.x, visualGroundY - 30, event.color || '#be123c');
                    return;
                }

                Generic.spawnBeam(vfx, source.px, source.py - sH - 40, 0, event.pos.x, visualGroundY - 30, 0, event.color || '#fff');
                Generic.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';
                    Generic.spawnDirectionalImpact(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, event.color || '#fff', type);
                }
            }
        } else {
            Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
        }

        if (dmg > 50) camera.addTrauma(0.05); 
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.15); 

            // Death Finger target hit check
            if (skill && skill.id === 'mr_u2') {
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#000', 3.0, 0.5, 'SPARK');
                Generic.addImpact(vfx, event.pos.x, visualY, 20, '#be123c', 'BLAST', 0.5);
                Generic.spawnShockwave(vfx, event.pos.x, visualY, '#000', 0.5);
                return; 
            }

            // FACTION RITUAL (Ult Hit)
            if (faction === Team.BLUE) {
                // Remove Pillar fallback. Use pure explosion/shockwave.
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.5, 0.8, 'SPARK');
                Generic.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 0.8);
            } else {
                // Red faction uses Blood Ritual
                Generic.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            if (skill && skill.id === 'wr_u1') { // Ragnarok Hit
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#991b1b', 2.0, 1.0, 'DEBRIS');
                Generic.addImpact(vfx, event.pos.x, visualY, 0, '#ef4444', 'BLAST', 0.8);
                camera.addTrauma(0.5);
            } 

        } else {
            // Standard Hits
            if (visualType === 'SMASH') {
                Generic.addImpact(vfx, event.pos.x, centerVisualY, 0, color, 'SHOCKWAVE', 0.4);
                Generic.spawnExplosion(vfx, event.pos.x, centerVisualY, 0, 8, color, 0.5, 0.6, 'SHARD'); 
            } 
            else if (visualType === 'SLASH') {
                if (source) {
                    const dx = event.pos.x - source.px;
                    const dy = event.pos.y - source.py;
                    const len = Math.sqrt(dx*dx + dy*dy) || 1;
                    Generic.spawnDirectionalImpact(vfx, event.pos.x, visualY, 30, dx/len, dy/len, color, 'PHYSICAL');
                } else {
                    Generic.spawnExplosion(vfx, event.pos.x, visualY, 30, 8, color, 1.5, 0.4, 'SPARK');
                }
            }
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                Generic.addImpact(vfx, event.pos.x, visualY, 20, color, 'BLAST', 0.5);
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 20, 5, color, 0.5, 1.0, 'SMOKE');
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 20, 8, '#fff', 1.0, 0.3, 'SPARK');
            }
            else {
                Generic.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.4);
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 2.0, 0.4, 'SPARK');
            }
        }
    }
}

import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { Skill } from "../../types";
import { isChaosStyle } from "../systems/vfx/utils";

// Procedural Noise function reuse
function noise(q: number, r: number) {
    return Math.sin(q * 12.9898 + r * 78.233) * 43758.5453 - Math.floor(Math.sin(q * 12.9898 + r * 78.233) * 43758.5453);
}

// Precomputed Hex for Geometry
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

export const SurfaceAssets = {

    // =================================================================================
    // 🌍 TERRAIN TEXTURES (Static Details)
    // =================================================================================

    drawTexture(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        color: string,
        globalTime: number
    ) {
        ctx.save();
        ctx.fillStyle = color;
        ctx.strokeStyle = color;

        const n = noise(q, r);
        const time = globalTime;

        if (type === 'MAGMA') {
            const pulse = 0.5 + Math.sin(time + n * 10) * 0.5;
            ctx.strokeStyle = 'rgba(40, 5, 5, 0.7)'; 
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(cx - 12, cy + 5); ctx.lineTo(cx - 5, cy - 2);
            ctx.lineTo(cx + 8, cy + 3); ctx.lineTo(cx + 15, cy - 5);
            ctx.stroke();

            if (pulse > 0.8) {
                ctx.fillStyle = '#ef4444';
                ctx.globalAlpha = (pulse - 0.8) * 3; 
                ctx.beginPath(); ctx.arc(cx - 5, cy - 2, 2, 0, Math.PI*2); ctx.fill();
            }

        } else if (type === 'VOID') {
            ctx.globalAlpha = 0.3;
            if (n > 0.3) {
                ctx.fillStyle = '#38bdf8';
                ctx.beginPath(); ctx.arc(cx, cy, 2, 0, Math.PI*2); ctx.fill();
                ctx.strokeStyle = '#38bdf8';
                ctx.lineWidth = 1;
                ctx.beginPath();
                if (n > 0.6) { ctx.moveTo(cx, cy); ctx.lineTo(cx + 15, cy - 8); }
                if (n < 0.4) { ctx.moveTo(cx, cy); ctx.lineTo(cx - 15, cy + 8); }
                ctx.stroke();
            }
            const packetTime = (time * 0.5 + n) % 2; 
            if (packetTime < 1.0) {
                ctx.globalAlpha = 1.0 - packetTime; 
                ctx.fillStyle = '#bae6fd';
                const px = cx + (Math.cos(n * 10) * 20 * packetTime);
                const py = cy + (Math.sin(n * 10) * 10 * packetTime);
                ctx.fillRect(px, py, 2, 2);
            }

        } else if (type === 'FOREST') {
            ctx.globalAlpha = 0.6;
            const tufts = Math.floor(n * 3) + 2;
            for(let i=0; i<tufts; i++) {
                const ox = (noise(q+i, r) - 0.5) * 20;
                const oy = (noise(r, q+i) - 0.5) * 12;
                const wind = Math.sin(time * 2 + cx * 0.05 + i) * 3;
                ctx.beginPath();
                ctx.moveTo(cx + ox, cy + oy);
                ctx.quadraticCurveTo(cx + ox - 2 + wind, cy + oy - 6, cx + ox - 4 + wind * 1.5, cy + oy - 8);
                ctx.lineWidth = 1.5;
                ctx.strokeStyle = i % 2 === 0 ? '#4ade80' : '#22c55e';
                ctx.stroke();
            }

        } else if (type === 'ICE') {
            ctx.globalAlpha = 0.3; ctx.fillStyle = '#fff';
            if (n > 0.4) {
                ctx.beginPath();
                ctx.moveTo(cx - 15, cy + 2); ctx.lineTo(cx + 5, cy - 8);
                ctx.lineTo(cx + 15, cy - 4); ctx.lineTo(cx - 5, cy + 8);
                ctx.fill();
            }

        } else if (type === 'DESERT') {
            ctx.globalAlpha = 0.2; ctx.strokeStyle = '#92400e'; ctx.lineWidth = 2;
            const offset = (time * 5) % 20; 
            ctx.beginPath();
            for(let i=0; i<2; i++) {
                const yBase = cy - 10 + i * 15;
                const shift = offset + (n * 20); 
                const xStart = cx - 15 + (shift % 10);
                ctx.moveTo(xStart, yBase);
                ctx.quadraticCurveTo(xStart + 10, yBase - 3, xStart + 20, yBase);
            }
            ctx.stroke();
        }
        ctx.restore();
    },

    // =================================================================================
    // 🎯 TACTICAL GRID VISUALS (Redesigned v2.0)
    // =================================================================================

    drawTacticalGrid(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        progress: number, 
        isCenter: boolean
    ) {
        ctx.save();
        ctx.translate(x, y);

        const isChaos = isChaosStyle(color);
        const intensity = 0.3 + (progress * 0.7); // 0.3 -> 1.0

        if (isChaos) {
            // --- COVENANT STYLE (Jagged, Breathing) ---
            ctx.globalCompositeOperation = 'source-over';

            // 1. Fill (Darker, pulsing)
            ctx.beginPath();
            for (let i = 0; i < 6; i++) {
                const c = HEX_CORNERS[i];
                // REMOVED JITTER: Vertices are now strictly aligned to grid
                if (i === 0) ctx.moveTo(c.x, c.y);
                else ctx.lineTo(c.x, c.y);
            }
            ctx.closePath();

            ctx.fillStyle = color;
            ctx.globalAlpha = 0.1 + (Math.sin(Date.now() * 0.01) * 0.05);
            ctx.fill();

            // 2. Warning Border (Dashed)
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = intensity;
            ctx.setLineDash([10, 5]);
            ctx.stroke();

            // 3. Center Cracks (Visual flavor inside strictly)
            if (isCenter) {
                ctx.setLineDash([]);
                ctx.beginPath();
                ctx.moveTo(-8, 0); ctx.lineTo(8, 0);
                ctx.moveTo(0, -4); ctx.lineTo(0, 4);
                ctx.stroke();
            }

        } else {
            // --- IMPERIAL STYLE (Holographic, Scanning) ---
            ctx.globalCompositeOperation = 'screen';

            // 1. Hex Border (Clean)
            ctx.beginPath();
            for (let i = 0; i < 6; i++) {
                const c = HEX_CORNERS[i];
                if (i === 0) ctx.moveTo(c.x, c.y);
                else ctx.lineTo(c.x, c.y);
            }
            ctx.closePath();

            ctx.lineWidth = 2;
            ctx.strokeStyle = color;
            ctx.globalAlpha = intensity * 0.8;
            ctx.shadowColor = color;
            ctx.shadowBlur = 5;
            ctx.stroke();
            ctx.shadowBlur = 0;

            // 2. Scanline Effect
            ctx.save();
            ctx.clip();

            // Moving scanline
            const scanY = ((Date.now() / 1500) % 1.0) * (HEX_SIZE * 2 * ISO_SCALE_Y) - (HEX_SIZE * ISO_SCALE_Y);
            ctx.beginPath();
            ctx.moveTo(-HEX_SIZE, scanY);
            ctx.lineTo(HEX_SIZE, scanY);
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.5;
            ctx.stroke();

            // Fill tint
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.1;
            ctx.fill();

            ctx.restore();

            // 3. Center Lock
            if (isCenter) {
                ctx.beginPath();
                ctx.arc(0, 0, 5, 0, Math.PI*2);
                ctx.fillStyle = '#fff';
                ctx.globalAlpha = 0.8;
                ctx.fill();
                ctx.strokeStyle = color;
                ctx.lineWidth = 1;
                ctx.beginPath(); ctx.arc(0, 0, 12, 0, Math.PI*2); ctx.stroke();
            }
        }

        ctx.restore();
    },

    // Kept for Unit Feet (Small personal rune)
    drawUnitRune(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        t: number, 
        progress: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); // Isometric

        const r = HEX_SIZE * 0.8;

        ctx.globalAlpha = 0.4 * progress;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;

        // Simple Spinning Ring
        ctx.beginPath();
        ctx.arc(0, 0, r, 0, Math.PI*2);
        ctx.stroke();

        // Inner spinning bits
        ctx.rotate(t);
        ctx.beginPath();
        ctx.rect(-r*0.6, -r*0.6, r*1.2, r*1.2);
        ctx.stroke();

        ctx.restore();
    },

    // =================================================================================
    // ☢️ FIELD EFFECTS (Active Zones)
    // =================================================================================

    resolveFieldVisual(skill: Skill, defaultVisual: string): string {
        if (skill.ccType === 'PULL' || skill.name.includes("黑洞") || skill.name.includes("事件視界")) return 'BLACK_HOLE';
        if (skill.visual === 'FIREBALL' || skill.name.includes("烈焰") || skill.name.includes("燃燒") || skill.name.includes("隕石")) return 'BURNING_GROUND';
        if (skill.name.includes("毒") || skill.name.includes("腐化") || skill.name.includes("瘟疫")) return 'POISON_SWAMP';
        if (skill.name.includes("雪") || skill.name.includes("冰") || skill.name.includes("凍")) return 'FROST_FIELD';
        return defaultVisual || 'GENERIC_FIELD';
    },

    drawFieldEffect(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        visual: string, 
        color: string,
        time: number, 
        traceFn: () => void
    ) {
        ctx.save();

        // 1. Border
        ctx.lineWidth = 1.5;
        ctx.strokeStyle = color;
        ctx.globalAlpha = 0.4;
        traceFn(); 
        ctx.stroke();

        // 2. Interior Effects (Clipped to Hex)
        // CRITICAL: We clip here to ensure strict hex containment
        ctx.clip();

        if (visual === 'BLACK_HOLE' || visual === 'PULL') {
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            ctx.fill();
            // Suction lines (Visual Only, clipped)
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.3;
            const offset = (time * 20) % 20;
            ctx.beginPath();
            for(let i=0; i<4; i++) {
                // Lines moving inward
                ctx.moveTo(x - 20 + i*10, y - 20 + offset);
                ctx.lineTo(x - 10 + i*10, y + 10 + offset);
            }
            ctx.stroke();

        } else if (visual === 'BURNING_GROUND' || visual === 'FIREBALL') {
            ctx.fillStyle = 'rgba(255, 100, 0, 0.15)';
            ctx.fill();
            // Embers (Clipped)
            const seed = x + y;
            const py = y - (time * 30 + seed) % 30 + 15;
            ctx.fillStyle = '#fbbf24';
            ctx.globalAlpha = 0.6;
            ctx.beginPath(); ctx.arc(x + Math.sin(time)*5, py, 2, 0, Math.PI*2); ctx.fill();

        } else if (visual === 'FROST_FIELD') {
            ctx.fillStyle = 'rgba(200, 240, 255, 0.2)';
            ctx.fill();
            // Sparkles
            if (Math.random() > 0.9) {
                ctx.fillStyle = '#fff';
                ctx.globalAlpha = 0.8;
                ctx.fillRect(x + (Math.random()-0.5)*20, y + (Math.random()-0.5)*10, 2, 2);
            }

        } else {
            // Generic Poison/Swamp
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.1;
            ctx.fill();
            // Bubbles
            const by = y - (time * 20 + x) % 30 + 15;
            ctx.strokeStyle = color;
            ctx.beginPath(); ctx.arc(x, by, 3, 0, Math.PI*2); ctx.stroke();
        }

        ctx.restore();
    }
};

import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { AssetManager } from "../../../assets";
import { ISO_SCALE_Y } from "../../../../constants";

// Helper: Draw Hexagon Path centered at 0,0
function drawHexPath(ctx: CanvasRenderingContext2D, radius: number) {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
        const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
        const x = radius * Math.cos(angle);
        const y = radius * Math.sin(angle) * ISO_SCALE_Y; 
        if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    }
    ctx.closePath();
}

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Context is already translated to Visual Position (Ground Y - Z)
        ctx.translate(p.x, p.y);

        // --- PHYSICAL SHADOW PASS ---
        if (['DEBRIS', 'SHARD', 'SPRITE'].includes(p.type) && p.z > 5) {
            ctx.save();
            ctx.translate(0, p.z); // Move "down" to ground level
            ctx.scale(1, 0.5); // Isometric shadow squash
            const shadowAlpha = Math.max(0, 0.3 - (p.z / 400)); // Lighter shadow
            if (shadowAlpha > 0) {
                ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
                const shadowSize = p.size * 0.8;
                ctx.beginPath(); ctx.arc(0, 0, shadowSize, 0, Math.PI * 2); ctx.fill();
            }
            ctx.restore();
        }

        // --- RENDER LOGIC BY TYPE ---

        if (p.type === 'SPARK') {
            // ✨ KINETIC SPARKS (Light Streaks)
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy + p.vz*p.vz);
            const stretch = Math.min(4.0, 1.0 + speed / 150); 
            const angle = Math.atan2(p.vy, p.vx); 

            ctx.rotate(angle);
            ctx.scale(stretch, 0.6); 

            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = Math.pow(1 - progress, 2); 

            // Streamlined Shape
            const grad = ctx.createLinearGradient(-p.size, 0, p.size, 0);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.2, p.color);
            grad.addColorStop(0.8, '#fff'); 
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.5, 0, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'SMOKE') {
            // ☁️ VOLUMETRIC SMOKE
            const scale = 0.5 + progress * 2.0; 
            const alpha = (1 - progress) * 0.6; 

            ctx.scale(scale, scale);
            ctx.rotate(p.rotation + progress * 0.5); 
            ctx.globalAlpha = alpha;

            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, p.size);
            grad.addColorStop(0, p.color);
            grad.addColorStop(1, 'rgba(0,0,0,0)'); 

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.arc(0, 0, p.size, 0, Math.PI*2);
            ctx.arc(p.size*0.5, p.size*0.5, p.size*0.6, 0, Math.PI*2);
            ctx.arc(-p.size*0.4, -p.size*0.3, p.size*0.7, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'RING') {
            // 🌊 ENERGY RIPPLE
            ctx.scale(1, 0.55); 
            const r = progress * p.size * 2; 

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 4;
            ctx.globalAlpha = 1 - progress;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

            if (progress > 0.2) {
                ctx.lineWidth = (1 - progress) * 2;
                ctx.globalAlpha = (1 - progress) * 0.5;
                ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI * 2); ctx.stroke();
            }

        } else if (p.type === 'BLAST') {
            // 💥 SPIKED EXPLOSION
            ctx.scale(1, 0.55); 
            const r = p.size * (progress); 

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 6; 
            ctx.globalAlpha = (1 - progress);

            ctx.beginPath(); 
            const spikes = 12;
            for(let i=0; i<=spikes; i++) {
                const angle = (i/spikes) * Math.PI*2;
                const rad = r * (1.0 + (i%2===0 ? 0.2 : 0)); 
                const px = Math.cos(angle) * rad;
                const py = Math.sin(angle) * rad;
                if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
            }
            ctx.closePath();
            ctx.stroke();

        } else if (p.type === 'DEBRIS' || p.type === 'SHARD' || p.type === 'CHIP') {
            // 💎 MATERIAL
            ctx.rotate(p.rotation);

            const grad = ctx.createLinearGradient(-p.size, -p.size, p.size, p.size);
            grad.addColorStop(0, '#ffffff'); 
            grad.addColorStop(0.3, p.color);
            grad.addColorStop(1, '#000000'); 

            ctx.fillStyle = grad;
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 1;

            if (p.type === 'CHIP') {
                ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
            } else {
                ctx.beginPath();
                ctx.moveTo(-p.size, -p.size/2); 
                ctx.lineTo(p.size * 0.8, -p.size * 0.2); 
                ctx.lineTo(0, p.size); 
                ctx.lineTo(-p.size * 0.5, p.size * 0.5);
                ctx.closePath();
                ctx.fill();
                ctx.stroke();
            }

        } else if (p.type === 'GLOW') {
            const img = AssetManager.getGlowSprite(p.color);
            const fade = Math.sin(progress * Math.PI); 
            const scale = (p.size / 64) * (0.8 + fade * 0.4); 

            ctx.globalAlpha = fade * 0.9;
            ctx.globalCompositeOperation = 'screen'; 
            ctx.scale(scale, scale);
            ctx.drawImage(img, -32, -32);

        } else if (p.type === 'SPRITE') {
            if (p.image) {
                const alpha = Math.max(0, 1 - Math.pow(progress, 3)); 
                ctx.globalAlpha = alpha;
                ctx.rotate(p.rotation + progress * 5);
                const perspective = 1.0 + (p.z * 0.002);
                const scale = (p.size / 64) * perspective * (1 - progress * 0.5); 
                ctx.scale(scale, scale);
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);
            }

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                this.drawHelixBeam(ctx, p, progress);
            }
        } else if (p.type === 'DEATH_RAY') {
            this.drawDeathRay(ctx, p, progress);
        } else if (p.type === 'PILLAR') {
            this.drawDivinePillar(ctx, p, progress);
        } else if (p.type === 'SHOCKWAVE') {
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            this.drawDomainArea(ctx, p, progress);
        } else if (p.type === 'GRID_FIELD') {
            this.drawGridField(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    // ⚡ HELIX BEAM
    drawHelixBeam(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.translate(-p.x, -p.y); 
        ctx.globalCompositeOperation = 'lighter';

        const sx = p.x; const sy = p.y;
        const tx = p.targetX!; const ty = p.targetY!;
        const dx = tx - sx;
        const dy = ty - sy;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const angle = Math.atan2(dy, dx);

        const beamWidth = 6 * (1 - Math.pow(progress, 3)); 
        if (beamWidth < 0.2) return;

        ctx.save();
        ctx.translate(sx, sy);
        ctx.rotate(angle);

        // Core
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = Math.max(2, beamWidth * 0.5);
        ctx.lineCap = 'round';
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(dist, 0); ctx.stroke();

        // Glow
        ctx.strokeStyle = p.color;
        ctx.lineWidth = beamWidth * 2.5; 
        ctx.globalAlpha = 0.5 * (1 - progress);
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(dist, 0); ctx.stroke();

        // Helix
        const freq = 0.12; 
        const amp = 8 * (1 - progress); 
        const phase = Date.now() * 0.025; 

        ctx.lineWidth = 2; 
        ctx.globalAlpha = 0.9 * (1 - progress);
        ctx.strokeStyle = p.color; 

        ctx.beginPath();
        for(let i=0; i<=dist; i+=5) {
            const yOffset = Math.sin(i * freq - phase) * amp;
            if(i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
        }
        ctx.stroke();

        ctx.beginPath();
        for(let i=0; i<=dist; i+=5) {
            const yOffset = Math.sin(i * freq - phase + Math.PI) * amp;
            if(i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
        }
        ctx.stroke();

        // Flares
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 1 - progress;
        ctx.beginPath(); ctx.arc(0, 0, beamWidth * 1.5, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(dist, 0, beamWidth * 2.5, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    // ☠️ DEATH RAY (High Velocity Particle Beam)
    drawDeathRay(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.translate(-p.x, -p.y); 

        const sx = p.x; const sy = p.y;
        const tx = p.targetX!; const ty = p.targetY!;
        const dx = tx - sx;
        const dy = ty - sy;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const angle = Math.atan2(dy, dx);

        ctx.save();
        ctx.translate(sx, sy);
        ctx.rotate(angle);

        const alpha = Math.pow(1 - progress, 2);

        // 1. Dark Void Core (Source-Over to block light)
        ctx.globalCompositeOperation = 'source-over'; 
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 4 * alpha;
        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

        // 2. Intense Crimson Glow (Lighter)
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = p.color; 
        ctx.lineWidth = 12 * alpha;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 20;
        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();
        ctx.shadowBlur = 0;

        // 3. White Hot Needle Center
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2 * alpha;
        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

        // 4. Chaotic Crackles
        ctx.strokeStyle = '#fca5a5'; 
        ctx.lineWidth = 2 * alpha;
        ctx.beginPath();
        let cx = 0;
        ctx.moveTo(0, 0);
        const segmentLen = 40;
        const steps = Math.ceil(dist / segmentLen);
        for(let i=0; i<steps; i++) {
            cx += segmentLen;
            const cy = (Math.random() - 0.5) * 20 * alpha;
            ctx.lineTo(cx, cy);
        }
        ctx.lineTo(dist, 0);
        ctx.stroke();

        ctx.restore();
    },

    // 🌫️ VOLUMETRIC GRID FOG (Strict Hex Geometry)
    drawGridField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        const size = 36; // Matching Tile Size
        const fade = Math.sin(progress * Math.PI); 
        ctx.save();

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over';

            // REMOVED JITTER TRANSLATION to ensure strict alignment with tile
            // ctx.translate(jitter, jitter); <- DELETED

            // Clip to Hex shape first
            drawHexPath(ctx, size);
            ctx.clip();

            ctx.fillStyle = `rgba(20, 5, 5, ${fade * 0.8})`;
            ctx.fill();

            ctx.strokeStyle = p.color; 
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade;
            ctx.beginPath();
            ctx.moveTo(-20, -10); ctx.lineTo(-10, 5); ctx.lineTo(5, -5); ctx.lineTo(20, 10);
            ctx.moveTo(0, 0); ctx.lineTo(-5, 15);
            ctx.stroke();

        } else {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 4;
            ctx.globalAlpha = fade * 0.4;
            drawHexPath(ctx, size);
            ctx.stroke();

            ctx.lineWidth = 2;
            ctx.globalAlpha = fade * 0.8;
            drawHexPath(ctx, size);
            ctx.stroke();

            ctx.fillStyle = p.color;
            ctx.globalAlpha = fade * 0.2;
            ctx.fill();
        }
        ctx.restore();
    },

    // 🏛️ DIVINE PILLAR 4.0: THIN SHAFT (Clean Edition)
    drawDivinePillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const lifeRatio = p.life / p.maxLife;

        let alpha = 0;
        if (lifeRatio > 0.8) alpha = (1 - lifeRatio) * 5; 
        else if (lifeRatio < 0.3) alpha = lifeRatio * 3.3; 
        else alpha = 1.0;

        const height = 800; 
        const width = p.size; // Strictly respects spawn size

        // --- 1. THE BEAM CORE ---
        ctx.save();
        // Use source-over to prevent additive blowout when multiple beams overlap
        ctx.globalCompositeOperation = 'source-over'; 

        const beamGrad = ctx.createLinearGradient(-width, 0, width, 0);
        beamGrad.addColorStop(0, 'rgba(255,255,255,0)');
        beamGrad.addColorStop(0.2, p.color);
        beamGrad.addColorStop(0.5, 'rgba(255,255,255,0.6)'); 
        beamGrad.addColorStop(0.8, p.color);
        beamGrad.addColorStop(1, 'rgba(255,255,255,0)');

        // Vertical fade
        const vGrad = ctx.createLinearGradient(0, 0, 0, -height);
        vGrad.addColorStop(0, 'rgba(255,255,255,1)');
        vGrad.addColorStop(0.8, 'rgba(255,255,255,0.5)');
        vGrad.addColorStop(1, 'rgba(255,255,255,0)');

        ctx.fillStyle = beamGrad;
        ctx.globalAlpha = alpha * 0.7; 
        ctx.fillRect(-width, -height, width * 2, height);

        // --- 2. GROUND RIPPLE (Impact Ring) ---
        ctx.save();
        ctx.globalCompositeOperation = 'screen';

        // Use Hex Path for strict ground alignment, though Pillar is usually circular energy.
        // But to keep consistency with "Grid Constraint", let's use a circle fitting the hex or just a circle.
        // Pillars are vertical, so a circle base is usually acceptable, but let's stick to circle here as it's a "point" effect.
        // Wait, user asked for "AOE type effects to be strictly constrained". Pillar is often single target or small AOE.
        // Let's keep circle for pillar base as it is a "beam", but ensure it doesn't bleed.

        const ringSize = width * 1.5 * (0.5 + (1-lifeRatio)); 
        ctx.scale(1, 0.58); 

        ctx.strokeStyle = p.color;
        ctx.lineWidth = 2;
        ctx.globalAlpha = alpha * 0.9;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.stroke();

        ctx.fillStyle = '#fff';
        ctx.globalAlpha = alpha * 0.6;
        ctx.beginPath(); ctx.arc(0, 0, width * 0.5, 0, Math.PI*2); ctx.fill();

        ctx.restore();
        ctx.restore();
    },

    // 🩸 DOMAIN (Active Field Visuals) - CHANGED TO HEXAGONAL GEOMETRY
    drawDomainArea(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
         const lifeRatio = p.life / p.maxLife;
         const alpha = Math.sin(lifeRatio * Math.PI); 
         const r = p.size;
         const isChaos = isChaosStyle(p.color);

         ctx.save();
         // No scale(1, 0.55) needed because drawHexPath handles ISO_SCALE_Y internally!
         // Wait, drawHexPath uses ISO_SCALE_Y on the Y coordinate calculation.
         // So we pass raw radius.

         if (isChaos) {
             // Chaos: Void Vortex -> Hexagonal Void
             ctx.globalCompositeOperation = 'source-over'; 
             const voidGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
             voidGrad.addColorStop(0, 'rgba(0,0,0,0.9)'); 
             voidGrad.addColorStop(0.6, 'rgba(0,0,0,0.8)');
             voidGrad.addColorStop(0.8, p.color); 
             voidGrad.addColorStop(1, 'transparent');

             ctx.fillStyle = voidGrad;
             ctx.globalAlpha = alpha * 0.8; 
             drawHexPath(ctx, r);
             ctx.fill();
         } else {
             // Order: Holy Ground -> Hexagonal Light Area
             ctx.globalCompositeOperation = 'screen'; // Light adds up

             // 1. Base Glow (Soft Gradient)
             const lightGrad = ctx.createRadialGradient(0, 0, r * 0.6, 0, 0, r);
             lightGrad.addColorStop(0, 'rgba(0,0,0,0)'); // Transparent center
             lightGrad.addColorStop(0.8, p.color); // Glowing rim
             lightGrad.addColorStop(1, 'transparent');

             ctx.fillStyle = lightGrad;
             ctx.globalAlpha = alpha * 0.6; 
             drawHexPath(ctx, r);
             ctx.fill();

             // 2. Heavy Hex Border
             ctx.strokeStyle = p.color;
             ctx.lineWidth = 4;
             ctx.globalAlpha = alpha;
             drawHexPath(ctx, r * 0.9);
             ctx.stroke();

             // 3. Inner decorative Hex
             ctx.strokeStyle = '#fff';
             ctx.lineWidth = 1;
             ctx.setLineDash([10, 10]);
             drawHexPath(ctx, r * 0.7);
             ctx.stroke();
         }

         // Cracks / Runes (Rotating)
         // For hex logic, rotating lines might look weird if they exceed hex bounds.
         // Let's clip them to the hex.
         ctx.save();
         drawHexPath(ctx, r);
         ctx.clip();

         ctx.strokeStyle = p.color; 
         ctx.lineWidth = 3;
         ctx.globalAlpha = alpha;
         ctx.beginPath();
         for(let i=0; i<6; i++) {
             const angle = i * (Math.PI/3) + progress;
             ctx.moveTo(0,0);
             ctx.lineTo(Math.cos(angle)*r, Math.sin(angle)*r * ISO_SCALE_Y); // Apply ISO to lines too
         }
         ctx.stroke();
         ctx.restore();

         // Rising Energy (The Cylinder effect)
         ctx.globalCompositeOperation = 'lighter';
         const heatGrad = ctx.createLinearGradient(0, 0, 0, -300);
         heatGrad.addColorStop(0, p.color);
         heatGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = heatGrad;
         ctx.globalAlpha = alpha * 0.2;
         ctx.beginPath();
         // Simple vertical sheet constrained to width
         ctx.moveTo(-r/2, 0); ctx.lineTo(-r/4, -300); ctx.lineTo(r/4, -300); ctx.lineTo(r/2, 0);
         ctx.fill();

         ctx.restore();
    },

    // 🌊 SHOCKWAVE - CHANGED TO HEXAGONAL RIPPLE
    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        // No pre-scale needed if using drawHexPath which applies ISO
        const r = progress * p.size; // Expands to max size
        const width = 30 * (1 - progress);

        ctx.globalAlpha = (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over'; 
            // Jagged Hex Ripple
            ctx.beginPath();
            for(let i=0; i<=6; i++) {
                const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
                // Add noise to vertices but keep general hex shape
                const noise = (Math.random() - 0.5) * 10;
                const rx = (r + noise) * Math.cos(angle);
                const ry = (r + noise) * Math.sin(angle) * ISO_SCALE_Y;
                if(i===0) ctx.moveTo(rx, ry); else ctx.lineTo(rx, ry);
            }
            ctx.closePath();
            ctx.stroke();
        } else {
            ctx.globalCompositeOperation = 'lighter';
            drawHexPath(ctx, r);
            ctx.stroke();
        }
    }
};

import { Role, Team } from "../../types";
import { PALETTE } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Dimensions
const BASE_SIZE = 128;
const ICON_SIZE = 64;

export const UnitFactory = {

    generateTokenBase(team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BASE_SIZE, BASE_SIZE);
        const cx = BASE_SIZE / 2;
        const cy = BASE_SIZE / 2;
        const radius = 36; 
        const isBlue = team === Team.BLUE;

        ctx.translate(cx, cy);
        ctx.scale(1, 0.58); // Isometric projection

        // 1. Drop Shadow (Heavy grounding)
        ctx.fillStyle = 'rgba(0,0,0,0.6)';
        ctx.beginPath(); 
        ctx.arc(0, 8, radius + 4, 0, Math.PI*2); 
        ctx.fill();

        // 2. Physical Material Body
        if (isBlue) {
            // --- IMPERIAL (Ultramarines Style) ---
            // Ceramite Blue Body
            const grad = ctx.createLinearGradient(-radius, -radius, radius, radius);
            grad.addColorStop(0, '#2563eb'); // Bright Cobalt
            grad.addColorStop(1, '#172554'); // Deep Navy
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI*2); ctx.fill();

            // Gold Trim (Aquila Style)
            ctx.strokeStyle = '#b45309'; // Dark Gold shadow
            ctx.lineWidth = 6;
            ctx.stroke();
            ctx.strokeStyle = '#fcd34d'; // Bright Gold highlight
            ctx.lineWidth = 3;
            ctx.stroke();

            // Inner Tech/Auspex Ring
            ctx.beginPath(); ctx.arc(0, 0, radius * 0.7, 0, Math.PI*2);
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)'; 
            ctx.lineWidth = 1;
            ctx.setLineDash([4, 2]);
            ctx.stroke();
            ctx.setLineDash([]);

            // Omega / Tactical Symbol Hint
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.2;
            ctx.font = 'bold 24px sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('Ω', 0, 2);

        } else {
            // --- CHAOS (Khorne Style) ---
            // Blood-stained Brass & Iron
            const grad = ctx.createLinearGradient(-radius, -radius, radius, radius);
            grad.addColorStop(0, '#991b1b'); // Dried Blood
            grad.addColorStop(0.5, '#450a0a'); // Dark Clot
            grad.addColorStop(1, '#000'); 
            ctx.fillStyle = grad;

            // Jagged Gear Shape (Chaos Star hint)
            ctx.beginPath();
            const sides = 8;
            for(let i=0; i<=sides; i++) {
                const a = (i/sides) * Math.PI*2;
                const r = radius * (i%2===0 ? 1.0 : 0.85); 
                const x = Math.cos(a)*r;
                const y = Math.sin(a)*r;
                if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
            ctx.fill();

            // Brass Trim (Tarnished)
            ctx.strokeStyle = '#78350f'; // Dark Bronze
            ctx.lineWidth = 5;
            ctx.stroke();
            ctx.strokeStyle = '#d97706'; // Highlight Brass
            ctx.lineWidth = 2;
            ctx.stroke();

            // Inner Runes (Burning)
            ctx.beginPath(); ctx.arc(0, 0, radius * 0.6, 0, Math.PI*2);
            ctx.strokeStyle = '#ef4444'; // Glowing Red
            ctx.lineWidth = 2;
            ctx.setLineDash([10, 5]);
            ctx.stroke();

            // Skull/Khorne Mark Hint
            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.4;
            ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    },

    generateRoleIcon(role: Role, team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);
        const cx = ICON_SIZE / 2;
        const cy = ICON_SIZE / 2;

        // Emissive holographic text color
        // Blue: Pale Cyan (Tactical Display)
        // Red: Burning Orange (Warp Energy)
        const color = team === Team.BLUE ? '#cffafe' : '#fdba74';
        const shadowColor = team === Team.BLUE ? '#0ea5e9' : '#ea580c';

        ctx.strokeStyle = color;
        ctx.fillStyle = color;
        ctx.shadowColor = shadowColor;
        ctx.shadowBlur = 8;
        ctx.lineWidth = 2.5;
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';

        ctx.translate(cx, cy);

        // Scale down to fit nicely in 64x64
        const scale = 1.1;
        ctx.scale(scale, scale);

        ctx.beginPath();
        if (role === Role.TANK) {
            // Shield -> Bulwark Icon (Terminator Honors)
            ctx.rect(-10, -12, 20, 24);
            ctx.stroke();
            ctx.beginPath(); ctx.moveTo(-10, 0); ctx.lineTo(10, 0); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(0, -12); ctx.lineTo(0, 12); ctx.stroke();

        } else if (role === Role.WARRIOR) {
            // Sword -> Chainsword/Axe
            ctx.moveTo(-10, -10); ctx.lineTo(10, 10); // Main blade
            ctx.moveTo(-6, -10); ctx.lineTo(-10, -6); // Handle
            ctx.moveTo(6, 10); ctx.lineTo(10, 6); // Tip
            ctx.stroke();
            // Teeth
            ctx.lineWidth = 1;
            ctx.beginPath(); ctx.moveTo(-4, -4); ctx.lineTo(0, -8); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(4, -4); ctx.stroke();

        } else if (role === Role.RANGER) {
            // Bow -> Crosshair / Bolter Round
            ctx.arc(0, 0, 10, 0, Math.PI*2);
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(0, -14); ctx.lineTo(0, -6);
            ctx.moveTo(0, 6); ctx.lineTo(0, 14);
            ctx.moveTo(-14, 0); ctx.lineTo(-6, 0);
            ctx.moveTo(6, 0); ctx.lineTo(14, 0);
            ctx.stroke();
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(0,0,2,0,Math.PI*2); ctx.fill();

        } else if (role === Role.MAGE) {
            // Staff -> Psychic Hood / Warp Bolt
            ctx.beginPath();
            ctx.moveTo(0, 10); ctx.lineTo(0, -6);
            ctx.stroke();
            ctx.beginPath();
            ctx.arc(0, -10, 5, 0, Math.PI*2);
            ctx.stroke();
            // Lightning bolts
            ctx.lineWidth = 1;
            ctx.beginPath(); ctx.moveTo(6, -14); ctx.lineTo(10, -18); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(-6, -14); ctx.lineTo(-10, -18); ctx.stroke();

        } else if (role === Role.SUPPORT) {
            // Cross -> Apothecary Helix / Chaos Icon
            ctx.beginPath();
            ctx.moveTo(0, -12); ctx.lineTo(0, 12);
            ctx.moveTo(-10, 0); ctx.lineTo(10, 0);
            ctx.stroke();
            // Helix bits
            ctx.lineWidth = 1;
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.stroke();
        }

        return canvas;
    },

    generateSheep(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(64, 64);
        const cx = 32, cy = 45;

        // Squig / Nurgling equivalent? Keep it simple white sheep for now but maybe darker
        ctx.fillStyle = '#e2e8f0';
        ctx.shadowColor = '#000';
        ctx.shadowBlur = 5;

        ctx.beginPath();
        ctx.arc(cx, cy, 15, 0, Math.PI*2);
        ctx.arc(cx-10, cy-5, 10, 0, Math.PI*2);
        ctx.arc(cx+10, cy-5, 10, 0, Math.PI*2);
        ctx.fill();

        return canvas;
    }
};

import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { AssetManager } from "../../../assets";
import { ISO_SCALE_Y } from "../../../../constants";

// Helper: Draw Hexagon Path centered at 0,0
function drawHexPath(ctx: CanvasRenderingContext2D, radius: number) {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
        const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
        const x = radius * Math.cos(angle);
        const y = radius * Math.sin(angle) * ISO_SCALE_Y; 
        if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    }
    ctx.closePath();
}

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Context is already translated to Visual Position (Ground Y - Z)
        ctx.translate(p.x, p.y);

        // --- PHYSICAL SHADOW PASS ---
        if (['DEBRIS', 'SHARD', 'SPRITE'].includes(p.type) && p.z > 5) {
            ctx.save();
            ctx.translate(0, p.z); // Move "down" to ground level
            ctx.scale(1, 0.5); // Isometric shadow squash
            const shadowAlpha = Math.max(0, 0.3 - (p.z / 400)); 
            if (shadowAlpha > 0) {
                ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
                const shadowSize = p.size * 0.8;
                ctx.beginPath(); ctx.arc(0, 0, shadowSize, 0, Math.PI * 2); ctx.fill();
            }
            ctx.restore();
        }

        // --- RENDER LOGIC BY TYPE ---

        if (p.type === 'SPARK') {
            // ✨ KINETIC SPARKS (Light Streaks) - 40k Bolter Sparks
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy + p.vz*p.vz);
            const stretch = Math.min(4.0, 1.0 + speed / 150); 
            const angle = Math.atan2(p.vy, p.vx); 

            ctx.rotate(angle);
            ctx.scale(stretch, 0.6); 

            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = Math.pow(1 - progress, 2); 

            const grad = ctx.createLinearGradient(-p.size, 0, p.size, 0);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.2, p.color);
            grad.addColorStop(0.8, '#fff'); 
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.5, 0, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'SMOKE') {
            // ☁️ VOLUMETRIC SMOKE - Darker, Grimdark
            const scale = 0.5 + progress * 2.0; 
            const alpha = (1 - progress) * 0.5; // Reduced alpha to prevent blocking

            ctx.scale(scale, scale);
            ctx.rotate(p.rotation + progress * 0.5); 
            ctx.globalAlpha = alpha;

            // Additive blending for fire, Source-Over for dark smoke
            const isFire = isChaos || p.color.includes('#f'); 
            ctx.globalCompositeOperation = isFire ? 'screen' : 'source-over';

            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, p.size);
            grad.addColorStop(0, p.color);
            grad.addColorStop(1, 'rgba(0,0,0,0)'); 

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.arc(0, 0, p.size, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'RING') {
            // 🌊 SHOCKWAVE RING - Sharp, thin
            ctx.scale(1, 0.55); 
            const r = progress * p.size * 2; 

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 3; // Thinner
            ctx.globalAlpha = 1 - progress;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'BLAST') {
            // 💥 IMPACT
            ctx.scale(1, 0.55); 
            const r = p.size * (progress); 

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 4; 
            ctx.globalAlpha = (1 - progress);

            ctx.beginPath(); 
            const spikes = 8; // Fewer spikes, more jagged
            for(let i=0; i<=spikes; i++) {
                const angle = (i/spikes) * Math.PI*2;
                const rad = r * (1.0 + (i%2===0 ? 0.5 : 0)); 
                const px = Math.cos(angle) * rad;
                const py = Math.sin(angle) * rad;
                if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
            }
            ctx.closePath();
            ctx.stroke();

        } else if (p.type === 'DEBRIS' || p.type === 'SHARD' || p.type === 'CHIP') {
            // 💎 MATERIAL (Metal/Stone chunks)
            ctx.rotate(p.rotation);

            ctx.fillStyle = p.color;
            ctx.strokeStyle = 'rgba(0,0,0,0.5)'; // Dark edges
            ctx.lineWidth = 1;

            ctx.beginPath();
            ctx.rect(-p.size/2, -p.size/2, p.size, p.size);
            ctx.fill();
            ctx.stroke();

        } else if (p.type === 'GLOW') {
            const img = AssetManager.getGlowSprite(p.color);
            const fade = Math.sin(progress * Math.PI); 
            const scale = (p.size / 64) * (0.8 + fade * 0.4); 

            ctx.globalAlpha = fade * 0.7; // Lower opacity
            ctx.globalCompositeOperation = 'screen'; 
            ctx.scale(scale, scale);
            ctx.drawImage(img, -32, -32);

        } else if (p.type === 'SPRITE') {
            if (p.image) {
                const alpha = Math.max(0, 1 - Math.pow(progress, 3)); 
                ctx.globalAlpha = alpha;
                ctx.rotate(p.rotation + progress * 5);
                const perspective = 1.0 + (p.z * 0.002);
                const scale = (p.size / 64) * perspective * (1 - progress * 0.5); 
                ctx.scale(scale, scale);
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);
            }

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                this.drawHelixBeam(ctx, p, progress);
            }
        } else if (p.type === 'DEATH_RAY') {
            this.drawDeathRay(ctx, p, progress);
        } else if (p.type === 'PILLAR') {
            this.drawDivinePillar(ctx, p, progress);
        } else if (p.type === 'SHOCKWAVE') {
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            this.drawDomainArea(ctx, p, progress);
        } else if (p.type === 'GRID_FIELD') {
            this.drawGridField(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    // ⚡ HELIX BEAM - Warped Energy
    drawHelixBeam(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.translate(-p.x, -p.y); 
        ctx.globalCompositeOperation = 'lighter';

        const sx = p.x; const sy = p.y;
        const tx = p.targetX!; const ty = p.targetY!;
        const dx = tx - sx;
        const dy = ty - sy;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const angle = Math.atan2(dy, dx);

        const beamWidth = 4 * (1 - Math.pow(progress, 3)); 
        if (beamWidth < 0.2) return;

        ctx.save();
        ctx.translate(sx, sy);
        ctx.rotate(angle);

        // Core (Thin)
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(dist, 0); ctx.stroke();

        // Glow (Medium)
        ctx.strokeStyle = p.color;
        ctx.lineWidth = beamWidth * 2; 
        ctx.globalAlpha = 0.5 * (1 - progress);
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(dist, 0); ctx.stroke();

        ctx.restore();
    },

    // ☠️ DEATH RAY (Lascannon / Warp Bolt)
    drawDeathRay(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.translate(-p.x, -p.y); 
        const sx = p.x; const sy = p.y;
        const tx = p.targetX!; const ty = p.targetY!;
        const dx = tx - sx;
        const dy = ty - sy;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const angle = Math.atan2(dy, dx);

        ctx.save();
        ctx.translate(sx, sy);
        ctx.rotate(angle);

        const alpha = Math.pow(1 - progress, 2);

        ctx.globalCompositeOperation = 'screen';
        ctx.strokeStyle = p.color; 
        ctx.lineWidth = 6 * alpha;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 10;
        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();
        ctx.shadowBlur = 0;

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2 * alpha;
        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

        ctx.restore();
    },

    // 🌫️ GRID FOG - Strictly Borders, minimal fill
    drawGridField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        const size = 36; 
        const fade = Math.sin(progress * Math.PI); 
        ctx.save();

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over';

            // Chaos: Cracks, no fill
            ctx.strokeStyle = p.color; 
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade * 0.8;

            // Draw a few jagged lines inside the hex
            ctx.beginPath();
            ctx.moveTo(-10, -5); ctx.lineTo(10, 5);
            ctx.moveTo(5, -10); ctx.lineTo(-5, 10);
            ctx.stroke();

            // Subtle rim
            ctx.lineWidth = 1;
            drawHexPath(ctx, size);
            ctx.stroke();

        } else {
            // Order: Tactical Grid, very faint fill
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 1.5;
            ctx.globalAlpha = fade * 0.6;

            drawHexPath(ctx, size);
            ctx.stroke();

            ctx.fillStyle = p.color;
            ctx.globalAlpha = fade * 0.05; // 5% Opacity Fill only
            ctx.fill();
        }
        ctx.restore();
    },

    // 🏛️ DIVINE PILLAR / BEACON - Thinner, Additive Light
    drawDivinePillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const lifeRatio = p.life / p.maxLife;
        let alpha = lifeRatio > 0.8 ? (1-lifeRatio)*5 : (lifeRatio < 0.3 ? lifeRatio*3 : 1.0);

        const height = 1200; 
        const width = p.size; 

        ctx.save();
        ctx.globalCompositeOperation = 'screen'; // Additive blending for light beam

        // Vertical Beacon (Gradient Fade)
        const beamGrad = ctx.createLinearGradient(0, 0, 0, -height);
        beamGrad.addColorStop(0, p.color);
        beamGrad.addColorStop(0.2, 'rgba(255,255,255,0.2)'); 
        beamGrad.addColorStop(1, 'rgba(0,0,0,0)');

        // Horizontal Fade (Soft Edges)
        ctx.fillStyle = beamGrad;
        ctx.globalAlpha = alpha * 0.3; // Very transparent core

        // Draw centered rect
        ctx.fillRect(-width/2, -height, width, height);

        // Narrow Core Beam
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = alpha * 0.2;
        ctx.fillRect(-width/4, -height, width/2, height);

        // Ground Ring
        ctx.scale(1, 0.58); 
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 2;
        ctx.globalAlpha = alpha * 0.8;
        ctx.beginPath(); ctx.arc(0, 0, width, 0, Math.PI*2); ctx.stroke();

        ctx.restore();
    },

    // 🩸 DOMAIN - Ground Decal Only (No Fill)
    drawDomainArea(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
         const lifeRatio = p.life / p.maxLife;
         const alpha = Math.sin(lifeRatio * Math.PI); 
         const r = p.size;
         const isChaos = isChaosStyle(p.color);

         ctx.save();

         if (isChaos) {
             // Chaos: Jagged Runes, Dark Outline
             ctx.globalCompositeOperation = 'source-over'; 

             ctx.strokeStyle = p.color;
             ctx.lineWidth = 3;
             ctx.globalAlpha = alpha * 0.8;
             drawHexPath(ctx, r);
             ctx.stroke();

             // Inner jagged ring
             ctx.setLineDash([20, 10]);
             drawHexPath(ctx, r * 0.7);
             ctx.stroke();

         } else {
             // Order: Clean Holo-Ring
             ctx.globalCompositeOperation = 'screen';

             ctx.strokeStyle = p.color;
             ctx.lineWidth = 2;
             ctx.globalAlpha = alpha * 0.6;
             drawHexPath(ctx, r);
             ctx.stroke();

             // Rotating geometric elements (Clipped to lines only)
             ctx.save();
             ctx.rotate(progress);
             ctx.setLineDash([5, 15]);
             drawHexPath(ctx, r * 0.8);
             ctx.stroke();
             ctx.restore();
         }
         ctx.restore();
    },

    // 🌊 SHOCKWAVE - Thin Ripple
    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        const r = progress * p.size; 

        ctx.globalAlpha = (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 2; // Thin line

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.beginPath();
            for(let i=0; i<=6; i++) {
                const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
                const noise = (Math.random() - 0.5) * 5;
                const rx = (r + noise) * Math.cos(angle);
                const ry = (r + noise) * Math.sin(angle) * ISO_SCALE_Y;
                if(i===0) ctx.moveTo(rx, ry); else ctx.lineTo(rx, ry);
            }
            ctx.closePath();
            ctx.stroke();
        } else {
            ctx.globalCompositeOperation = 'screen';
            drawHexPath(ctx, r);
            ctx.stroke();
        }
    }
};

