import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { AssetManager } from "../../../assets";
import { ISO_SCALE_Y } from "../../../../constants";
import { SurfaceAssets } from "../../../graphics/SurfaceAssets";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // 1. POSITIONING
        const isGridLocked = ['GRID_FIELD', 'DOMAIN', 'SHOCKWAVE', 'PILLAR'].includes(p.type);

        if (isGridLocked) {
            ctx.translate(Math.round(p.x), Math.round(p.y));
        } else {
            ctx.translate(p.x, p.y);
        }

        // --- RENDER LOGIC BY TYPE ---

        if (p.type === 'BEAM' || p.type === 'DEATH_RAY') {
            // ⚡ HIGH ENERGY BEAM (Railgun / Laser)
            if (p.targetX !== undefined) {
                const dx = p.targetX - p.x;
                const dy = p.targetY! - p.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                const angle = Math.atan2(dy, dx);

                ctx.rotate(angle);

                // Dynamic Width: Pulse based on life
                // Expansion -> Hold -> Collapse
                const lifeRatio = p.life / p.maxLife;
                const widthMod = Math.sin(lifeRatio * Math.PI); // 0 -> 1 -> 0
                const baseWidth = p.size * widthMod;

                if (baseWidth > 0.5) {
                    ctx.lineCap = 'round';

                    // 1. The Aura (Wide, Low Opacity)
                    ctx.globalCompositeOperation = isChaos ? 'source-over' : 'lighter';
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = baseWidth * 4;
                    ctx.globalAlpha = 0.2 * widthMod;
                    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

                    // 2. The Core (Intense, White Hot)
                    ctx.globalCompositeOperation = 'lighter';
                    ctx.lineWidth = baseWidth;
                    ctx.strokeStyle = '#fff';
                    ctx.shadowColor = p.color;
                    ctx.shadowBlur = 20; // Intense Bloom
                    ctx.globalAlpha = 0.9;
                    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();
                    ctx.shadowBlur = 0;

                    // 3. Shock Rings (Mach Cones along the beam)
                    // Visualizing the sonic boom of the energy
                    const ringCount = Math.floor(dist / 40);
                    ctx.lineWidth = 2;
                    ctx.strokeStyle = p.color;
                    ctx.globalAlpha = 0.6 * widthMod;

                    for(let i=1; i<ringCount; i++) {
                        const rx = i * 40 + (Date.now() * 0.2) % 40; // Moving rings
                        if (rx > dist) continue;

                        const rw = baseWidth * 2;
                        const rh = baseWidth * 4; // Tall vertical rings perpendicular to beam

                        ctx.beginPath();
                        ctx.ellipse(rx, 0, rw, rh, 0, 0, Math.PI*2);
                        ctx.stroke();
                    }

                    // 4. Lightning Arcs (Chaos/Death Ray only)
                    if (isChaos || p.type === 'DEATH_RAY') {
                        ctx.beginPath();
                        ctx.moveTo(0, 0);
                        const segments = 10;
                        for(let i=1; i<=segments; i++) {
                            const lx = (dist / segments) * i;
                            const ly = (Math.random() - 0.5) * baseWidth * 4;
                            ctx.lineTo(lx, ly);
                        }
                        ctx.strokeStyle = p.color;
                        ctx.lineWidth = 2;
                        ctx.stroke();
                    }
                }
            }

        } else if (p.type === 'PILLAR') {
            // 🏛️ ORBITAL STRIKE (Vertical God Ray)
            const h = 1200; // Massive height
            const w = p.size; // Width defines the power

            // Animation: Crash down (Fast) -> Sustain -> Fade
            let alpha = 1.0;
            let currentH = h;

            // Intro animation (Beam hits ground)
            if (progress < 0.1) {
                currentH = h * (progress / 0.1);
            }
            // Outro animation (Fade)
            if (progress > 0.8) {
                alpha = 1 - (progress - 0.8) / 0.2;
            }

            ctx.globalCompositeOperation = 'screen';

            // 1. Ground Impact Ring
            ctx.save();
            ctx.scale(1, ISO_SCALE_Y);
            ctx.fillStyle = p.color;
            ctx.globalAlpha = alpha * 0.3;
            ctx.beginPath(); ctx.arc(0, 0, w * 1.5, 0, Math.PI*2); ctx.fill();

            // Shockwave expanding from base
            const shockR = w * (1 + (Date.now() * 0.005) % 1);
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = alpha * (1 - ((shockR - w)/w));
            ctx.beginPath(); ctx.arc(0, 0, shockR, 0, Math.PI*2); ctx.stroke();
            ctx.restore();

            // 2. The Main Shaft (Gradient)
            const grad = ctx.createLinearGradient(0, 0, 0, -currentH);
            grad.addColorStop(0, '#fff'); // Ground contact is white hot
            grad.addColorStop(0.1, p.color);
            grad.addColorStop(1, 'transparent'); // Fade into sky

            ctx.fillStyle = grad;
            ctx.globalAlpha = alpha * 0.8;
            ctx.fillRect(-w/2, -currentH, w, currentH);

            // 3. The Core (Thin, intense center)
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = alpha;
            ctx.fillRect(-w/4, -currentH, w/2, currentH);

            // 4. Energy Spirals (Helix up)
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 3;
            ctx.globalAlpha = alpha * 0.5;
            ctx.beginPath();
            const spiralFreq = 0.05;
            const timeOffset = Date.now() * 0.5;
            for(let y = 0; y < currentH; y += 20) {
                const xOffset = Math.sin(y * spiralFreq - timeOffset) * w;
                if (y===0) ctx.moveTo(xOffset, -y);
                else ctx.lineTo(xOffset, -y);
            }
            ctx.stroke();

        } else if (p.type === 'BLAST') {
            // 💥 STARBURST SHOCKWAVE
            const scale = p.size * (Math.pow(progress, 0.5)); // Fast start, slow end

            ctx.scale(scale, scale * ISO_SCALE_Y); 
            ctx.globalCompositeOperation = 'lighter';

            // Spike Burst
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - progress; // Fade out

            ctx.beginPath();
            const spikes = 16; // More spikes
            for(let i=0; i<spikes*2; i++) {
                const angle = (i / (spikes*2)) * Math.PI * 2;
                // Sharp spikes: Outer 1.0, Inner 0.2
                const r = (i % 2 === 0) ? 1.0 : 0.2;
                ctx.lineTo(Math.cos(angle) * r, Math.sin(angle) * r);
            }
            ctx.closePath();
            ctx.fill();

            // Central Ring Flash
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 0.1; // Scaled
            ctx.beginPath(); ctx.arc(0, 0, 0.6, 0, Math.PI*2); ctx.stroke();

        } else if (p.type === 'SMOKE') {
            // ☁️ CLUSTER SMOKE
            // Improved physics feel: Grow and rise
            const growth = 1.0 + progress; 
            const alpha = (1 - progress); 

            ctx.scale(growth, growth);
            ctx.rotate(p.rotation + progress); 

            ctx.globalAlpha = alpha * 0.5;

            if (isChaos) {
                ctx.globalCompositeOperation = 'source-over';
                ctx.fillStyle = p.color; 
            } else {
                ctx.globalCompositeOperation = 'screen';
                // Simple radial for soft smoke
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, p.size);
                grad.addColorStop(0, p.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
            }

            ctx.beginPath();
            ctx.arc(0, 0, p.size, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'SPARK') {
            // ✨ STREAK SPARKS
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy);
            const stretch = Math.min(5.0, 1.0 + speed / 80); 
            const angle = Math.atan2(p.vy, p.vx); 

            ctx.rotate(angle);
            ctx.scale(stretch, 0.4); 

            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = 1.0 - progress; 

            // Hot Core
            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.ellipse(0, 0, p.size, p.size, 0, 0, Math.PI*2); ctx.fill();

            // Trail
            ctx.fillStyle = p.color;
            ctx.globalAlpha = (1.0 - progress) * 0.7;
            ctx.beginPath(); ctx.ellipse(-p.size*2, 0, p.size * 4, p.size*2, 0, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'GRID_FIELD') {
            // 🧱 VOLUMETRIC GRID BLOCK
            const height = 15; 
            const alpha = Math.sin(progress * Math.PI); 
            SurfaceAssets.drawExtrudedHex(ctx, 0, 0, height, p.color, alpha * 0.6, false);

        } else if (p.type === 'DOMAIN') {
            // 🏰 VOLUMETRIC FORTRESS
            const maxH = 120;
            const h = maxH * Math.sin(progress * Math.PI); 
            const alpha = Math.min(1, Math.sin(progress * Math.PI) * 1.5);
            SurfaceAssets.drawExtrudedHex(ctx, 0, 0, h, p.color, alpha * 0.2, true); 
            ctx.globalCompositeOperation = 'screen';
            SurfaceAssets.drawUnitRune(ctx, 0, 0, p.color, Date.now() * 0.001, 1.0);

        } else if (p.type === 'SHOCKWAVE') {
            // 🌊 EXPANDING RING
            const r = progress * p.size; 
            ctx.globalAlpha = 1 - progress; 
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 4;

            if (isChaos) ctx.globalCompositeOperation = 'source-over';
            else ctx.globalCompositeOperation = 'screen';

            SurfaceAssets.pathHex(ctx, 0, 0, r / 32); 
            ctx.stroke();

        } else if (p.type === 'GLOW') {
            const img = AssetManager.getGlowSprite(p.color);
            const scale = (p.size / 64) * (0.8 + Math.sin(progress * Math.PI) * 0.2); 
            ctx.globalAlpha = 1 - progress;
            ctx.globalCompositeOperation = 'screen';
            ctx.scale(scale, scale);
            ctx.drawImage(img, -32, -32);

        } else if (['DEBRIS', 'SHARD', 'CHIP'].includes(p.type)) {
            // 💎 PHYSICAL DEBRIS
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;
            ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
        }

        ctx.restore();
    }
};

