    const slash = system.state.getParticle();
    slash.x = x; slash.y = y; slash.z = 60;
    slash.life = 0.4; slash.maxLife = 0.4;
    slash.color = '#7f1d1d'; 
    slash.size = 200; 
    slash.type = 'BLAST'; 
    system.state.particles.push(slash);

    for(let i=0; i<20; i++) {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = 20;
        p.vx = (Math.random()-0.5)*400; 
        p.vy = (Math.random()-0.5)*400; 
        p.vz = 300 + Math.random()*200;
        p.life = 1.5; p.maxLife = 1.5;
        p.color = '#991b1b';
        p.size = 10;
        p.type = 'DEBRIS'; 
        system.state.particles.push(p);
    }
}

