import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { isChaosStyle } from "../systems/vfx/utils";
import { Skill } from "../../types";

// Precomputed Hex for Geometry
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

const VISIBLE_FACES = [0, 1, 5]; 

export const SurfaceAssets = {

    pathHex(ctx: CanvasRenderingContext2D, x: number, y: number, scale: number = 1.0) {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const c = HEX_CORNERS[i];
            if (i === 0) ctx.moveTo(x + c.x * scale, y + c.y * scale);
            else ctx.lineTo(x + c.x * scale, y + c.y * scale);
        }
        ctx.closePath();
    },

    resolveFieldVisual(skill: Skill, visualType: string): string {
        if (skill.ccType === 'PULL' || skill.name.includes('黑洞')) return 'GRAVITY';
        if (skill.ccType === 'DOT' || skill.name.includes('酸') || skill.name.includes('毒')) return 'POISON_FOG';
        if (skill.name.includes('血') || skill.name.includes('池')) return 'BLOOD_POOL';
        if (skill.name.includes('熔岩') || skill.name.includes('火')) return 'LAVA_POOL';
        if (skill.visual === 'SMASH' || skill.name.includes('震') || skill.name.includes('裂')) return 'CRACK';
        if (skill.name.includes('冰') || skill.name.includes('雪')) return 'ICE_FIELD';
        return visualType; // Fallback
    },

    // 1. LIQUID SURFACE (Blood, Lava, Acid)
    // Concept: Wobbly meniscus inside the hex, specular highlights
    drawLiquidSurface(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); // Flatten to isometric plane

        // Wobbly Circle Base
        ctx.beginPath();
        const r = HEX_SIZE * 0.9;
        const segments = 8;
        for (let i = 0; i <= segments; i++) {
            const angle = (i / segments) * Math.PI * 2;
            // Noise offset based on time and angle
            const noise = Math.sin(angle * 3 + time * 2) * 5 + Math.cos(angle * 5 - time) * 3;
            const px = Math.cos(angle) * (r + noise);
            const py = Math.sin(angle) * (r + noise);
            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();

        // Fluid Body
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.8 * intensity;
        ctx.fill();

        // Inner darker pool (Depth)
        ctx.globalCompositeOperation = 'multiply';
        ctx.beginPath();
        ctx.arc(0, 0, r * 0.6, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.5;
        ctx.fill();

        // Specular Highlights (Surface Tension)
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.6;
        ctx.fillStyle = '#fff';

        // Highlight 1 (Top Edge)
        ctx.beginPath();
        ctx.ellipse(0, -r * 0.6, r * 0.4, 4, 0, 0, Math.PI*2);
        ctx.fill();

        // Highlight 2 (Small bubble)
        const bubbleX = Math.sin(time) * r * 0.3;
        const bubbleY = Math.cos(time) * r * 0.3;
        ctx.beginPath(); ctx.arc(bubbleX, bubbleY, 3, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    // 2. VOLUMETRIC FOG (Poison, Smoke)
    // Concept: Multiple drifting cloud puffs with soft gradients
    drawVolumetricFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        ctx.save();
        ctx.translate(x, y);

        // Create cloud puffs
        const puffs = 5;
        for(let i=0; i<puffs; i++) {
            const tOffset = i * 1.5;
            const cycle = (time + tOffset) % 4; // 4s cycle

            // Orbiting motion
            const angle = time * 0.5 + i * (Math.PI * 2 / puffs);
            const dist = Math.sin(time * 0.2 + i) * 15;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist * ISO_SCALE_Y - 15; // Floating slightly up

            // Breath (Scale)
            const scale = 1.0 + Math.sin(time + i) * 0.2;
            const radius = 25 * scale;

            const grad = ctx.createRadialGradient(px, py, 0, px, py, radius);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.globalAlpha = 0.4;
            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.arc(px, py, radius, 0, Math.PI*2);
            ctx.fill();
        }

        // Ground Haze
        ctx.scale(1, ISO_SCALE_Y);
        ctx.globalAlpha = 0.2;
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    // 3. GROUND CRACKS (Smash, Earthquake)
    // Concept: Jagged lines radiating from center
    drawGroundCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.strokeStyle = color; // Lava color or Energy color
        ctx.lineWidth = 2 * intensity;
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';

        const branches = 4;
        for(let i=0; i<branches; i++) {
            const angle = (i / branches) * Math.PI * 2 + (Math.random()*0.5);
            ctx.beginPath();
            ctx.moveTo(0, 0);

            // Jagged segments
            let cx = 0, cy = 0;
            const len = HEX_SIZE * intensity;
            const steps = 3;
            for(let j=0; j<steps; j++) {
                const stepLen = len / steps;
                cx += Math.cos(angle) * stepLen + (Math.random()-0.5) * 10;
                cy += Math.sin(angle) * stepLen + (Math.random()-0.5) * 10;
                ctx.lineTo(cx, cy);
            }
            ctx.stroke();
        }

        // Glowing Core
        ctx.globalCompositeOperation = 'lighter';
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, 10 * intensity, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    // Original Extruded Hex (Kept for basic fields/walls)
    drawExtrudedHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        height: number,
        color: string,
        opacity: number,
        isHollow: boolean = false
    ) {
        const topY = y - height;
        const bottomY = y;

        ctx.save();
        ctx.globalAlpha = opacity * 0.6;

        for (const i of VISIBLE_FACES) {
            const idx1 = i;
            const idx2 = (i + 1) % 6;

            const c1 = HEX_CORNERS[idx1];
            const c2 = HEX_CORNERS[idx2];

            let shade = 1.0;
            if (i === 5) shade = 0.7; 
            if (i === 0) shade = 0.5; 
            if (i === 1) shade = 0.9; 

            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c2.x, topY + c2.y);
            ctx.lineTo(x + c2.x, bottomY + c2.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.closePath();

            const oldAlpha = ctx.globalAlpha;
            ctx.globalAlpha = oldAlpha * shade;
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.8;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.stroke();

            ctx.globalAlpha = oldAlpha;
        }

        if (!isHollow) {
            ctx.globalAlpha = opacity;
            ctx.fillStyle = color;
            this.pathHex(ctx, x, topY, 1.0);
            ctx.fill();

            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = opacity * 0.5;
            this.pathHex(ctx, x, topY, 0.8);
            ctx.fill();
            ctx.globalCompositeOperation = 'source-over';
        }

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        this.pathHex(ctx, x, topY, 1.0);
        ctx.stroke();

        ctx.restore();
    },

    drawTacticalGrid(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        progress: number, 
        isCenter: boolean
    ) {
        ctx.save();
        const isChaos = isChaosStyle(color);
        const alpha = 0.6 + Math.sin(Date.now() * 0.01) * 0.2;

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over';
            ctx.lineWidth = 2;
            ctx.strokeStyle = color;
            ctx.globalAlpha = alpha;
            this.pathHex(ctx, x, y, 0.9);
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(x - 15, y - 10); ctx.lineTo(x + 15, y + 10);
            ctx.moveTo(x + 15, y - 10); ctx.lineTo(x - 15, y + 10);
            ctx.stroke();
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.2;
            ctx.fill();
        } else {
            const height = 10 * progress;
            this.drawExtrudedHex(ctx, x, y, height, color, 0.4, true); 
            const topY = y - height;
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.8;
            this.pathHex(ctx, x, topY, 1.0);
            ctx.stroke();
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.1;
            this.pathHex(ctx, x, topY, 0.9);
            ctx.fill();
        }
        ctx.restore();
    },

    drawTexture(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        color: string,
        globalTime: number
    ) {
        ctx.save();
        ctx.fillStyle = color;
        ctx.strokeStyle = color;
        const n = Math.sin(q * 12.9898 + r * 78.233) * 43758.5453;
        const seed = n - Math.floor(n);

        if (type === 'MAGMA') {
            if (seed > 0.5) {
                ctx.globalAlpha = 0.6;
                ctx.beginPath();
                ctx.moveTo(cx - 10, cy);
                ctx.lineTo(cx, cy + 5);
                ctx.lineTo(cx + 10, cy - 2);
                ctx.stroke();
            }
        } else if (type === 'VOID') {
            if (seed > 0.7) {
                ctx.fillStyle = '#38bdf8';
                ctx.globalAlpha = 0.4;
                ctx.fillRect(cx - 2, cy - 2, 4, 4);
                ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx+10, cy-5); ctx.stroke();
            }
        }
        ctx.restore();
    },

    drawUnitRune(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        t: number, 
        progress: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 
        const r = HEX_SIZE * 0.8 * progress; 
        ctx.globalAlpha = 0.8;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.stroke();
        ctx.rotate(t * 2);
        ctx.lineWidth = 4;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI/4); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, 0, r, Math.PI, Math.PI + Math.PI/4); ctx.stroke();
        ctx.restore();
    }
};

import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { AssetManager } from "../../../assets";
import { ISO_SCALE_Y } from "../../../../constants";
import { SurfaceAssets } from "../../../graphics/SurfaceAssets";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // 1. POSITIONING
        const isGridLocked = ['GRID_FIELD', 'DOMAIN', 'SHOCKWAVE', 'PILLAR'].includes(p.type);

        if (isGridLocked) {
            ctx.translate(Math.round(p.x), Math.round(p.y));
        } else {
            ctx.translate(p.x, p.y);
        }

        const now = Date.now() / 1000;

        // --- RENDER LOGIC BY TYPE ---

        if (p.type === 'GRID_FIELD') {
            // 🌍 GROUND FIELD REFACTOR
            // Based on Visual Tag, choose specific renderer

            if (p.color === '#be123c' || p.color === '#7f1d1d' || p.color.includes('red')) {
                // 🩸 BLOOD POOL (Liquid)
                SurfaceAssets.drawLiquidSurface(ctx, 0, 0, '#991b1b', now, progress);
            } else if (p.color === '#a3e635' || p.color.includes('green') || p.color.includes('purple')) {
                // ☣️ POISON FOG (Volumetric)
                SurfaceAssets.drawVolumetricFog(ctx, 0, 0, p.color, now);
            } else if (p.color === '#ea580c' || p.color.includes('orange')) {
                // 🌋 LAVA / MAGMA (Liquid + Glow)
                SurfaceAssets.drawLiquidSurface(ctx, 0, 0, '#ea580c', now, progress);
                SurfaceAssets.drawGroundCracks(ctx, 0, 0, '#fdba74', progress);
            } else {
                // 🧱 GENERIC BLOCK (Fallback)
                const height = 15 * progress;
                SurfaceAssets.drawExtrudedHex(ctx, 0, 0, height, p.color, 0.6, false);
            }

        } else if (p.type === 'BEAM' || p.type === 'DEATH_RAY') {
            // ⚡ HIGH ENERGY BEAM (Railgun / Laser)
            if (p.targetX !== undefined) {
                const dx = p.targetX - p.x;
                const dy = p.targetY! - p.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                const angle = Math.atan2(dy, dx);

                ctx.rotate(angle);

                const lifeRatio = p.life / p.maxLife;
                const widthMod = Math.sin(lifeRatio * Math.PI); 
                const baseWidth = p.size * widthMod;

                if (baseWidth > 0.5) {
                    ctx.lineCap = 'round';

                    ctx.globalCompositeOperation = isChaos ? 'source-over' : 'lighter';
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = baseWidth * 4;
                    ctx.globalAlpha = 0.2 * widthMod;
                    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

                    ctx.globalCompositeOperation = 'lighter';
                    ctx.lineWidth = baseWidth;
                    ctx.strokeStyle = '#fff';
                    ctx.shadowColor = p.color;
                    ctx.shadowBlur = 20; 
                    ctx.globalAlpha = 0.9;
                    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();
                    ctx.shadowBlur = 0;

                    const ringCount = Math.floor(dist / 40);
                    ctx.lineWidth = 2;
                    ctx.strokeStyle = p.color;
                    ctx.globalAlpha = 0.6 * widthMod;

                    for(let i=1; i<ringCount; i++) {
                        const rx = i * 40 + (Date.now() * 0.2) % 40; 
                        if (rx > dist) continue;
                        const rw = baseWidth * 2;
                        const rh = baseWidth * 4; 
                        ctx.beginPath(); ctx.ellipse(rx, 0, rw, rh, 0, 0, Math.PI*2); ctx.stroke();
                    }

                    if (isChaos || p.type === 'DEATH_RAY') {
                        ctx.beginPath(); ctx.moveTo(0, 0);
                        const segments = 10;
                        for(let i=1; i<=segments; i++) {
                            const lx = (dist / segments) * i;
                            const ly = (Math.random() - 0.5) * baseWidth * 4;
                            ctx.lineTo(lx, ly);
                        }
                        ctx.strokeStyle = p.color; ctx.lineWidth = 2; ctx.stroke();
                    }
                }
            }

        } else if (p.type === 'PILLAR') {
            const h = 1200; 
            const w = p.size; 

            let alpha = 1.0;
            let currentH = h;

            if (progress < 0.1) currentH = h * (progress / 0.1);
            if (progress > 0.8) alpha = 1 - (progress - 0.8) / 0.2;

            ctx.globalCompositeOperation = 'screen';

            ctx.save();
            ctx.scale(1, ISO_SCALE_Y);
            ctx.fillStyle = p.color;
            ctx.globalAlpha = alpha * 0.3;
            ctx.beginPath(); ctx.arc(0, 0, w * 1.5, 0, Math.PI*2); ctx.fill();

            const shockR = w * (1 + (Date.now() * 0.005) % 1);
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = alpha * (1 - ((shockR - w)/w));
            ctx.beginPath(); ctx.arc(0, 0, shockR, 0, Math.PI*2); ctx.stroke();
            ctx.restore();

            const grad = ctx.createLinearGradient(0, 0, 0, -currentH);
            grad.addColorStop(0, '#fff'); 
            grad.addColorStop(0.1, p.color);
            grad.addColorStop(1, 'transparent'); 

            ctx.fillStyle = grad;
            ctx.globalAlpha = alpha * 0.8;
            ctx.fillRect(-w/2, -currentH, w, currentH);

            ctx.fillStyle = '#fff';
            ctx.globalAlpha = alpha;
            ctx.fillRect(-w/4, -currentH, w/2, currentH);

            ctx.strokeStyle = p.color;
            ctx.lineWidth = 3;
            ctx.globalAlpha = alpha * 0.5;
            ctx.beginPath();
            const spiralFreq = 0.05;
            const timeOffset = Date.now() * 0.5;
            for(let y = 0; y < currentH; y += 20) {
                const xOffset = Math.sin(y * spiralFreq - timeOffset) * w;
                if (y===0) ctx.moveTo(xOffset, -y);
                else ctx.lineTo(xOffset, -y);
            }
            ctx.stroke();

        } else if (p.type === 'BLAST') {
            const scale = p.size * (Math.pow(progress, 0.5)); 

            ctx.scale(scale, scale * ISO_SCALE_Y); 
            ctx.globalCompositeOperation = 'lighter';

            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - progress; 

            ctx.beginPath();
            const spikes = 16; 
            for(let i=0; i<spikes*2; i++) {
                const angle = (i / (spikes*2)) * Math.PI * 2;
                const r = (i % 2 === 0) ? 1.0 : 0.2;
                ctx.lineTo(Math.cos(angle) * r, Math.sin(angle) * r);
            }
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 0.1; 
            ctx.beginPath(); ctx.arc(0, 0, 0.6, 0, Math.PI*2); ctx.stroke();

        } else if (p.type === 'SMOKE') {
            const growth = 1.0 + progress; 
            const alpha = (1 - progress); 

            ctx.scale(growth, growth);
            ctx.rotate(p.rotation + progress); 

            ctx.globalAlpha = alpha * 0.5;

            if (isChaos) {
                ctx.globalCompositeOperation = 'source-over';
                ctx.fillStyle = p.color; 
            } else {
                ctx.globalCompositeOperation = 'screen';
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, p.size);
                grad.addColorStop(0, p.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
            }

            ctx.beginPath();
            ctx.arc(0, 0, p.size, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'SPARK') {
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy);
            const stretch = Math.min(5.0, 1.0 + speed / 80); 
            const angle = Math.atan2(p.vy, p.vx); 

            ctx.rotate(angle);
            ctx.scale(stretch, 0.4); 

            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = 1.0 - progress; 

            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.ellipse(0, 0, p.size, p.size, 0, 0, Math.PI*2); ctx.fill();

            ctx.fillStyle = p.color;
            ctx.globalAlpha = (1.0 - progress) * 0.7;
            ctx.beginPath(); ctx.ellipse(-p.size*2, 0, p.size * 4, p.size*2, 0, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'DOMAIN') {
            const maxH = 120;
            const h = maxH * Math.sin(progress * Math.PI); 
            const alpha = Math.min(1, Math.sin(progress * Math.PI) * 1.5);
            SurfaceAssets.drawExtrudedHex(ctx, 0, 0, h, p.color, alpha * 0.2, true); 
            ctx.globalCompositeOperation = 'screen';
            SurfaceAssets.drawUnitRune(ctx, 0, 0, p.color, Date.now() * 0.001, 1.0);

        } else if (p.type === 'SHOCKWAVE') {
            const r = progress * p.size; 
            ctx.globalAlpha = 1 - progress; 
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 4;

            if (isChaos) ctx.globalCompositeOperation = 'source-over';
            else ctx.globalCompositeOperation = 'screen';

            SurfaceAssets.pathHex(ctx, 0, 0, r / 32); 
            ctx.stroke();

        } else if (p.type === 'GLOW') {
            const img = AssetManager.getGlowSprite(p.color);
            const scale = (p.size / 64) * (0.8 + Math.sin(progress * Math.PI) * 0.2); 
            ctx.globalAlpha = 1 - progress;
            ctx.globalCompositeOperation = 'screen';
            ctx.scale(scale, scale);
            ctx.drawImage(img, -32, -32);

        } else if (['DEBRIS', 'SHARD', 'CHIP'].includes(p.type)) {
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;
            ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
        }

        ctx.restore();
    }
};

import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../../types";
import { SpriteManager } from "../../../sprites";
import { THEME_IMPERIAL, THEME_COVENANT } from "../../../../constants";

// =========================================================================================
// 🛠️ GENERIC / SHARED UTILS (2.5D Volumetric Building Blocks)
// =========================================================================================

// 1. STANDARD EXPLOSION (Physical Debris + Flash)
export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE' | 'SHARD' | 'DEBRIS' | 'GLOW') {
    const safeCount = Math.min((type === 'SPARK' || type === 'GLOW') ? 15 : 8, count);

    for (let i = 0; i < safeCount; i++) {
        const theta = Math.random() * Math.PI * 2;
        const phi = (Math.random() - 0.5) * Math.PI; 
        const spd = Math.random() * 200 * speed;

        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;

        const cosPhi = Math.cos(phi);
        p.vx = Math.cos(theta) * cosPhi * spd;
        p.vy = Math.sin(theta) * cosPhi * spd;
        p.vz = Math.sin(phi) * spd + (100 * speed); 

        p.life = life * (0.6 + Math.random() * 0.4); p.maxLife = life;
        p.color = color;

        if (type === 'SPARK') {
            p.size = Math.random() * 3 + 2;
        } else if (type === 'SHARD') {
            p.size = 6 + Math.random() * 6;
        } else if (type === 'GLOW') {
            p.size = Math.random() * 20 + 10;
        } else {
            p.size = Math.random() * 15 + 10; 
        }

        p.type = type; 
        p.delay = 0;
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random() - 0.5) * 10;

        system.state.particles.push(p);
    }

    if (type === 'SPARK' && count > 5) {
        const flash = system.state.getParticle();
        flash.x = x; flash.y = y; flash.z = z;
        flash.life = 0.2; flash.maxLife = 0.2;
        flash.color = '#fff'; flash.size = 50;
        flash.type = 'BLAST'; 
        system.state.particles.push(flash);

        const smoke = system.state.getParticle();
        smoke.x = x; smoke.y = y; smoke.z = z;
        smoke.vx = 0; smoke.vy = 0; smoke.vz = 50;
        smoke.life = 1.0; smoke.maxLife = 1.0;
        smoke.color = color; smoke.size = 40;
        smoke.type = 'SMOKE';
        system.state.particles.push(smoke);
    }
}

// 2. GROUND IMPACT RINGS
export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 5;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; 
    p.size = 150; 
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

// 3. BEAM
export function spawnBeam(system: VFXSystem, sx: number, sy: number, sz: number, tx: number, ty: number, tz: number, color: string, duration: number = 0.4, size: number = 4) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = sz;
    p.targetX = tx; p.targetY = ty; 
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = duration; p.maxLife = duration; 
    p.color = color; p.size = size; 
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

// 4. SPIKES
export function spawnRisingSpikes(system: VFXSystem, x: number, y: number, count: number, radius: number, color: string, type: 'SHARD' | 'DEBRIS') {
    for(let i=0; i<count; i++) {
        const angle = Math.random() * Math.PI * 2;
        const dist = Math.random() * radius;
        const p = system.state.getParticle();
        p.x = x + Math.cos(angle) * dist;
        p.y = y + Math.sin(angle) * dist;
        p.z = -50; 
        p.vx = 0; p.vy = 0;
        p.vz = 300 + Math.random() * 200; 
        p.life = 2.0; p.maxLife = 2.0;
        p.color = color;
        p.size = 10 + Math.random() * 15;
        p.type = type;
        p.rotation = 0; 
        p.delay = dist * 0.005; 
        system.state.particles.push(p);
    }
}

// 5. PHYSICS DIRECTIONAL IMPACT (Revised)
// Uses impact vector (dirX, dirY) to create cone-based exit/entry debris
export function spawnDirectionalImpact(system: VFXSystem, x: number, y: number, z: number, dirX: number, dirY: number, color: string, type: 'PHYSICAL' | 'MAGICAL') {
    const isPhysical = type === 'PHYSICAL';
    const impactAngle = Math.atan2(dirY, dirX);

    // Cone width (narrow for pierce, wide for blunt)
    const spread = isPhysical ? 0.8 : 1.5; 

    // Number of particles
    const count = isPhysical ? 12 : 8;

    for (let i = 0; i < count; i++) {
        // Random angle within cone directed ALONG the impact (Exit wound)
        // OR slightly back (Ricochet). Let's do 70% forward, 30% back.
        const isRicochet = Math.random() > 0.7;
        const baseAngle = isRicochet ? impactAngle + Math.PI : impactAngle;
        const angle = baseAngle + (Math.random() - 0.5) * spread;

        const speed = 400 + Math.random() * 400; // Fast!
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = isRicochet ? 200 + Math.random() * 200 : 50 + Math.random() * 100; // Ricochets fly higher

        p.life = 0.5; p.maxLife = p.life;

        if (isPhysical) {
            // Blood / Metal chips
            // Use 'DEBRIS' which has gravity logic in VFXSystem
            p.type = Math.random() > 0.5 ? 'DEBRIS' : 'SPARK';
            p.color = (p.type === 'DEBRIS') ? '#7f1d1d' : '#fff'; // Blood or bright metal
            p.size = 3 + Math.random() * 4;
        } else {
            // Magic sparks
            p.type = 'SPARK';
            p.color = color;
            p.size = 2 + Math.random() * 5;
        }

        p.delay = 0;
        system.state.particles.push(p);
    }

    // Impact Flash (Offset slightly towards source to show impact point)
    const p = system.state.getParticle();
    p.x = x - dirX * 10; p.y = y - dirY * 10; p.z = z;
    p.life = 0.2; p.maxLife = 0.2;
    p.color = '#fff'; p.size = 40; p.type = 'BLAST';
    system.state.particles.push(p);
}

// 6. UNIT DEATH
export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role, impulseX: number = 0, impulseY: number = 0) {
    const assets = SpriteManager.getUnitImages(role, team);
    const isBlue = team === Team.BLUE;

    const base = system.state.getParticle();
    base.x = x; base.y = y; base.z = 10;
    base.vx = impulseX * 0.8; base.vy = impulseY * 0.8;
    base.vz = 150 + Math.random() * 100;
    base.life = 2.0; base.maxLife = 2.0;
    base.color = '#fff'; base.size = 50; 
    base.type = 'SPRITE'; base.image = assets.base;
    base.vRotation = (Math.random() - 0.5) * 10;
    system.state.particles.push(base);

    const icon = system.state.getParticle();
    icon.x = x; icon.y = y; icon.z = 40; 
    icon.vx = impulseX * 1.2; icon.vy = impulseY * 1.2;
    icon.vz = 300 + Math.random() * 200;
    icon.life = 2.0; icon.maxLife = 2.0;
    icon.color = '#fff'; icon.size = 64; 
    icon.type = 'SPRITE'; icon.image = assets.icon;
    icon.vRotation = (Math.random() - 0.5) * 20; 
    system.state.particles.push(icon);

    spawnExplosion(system, x, y, 30, 12, isBlue ? '#94a3b8' : '#52525b', 1.5, 2.0, 'DEBRIS');

    const flash = system.state.getParticle();
    flash.x = x; flash.y = y; flash.z = 40;
    flash.life = 0.3; flash.maxLife = 0.3;
    flash.color = '#fff'; flash.size = 80;
    flash.type = 'BLAST';
    system.state.particles.push(flash);
}

// 7. TELEPORT
export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    const beam = system.state.getParticle();
    beam.x = x; beam.y = y; beam.z = 0;
    beam.life = 0.5; beam.maxLife = 0.5;
    beam.color = color; beam.size = 40; beam.type = 'PILLAR';
    system.state.particles.push(beam);

    spawnShockwave(system, x, y, color, 0.5);
}

// 8. LINGERING FOG
export function spawnLingeringField(system: VFXSystem, x: number, y: number, color: string, type: string, duration: number, delay: number) {
    const count = 5;
    for(let i=0; i<count; i++) {
        const p = system.state.getParticle();
        const r = 20;
        p.x = x + (Math.random()-0.5)*r;
        p.y = y + (Math.random()-0.5)*r;
        p.z = 5;
        p.vx = (Math.random()-0.5) * 10;
        p.vy = (Math.random()-0.5) * 10;
        p.vz = 10 + Math.random() * 10; 
        p.life = duration + Math.random(); p.maxLife = p.life;
        p.color = color;
        p.size = 30 + Math.random() * 20; 
        p.type = 'SMOKE';
        p.delay = delay + (i * 0.1); 
        system.state.particles.push(p);
    }
}

// 9. CAST INTERRUPT
