import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";

// Modular Spawners
import * as Generic from "../vfx/spawners/generic";
import * as Imperial from "../vfx/spawners/imperial";
import * as Covenant from "../vfx/spawners/covenant";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                }
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'IMPACT_AOE':
                if (event.skill) {
                    const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                    const radius = event.skill.aoeRadius || 1;
                    const affectedHexes = HexUtils.range(centerHex, radius);

                    const id = event.skill.id;
                    const color = event.color || '#fff';

                    // IMPERIAL (BLUE)
                    if (id === 'tb_u1') { Imperial.spawnImperialSanctuary(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.7); return; }
                    if (id === 'tb_u2') { Imperial.spawnImperialKingsBlessing(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }
                    if (id === 'wb_u1') { Imperial.spawnImperialThunder(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.6); return; }
                    if (id === 'wb_u2') { Imperial.spawnImperialDaybreak(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.8); return; }
                    if (id === 'rb_u1') { Imperial.spawnImperialCrystalArrow(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.6); return; }
                    if (id === 'rb_u2') { Imperial.spawnImperialStarfall(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.4); return; }
                    if (id === 'mb_u1') { Imperial.spawnImperialBlackHole(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.5); return; }
                    if (id === 'mb_u2') { Imperial.spawnImperialFrostfall(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.5); return; }
                    if (id === 'sb_u1') { Imperial.spawnImperialIntervention(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }
                    if (id === 'sb_u2') { Imperial.spawnImperialResurrection(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.4); return; }

                    // COVENANT (RED)
                    if (id === 'tr_u1') { Covenant.spawnCovenantGuillotine(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.8); return; }
                    if (id === 'tr_u2') { Covenant.spawnCovenantUndeadArmy(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.5); return; }
                    if (id === 'wr_u1') { Covenant.spawnCovenantRagnarok(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.9); return; }
                    if (id === 'wr_u2') { Covenant.spawnCovenantBloodStorm(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.6); return; }
                    if (id === 'rr_u1') { Covenant.spawnCovenantRailgun(vfx, event.pos.x - 200, event.pos.y, event.pos.x, event.pos.y, color); camera.addTrauma(0.8); return; }
                    if (id === 'rr_u2') { Covenant.spawnCovenantNuke(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.8); return; }
                    if (id === 'mr_u1') { Covenant.spawnCovenantMeteor(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.7); return; }
                    if (id === 'mr_u2') { Covenant.spawnCovenantDeathFinger(vfx, event.pos.x, event.pos.y - 200, event.pos.x, event.pos.y, color); camera.addTrauma(0.7); return; }
                    if (id === 'sr_u1') { Covenant.spawnCovenantSoulLink(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }
                    if (id === 'sr_u2') { Covenant.spawnCovenantAncestors(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }

                    // Generic Grid Reaction (Ground Cracks/Fields)
                    affectedHexes.forEach(h => {
                        if (engine.map.isValid(h.q, h.r)) {
                            const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                            const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                            const tileVisualY = tilePos.y - hHeight;
                            const dist = HexUtils.dist(centerHex, h);
                            const delay = dist * 0.06;

                            Generic.spawnGridImpact(vfx, tilePos.x, tileVisualY, event.color || '#fff', Team.BLUE, delay);
                        }
                    });
                }

                // Generic Fallback
                Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 0, 20, event.color || '#fff', 2.0, 0.6, 'SPARK');
                Generic.addImpact(vfx, event.pos.x, visualGroundY, 0, event.color || '#fff', 'BLAST', 0.5);
                Generic.spawnShockwave(vfx, event.pos.x, visualGroundY, event.color || '#fff', 0.6);
                camera.addTrauma(0.25); 
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                } else {
                    const hitColor = event.skill?.color || '#fff';
                    Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 20, 8, hitColor, 1.0, 0.3, 'SPARK');
                }
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) {
                    const vx = dAgent.physics.vx || 0;
                    const vy = dAgent.physics.vy || 0;
                    Generic.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role, vx, vy);
                }
                camera.addTrauma(0.15); 
                break;

            case 'SPAWN':
                Generic.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                Generic.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                Generic.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                if (event.skill?.id === 'mr_u2') {
                    Generic.spawnDeathRay(vfx, source.px, source.py - sH - 45, event.pos.x, visualGroundY - 30, event.color || '#be123c');
                    return;
                }

                Generic.spawnBeam(vfx, source.px, source.py - sH - 40, 0, event.pos.x, visualGroundY - 30, 0, event.color || '#fff');
                Generic.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';
                    // Pass normalized direction for "Exit Wound" debris cone
                    Generic.spawnDirectionalImpact(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, event.color || '#fff', type);
                }
            }
        } else {
            // Unknown source (e.g. DoT tick), explode upwards
            Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
        }

        if (dmg > 50) camera.addTrauma(0.05); 
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.15); 

            if (skill && skill.id === 'mr_u2') {
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#000', 3.0, 0.5, 'SPARK');
                Generic.addImpact(vfx, event.pos.x, visualY, 20, '#be123c', 'BLAST', 0.5);
                Generic.spawnShockwave(vfx, event.pos.x, visualY, '#000', 0.5);
                return; 
            }

            if (faction === Team.BLUE) {
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.5, 0.8, 'SPARK');
                Generic.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 0.8);
            } else {
                Generic.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            if (skill && skill.id === 'wr_u1') { // Ragnarok Hit
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#991b1b', 2.0, 1.0, 'DEBRIS');
                Generic.addImpact(vfx, event.pos.x, visualY, 0, '#ef4444', 'BLAST', 0.8);
                camera.addTrauma(0.5);
            } 

        } else {
            // Standard Hit Logic with Direction
            let dx = 0, dy = 0;
            if (source) {
                const len = Math.sqrt((event.pos.x - source.px)**2 + (event.pos.y - source.py)**2) || 1;
                dx = (event.pos.x - source.px) / len;
                dy = (event.pos.y - source.py) / len;
            }

            if (visualType === 'SMASH') {
                Generic.addImpact(vfx, event.pos.x, centerVisualY, 0, color, 'SHOCKWAVE', 0.4);
                // Directional smash debris
                Generic.spawnDirectionalImpact(vfx, event.pos.x, centerVisualY, 10, dx, dy, color, 'PHYSICAL');
            } 
            else if (visualType === 'SLASH') {
                if (source) {
                    Generic.spawnDirectionalImpact(vfx, event.pos.x, visualY, 30, dx, dy, color, 'PHYSICAL');
                } else {
                    Generic.spawnExplosion(vfx, event.pos.x, visualY, 30, 8, color, 1.5, 0.4, 'SPARK');
                }
            }
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                Generic.addImpact(vfx, event.pos.x, visualY, 20, color, 'BLAST', 0.5);
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 20, 5, color, 0.5, 1.0, 'SMOKE');
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 20, 8, '#fff', 1.0, 0.3, 'SPARK');
            }
            else {
                // Magic Bolt / Arrow
                Generic.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.4);
                if (dx !== 0 || dy !== 0) {
                    Generic.spawnDirectionalImpact(vfx, event.pos.x, visualY, 30, dx, dy, color, 'MAGICAL');
                } else {
                    Generic.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 2.0, 0.4, 'SPARK');
                }
            }
        }
    }
}

export interface Particle {
    active: boolean; // Pooling flag
    x: number;
    y: number;
    z: number;
    vx: number;
    vy: number;
    vz: number;
    rotation: number;     // Current rotation
    vRotation: number;    // Rotation speed
    life: number;
    maxLife: number;
    color: string;
    size: number;
    // Consolidated Types for Simplicity
    // Added ROCK for heavy debris
    type: 'SPARK' | 'SMOKE' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'RING' | 'BEAM' | 'SHOCKWAVE' | 'PILLAR' | 'DOMAIN' | 'SPRITE' | 'BLAST' | 'CHIP' | 'GRID_FIELD' | 'DEATH_RAY' | 'ROCK';
    targetX?: number; // For BEAM
    targetY?: number; // For BEAM
    delay?: number;
    image?: HTMLCanvasElement; // For SPRITE type (Unit parts)
}

export interface Decal {
    x: number;
    y: number;
    color: string;
    life: number;
    scale: number;
}

export class VFXStateManager {
    public particles: Particle[] = [];
    public decals: Decal[] = [];

    // Object Pool
    private particlePool: Particle[] = [];

    public getParticle(): Particle {
        if (this.particlePool.length > 0) {
            const p = this.particlePool.pop()!;
            p.active = true;
            p.image = undefined; // Reset image reference
            p.delay = 0; // Reset delay
            return p;
        }
        return { 
            active: true,
            x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, 
            rotation: 0, vRotation: 0,
            life: 0, maxLife: 0, color: '#fff', size: 0, type: 'SPARK',
            delay: 0
        };
    }

    public releaseParticle(p: Particle) {
        p.active = false;
        p.image = undefined;
        this.particlePool.push(p);
    }

    public reset() {
        // Return active particles to pool immediately
        while (this.particles.length > 0) {
            const p = this.particles.pop();
            if (p) this.releaseParticle(p);
        }
        this.decals.length = 0;
    }
}

import { VFXStateManager } from "./vfx/state";

const GRAVITY = 1800; // Gravity for particles

export class VFXSystem {
    // Encapsulated State
    public state: VFXStateManager = new VFXStateManager();

    // Ambient Spawn State
    private ambientTimer: number = 0;

    public reset() {
        this.state.reset();
        this.ambientTimer = 0;
    }

    update(dt: number, globalTime: number, ambientType: string, getTerrainHeight?: (x: number, y: number) => number) {
        // Update Particles
        // PERF: Iterate backwards to allow Swap-Pop removal
        const particles = this.state.particles;
        let count = particles.length;

        for (let i = count - 1; i >= 0; i--) {
            const p = particles[i];

            if (p.delay && p.delay > 0) {
                p.delay -= dt;
                continue;
            }

            p.life -= dt;
            if (p.life <= 0) {
                this.state.releaseParticle(p);
                // PERF: Swap-and-Pop O(1) removal
                particles[i] = particles[count - 1];
                particles.pop();
                count--;
                continue;
            }

            // --- PHYSICS UPDATE ---
            // Types affected by gravity and floor collisions
            // ADDED: ROCK
            const isPhysical = p.type === 'DEBRIS' || p.type === 'SHARD' || p.type === 'SPRITE' || p.type === 'ROCK';

            if (isPhysical) {
                // Get ground height at particle position
                let groundH = 0;
                if (getTerrainHeight) {
                    groundH = getTerrainHeight(p.x, p.y);
                }

                // RESTING CHECK (The Anti-Jitter Fix)
                // If on ground (at terrain height) and barely moving
                const distToGround = p.z - groundH;
                const isResting = distToGround <= 0.5 && Math.abs(p.vz) < 50 && Math.abs(p.vx) < 10 && Math.abs(p.vy) < 10;

                if (isResting) {
                    p.z = groundH; // Snap to terrain top
                    p.vz = 0;
                    p.vx = 0;
                    p.vy = 0;
                    p.vRotation = 0;
                    // Skip integration, just render static
                } else {
                    // Apply Gravity
                    p.vz -= GRAVITY * dt;

                    // Integrate Position
                    p.x += p.vx * dt;
                    p.y += p.vy * dt;
                    p.z += p.vz * dt;
                    p.rotation += p.vRotation * dt;

                    // Ground Collision
                    if (p.z < groundH) {
                        p.z = groundH;
                        // Bounce Logic
                        const bounceFactor = p.type === 'ROCK' ? 0.4 : 0.5; // Rocks bounce less than metal

                        if (Math.abs(p.vz) > 100) {
                            // High Energy: Bounce
                            p.vz = -p.vz * bounceFactor; 
                            p.vx *= 0.6; // Friction on bounce
                            p.vy *= 0.6;
                            p.vRotation *= 0.5;
                        } else {
                            // Low Energy: Slide
                            p.vz = 0;
                            // Heavy Ground Friction
                            p.vx *= 0.1; 
                            p.vy *= 0.1;
                            p.vRotation *= 0.1;
                        }
                    }
                }
            } else {
                // Non-Physical Particles (Smoke, Sparks, etc.)
                p.x += p.vx * dt;
                p.y += p.vy * dt;
                p.z += p.vz * dt;
                p.rotation += p.vRotation * dt;

                if (p.type === 'SPARK' || p.type === 'SMOKE') {
                    p.vx *= 0.90; 
                    p.vy *= 0.90;
                    p.vz *= 0.90; // Drag
                } else if (p.type === 'GLOW') {
                    // Ambient particles float/wobble
                    p.vx += Math.sin(globalTime * 2 + p.x) * 50 * dt;
                    p.vy += Math.cos(globalTime * 2 + p.y) * 50 * dt;
                }
            }
        }

        // Update Decals
        for (let i = this.state.decals.length - 1; i >= 0; i--) {
            this.state.decals[i].life -= dt * 0.5;
            if (this.state.decals[i].life <= 0) {
                // Simple Splice OK here as count is low
                this.state.decals.splice(i, 1);
            }
        }

        // --- AMBIENT SPAWNER ---
        this.updateAmbient(dt, ambientType);
    }

    private updateAmbient(dt: number, type: string) {
        if (type === 'NONE') return;

        this.ambientTimer += dt;
        // Spawn rate based on type
        const rate = type === 'SNOW' || type === 'ASH' ? 0.05 : 0.2; 

        if (this.ambientTimer > rate) {
            this.ambientTimer = 0;
            this.spawnAmbientParticle(type);
        }
    }

    private spawnAmbientParticle(type: string) {
        // Spawn randomly in a large area around center
        const x = Math.random() * 1200 - 100;
        const y = Math.random() * 800 - 100;

        const p = this.state.getParticle();
        p.x = x; p.y = y; p.z = Math.random() * 200 + 50; // Keep off ground
        p.type = 'GLOW';

        if (type === 'SNOW') {
            p.color = '#fff';
            p.size = Math.random() * 3 + 1;
            p.vx = 20 + Math.random() * 20; // Wind
            p.vy = 50 + Math.random() * 30; // Fall
            p.life = 3.0; p.maxLife = 3.0;
        } else if (type === 'ASH') {
            p.color = '#78350f'; // Dark grey/brown
            p.size = Math.random() * 4 + 1;
            p.vx = 30 + Math.random() * 30;
            p.vy = 20 + Math.random() * 20;
            p.life = 4.0; p.maxLife = 4.0;
        } else if (type === 'EMBER') {
            p.color = '#fbbf24';
            p.size = Math.random() * 2 + 1;
            p.vx = (Math.random() - 0.5) * 20;
            p.vy = -30 - Math.random() * 20; // Rise
            p.life = 2.0; p.maxLife = 2.0;
        } else if (type === 'SPORES') {
            p.color = Math.random() > 0.5 ? '#bef264' : '#a855f7';
            p.size = Math.random() * 2 + 1;
            p.vx = (Math.random() - 0.5) * 10;
            p.vy = (Math.random() - 0.5) * 10; // Float
            p.life = 5.0; p.maxLife = 5.0;
        }

        this.state.particles.push(p);
    }
}

import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { AssetManager } from "../../../assets";
import { ISO_SCALE_Y } from "../../../../constants";
import { SurfaceAssets } from "../../../graphics/SurfaceAssets";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // 1. POSITIONING
        // Some effects are grid-locked (Tiles), others are free-floating
        const isGridLocked = ['GRID_FIELD', 'DOMAIN', 'SHOCKWAVE', 'PILLAR'].includes(p.type);

        if (isGridLocked) {
            ctx.translate(Math.round(p.x), Math.round(p.y));
        } else {
            ctx.translate(p.x, p.y);
        }

        const now = Date.now() / 1000;

        // --- RENDER LOGIC BY TYPE ---

        if (p.type === 'GRID_FIELD') {
            // 🌍 GROUND FIELD REFACTOR
            // NOTE: The Z-offset (Terrain Height) is applied in VFXRenderer via translation before calling this.
            // So we draw at local (0,0) which corresponds to the Top Face of the tile.

            if (p.color === '#be123c' || p.color === '#7f1d1d' || p.color.includes('red') || p.color.includes('blood')) {
                // 🩸 BLOOD POOL (Liquid)
                SurfaceAssets.drawLiquidSurface(ctx, 0, 0, '#991b1b', now, progress);
            } else if (p.color === '#a3e635' || p.color.includes('green') || p.color.includes('purple')) {
                // ☣️ POISON FOG (Volumetric)
                SurfaceAssets.drawVolumetricFog(ctx, 0, 0, p.color, now);
            } else if (p.color === '#ea580c' || p.color.includes('orange')) {
                // 🌋 LAVA / MAGMA (Liquid + Glow + Cracks)
                SurfaceAssets.drawLiquidSurface(ctx, 0, 0, '#ea580c', now, progress);
                SurfaceAssets.drawGroundCracks(ctx, 0, 0, '#fdba74', progress);
            } else {
                // 🧱 GENERIC BLOCK (Fallback for unknown types)
                const height = 15 * progress;
                SurfaceAssets.drawExtrudedHex(ctx, 0, 0, height, p.color, 0.6, false);
            }

        } else if (p.type === 'ROCK') {
            // 🪨 STONE DEBRIS
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color; // Usually grey/brown

            // Draw irregular polygon (Rock shape)
            ctx.beginPath();
            const s = p.size;
            ctx.moveTo(-s, -s*0.5);
            ctx.lineTo(-s*0.2, -s);
            ctx.lineTo(s*0.8, -s*0.6);
            ctx.lineTo(s, s*0.5);
            ctx.lineTo(0, s);
            ctx.lineTo(-s*0.8, s*0.5);
            ctx.closePath();
            ctx.fill();

            // Rim Light (Highlight)
            ctx.strokeStyle = 'rgba(255,255,255,0.3)';
            ctx.lineWidth = 1;
            ctx.stroke();

        } else if (p.type === 'BEAM' || p.type === 'DEATH_RAY') {
            // ⚡ HIGH ENERGY BEAM (Railgun / Laser)
            if (p.targetX !== undefined) {
                const dx = p.targetX - p.x;
                const dy = p.targetY! - p.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                const angle = Math.atan2(dy, dx);

                ctx.rotate(angle);

                // Dynamic Width: Pulse based on life (Expansion -> Hold -> Collapse)
                const lifeRatio = p.life / p.maxLife;
                const widthMod = Math.sin(lifeRatio * Math.PI); 
                const baseWidth = p.size * widthMod;

                if (baseWidth > 0.5) {
                    ctx.lineCap = 'round';

                    // 1. Aura (Wide, Transparent)
                    ctx.globalCompositeOperation = isChaos ? 'source-over' : 'lighter';
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = baseWidth * 4;
                    ctx.globalAlpha = 0.2 * widthMod;
                    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

                    // 2. Core (Intense White)
                    ctx.globalCompositeOperation = 'lighter';
                    ctx.lineWidth = baseWidth;
                    ctx.strokeStyle = '#fff';
                    ctx.shadowColor = p.color;
                    ctx.shadowBlur = 20; 
                    ctx.globalAlpha = 0.9;
                    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();
                    ctx.shadowBlur = 0;

                    // 3. Shock Rings (Sonic Boom along beam)
                    const ringCount = Math.floor(dist / 40);
                    ctx.lineWidth = 2;
                    ctx.strokeStyle = p.color;
                    ctx.globalAlpha = 0.6 * widthMod;

                    for(let i=1; i<ringCount; i++) {
                        const rx = i * 40 + (Date.now() * 0.2) % 40; 
                        if (rx > dist) continue;
                        const rw = baseWidth * 2;
                        const rh = baseWidth * 4; 
                        ctx.beginPath(); ctx.ellipse(rx, 0, rw, rh, 0, 0, Math.PI*2); ctx.stroke();
                    }

                    // 4. Lightning Arcs (Chaos/Death Ray only)
                    if (isChaos || p.type === 'DEATH_RAY') {
                        ctx.beginPath(); ctx.moveTo(0, 0);
                        const segments = 10;
                        for(let i=1; i<=segments; i++) {
                            const lx = (dist / segments) * i;
                            const ly = (Math.random() - 0.5) * baseWidth * 4;
                            ctx.lineTo(lx, ly);
                        }
                        ctx.strokeStyle = p.color; ctx.lineWidth = 2; ctx.stroke();
                    }
                }
            }

        } else if (p.type === 'PILLAR') {
            // 🏛️ ORBITAL STRIKE
            const h = 1200; 
            const w = p.size; 

            let alpha = 1.0;
            let currentH = h;

            if (progress < 0.1) currentH = h * (progress / 0.1);
            if (progress > 0.8) alpha = 1 - (progress - 0.8) / 0.2;

            ctx.globalCompositeOperation = 'screen';

            // Ground Impact Ring
            ctx.save();
            ctx.scale(1, ISO_SCALE_Y);
            ctx.fillStyle = p.color;
            ctx.globalAlpha = alpha * 0.3;
            ctx.beginPath(); ctx.arc(0, 0, w * 1.5, 0, Math.PI*2); ctx.fill();

            const shockR = w * (1 + (Date.now() * 0.005) % 1);
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = alpha * (1 - ((shockR - w)/w));
            ctx.beginPath(); ctx.arc(0, 0, shockR, 0, Math.PI*2); ctx.stroke();
            ctx.restore();

            // Shaft
            const grad = ctx.createLinearGradient(0, 0, 0, -currentH);
            grad.addColorStop(0, '#fff'); 
            grad.addColorStop(0.1, p.color);
            grad.addColorStop(1, 'transparent'); 

            ctx.fillStyle = grad;
            ctx.globalAlpha = alpha * 0.8;
            ctx.fillRect(-w/2, -currentH, w, currentH);

            // Core
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = alpha;
            ctx.fillRect(-w/4, -currentH, w/2, currentH);

            // Energy Spirals
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 3;
            ctx.globalAlpha = alpha * 0.5;
            ctx.beginPath();
            const spiralFreq = 0.05;
            const timeOffset = Date.now() * 0.5;
            for(let y = 0; y < currentH; y += 20) {
                const xOffset = Math.sin(y * spiralFreq - timeOffset) * w;
                if (y===0) ctx.moveTo(xOffset, -y);
                else ctx.lineTo(xOffset, -y);
            }
            ctx.stroke();

        } else if (p.type === 'BLAST') {
            // 💥 STARBURST
            const scale = p.size * (Math.pow(progress, 0.5)); 

            ctx.scale(scale, scale * ISO_SCALE_Y); 
            ctx.globalCompositeOperation = 'lighter';

            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - progress; 

            ctx.beginPath();
            const spikes = 16; 
            for(let i=0; i<spikes*2; i++) {
                const angle = (i / (spikes*2)) * Math.PI * 2;
                const r = (i % 2 === 0) ? 1.0 : 0.2;
                ctx.lineTo(Math.cos(angle) * r, Math.sin(angle) * r);
            }
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 0.1; 
            ctx.beginPath(); ctx.arc(0, 0, 0.6, 0, Math.PI*2); ctx.stroke();

        } else if (p.type === 'SMOKE') {
            // ☁️ CLUSTER SMOKE
            const growth = 1.0 + progress; 
            const alpha = (1 - progress); 

            ctx.scale(growth, growth);
            ctx.rotate(p.rotation + progress); 

            ctx.globalAlpha = alpha * 0.5;

            if (isChaos) {
                ctx.globalCompositeOperation = 'source-over';
                ctx.fillStyle = p.color; 
            } else {
                ctx.globalCompositeOperation = 'screen';
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, p.size);
                grad.addColorStop(0, p.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
            }

            ctx.beginPath();
            ctx.arc(0, 0, p.size, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'SPARK') {
            // ✨ STREAK SPARKS
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy);
            const stretch = Math.min(5.0, 1.0 + speed / 80); 
            const angle = Math.atan2(p.vy, p.vx); 

            ctx.rotate(angle);
            ctx.scale(stretch, 0.4); 

            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = 1.0 - progress; 

            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.ellipse(0, 0, p.size, p.size, 0, 0, Math.PI*2); ctx.fill();

            ctx.fillStyle = p.color;
            ctx.globalAlpha = (1.0 - progress) * 0.7;
            ctx.beginPath(); ctx.ellipse(-p.size*2, 0, p.size * 4, p.size*2, 0, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'DOMAIN') {
            const maxH = 120;
            const h = maxH * Math.sin(progress * Math.PI); 
            const alpha = Math.min(1, Math.sin(progress * Math.PI) * 1.5);
            SurfaceAssets.drawExtrudedHex(ctx, 0, 0, h, p.color, alpha * 0.2, true); 
            ctx.globalCompositeOperation = 'screen';
            SurfaceAssets.drawUnitRune(ctx, 0, 0, p.color, Date.now() * 0.001, 1.0);

        } else if (p.type === 'SHOCKWAVE') {
            const r = progress * p.size; 
            ctx.globalAlpha = 1 - progress; 
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 4;

            if (isChaos) ctx.globalCompositeOperation = 'source-over';
            else ctx.globalCompositeOperation = 'screen';

            SurfaceAssets.pathHex(ctx, 0, 0, r / 32); 
            ctx.stroke();

        } else if (p.type === 'GLOW') {
            const img = AssetManager.getGlowSprite(p.color);
            const scale = (p.size / 64) * (0.8 + Math.sin(progress * Math.PI) * 0.2); 
            ctx.globalAlpha = 1 - progress;
            ctx.globalCompositeOperation = 'screen';
            ctx.scale(scale, scale);
            ctx.drawImage(img, -32, -32);

        } else if (['DEBRIS', 'SHARD', 'CHIP'].includes(p.type)) {
            // Physical debris chips
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;
            ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
        }

        ctx.restore();
    }
};

import { GameEngine } from "../../game";
import { AssetManager } from "../../assets";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { SceneTheme } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";
import { ParticleRenderer } from "./renderers/ParticleRenderer";

export class VFXRenderer {

    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        // 1. Decals (Ground Level)
        vfx.state.decals.forEach(d => {
            const offsetY = getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            const drawY = d.y + offsetY;
            if (drawY > d.y + 800) return;

            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            op.y = drawY; op.z = 0;
            op.tx = d.x; op.ty = drawY; // Reuse tx/ty for pos
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });

        // 2. Physical Particles (Sorted with World)
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            // Only Physical types that should be occluded by units
            // Added ROCK to the list
            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'GRID_FIELD', 'ROCK'].includes(p.type)) {

                const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
                if (offset > 800) return;

                const progress = 1 - (p.life / p.maxLife);
                const isChaos = isChaosStyle(p.color);

                const op = renderList.next();
                op.type = RenderOpType.VFX;

                // --- GRID FIELD LAYER FIX ---
                // If it's a persistent field (Fog/Blood), we must query terrain height
                // and lift the particle so it sits ON TOP of the block, not inside it.
                let terrainOffset = 0;
                if (p.type === 'GRID_FIELD') {
                    terrainOffset = getTerrainHeight(p.x, p.y);
                }

                // Sort Key: Keep Y as the sort basis (Row order)
                op.y = p.y + offset; 
                op.z = 5;

                // Draw Position: Apply the terrain lift for fields
                op.particle = p;
                op.vProgress = progress;
                op.vChaos = isChaos;
                op.tx = p.x;
                op.ty = p.y + offset - p.z - terrainOffset; // Drawing Y (visual)
                op.th = p.z; // Height used for shadow calc
            }
        });

        // 3. Projectiles (Delegated)
        ProjectileRenderer.submit(renderList, engine, getTerrainHeight, transitionT, transitionPhase);
    }

    // Items here are drawn ON TOP of everything (Overlay VFX like flashes, text, magic circles)
    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            // Filter out physicals already drawn
            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'GRID_FIELD', 'ROCK'].includes(p.type)) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (offset > 800) return; 

            const progress = 1 - (p.life / p.maxLife);
            const drawY = p.y + offset - p.z;
            const isChaos = isChaosStyle(p.color);

            const originalY = p.y;
            p.y = drawY; 

            ParticleRenderer.drawSingleParticle(ctx, p, progress, isChaos);

            p.y = originalY; 
        });
    }
}

import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../../types";
import { SpriteManager } from "../../../sprites";
import { THEME_IMPERIAL, THEME_COVENANT } from "../../../../constants";

// =========================================================================================
// 🛠️ GENERIC / SHARED UTILS (2.5D Volumetric Building Blocks)
// =========================================================================================

// 1. STANDARD EXPLOSION (Physical Debris + Flash)
export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE' | 'SHARD' | 'DEBRIS' | 'GLOW') {
    const safeCount = Math.min((type === 'SPARK' || type === 'GLOW') ? 15 : 8, count);

    for (let i = 0; i < safeCount; i++) {
        const theta = Math.random() * Math.PI * 2;
        const phi = (Math.random() - 0.5) * Math.PI; 
        const spd = Math.random() * 200 * speed;

        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;

        const cosPhi = Math.cos(phi);
        p.vx = Math.cos(theta) * cosPhi * spd;
        p.vy = Math.sin(theta) * cosPhi * spd;
        p.vz = Math.sin(phi) * spd + (100 * speed); 

        p.life = life * (0.6 + Math.random() * 0.4); p.maxLife = life;
        p.color = color;

        if (type === 'SPARK') {
            p.size = Math.random() * 3 + 2;
        } else if (type === 'SHARD') {
            p.size = 6 + Math.random() * 6;
        } else if (type === 'GLOW') {
            p.size = Math.random() * 20 + 10;
        } else {
            p.size = Math.random() * 15 + 10; 
        }

        p.type = type; 
        p.delay = 0;
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random() - 0.5) * 10;

        system.state.particles.push(p);
    }

    if (type === 'SPARK' && count > 5) {
        const flash = system.state.getParticle();
        flash.x = x; flash.y = y; flash.z = z;
        flash.life = 0.2; flash.maxLife = 0.2;
        flash.color = '#fff'; flash.size = 50;
        flash.type = 'BLAST'; 
        system.state.particles.push(flash);

        const smoke = system.state.getParticle();
        smoke.x = x; smoke.y = y; smoke.z = z;
        smoke.vx = 0; smoke.vy = 0; smoke.vz = 50;
        smoke.life = 1.0; smoke.maxLife = 1.0;
        smoke.color = color; smoke.size = 40;
        smoke.type = 'SMOKE';
        system.state.particles.push(smoke);
    }
}

// 2. GROUND IMPACT RINGS
export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 5;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; 
    p.size = 150; 
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

// 3. BEAM
export function spawnBeam(system: VFXSystem, sx: number, sy: number, sz: number, tx: number, ty: number, tz: number, color: string, duration: number = 0.4, size: number = 4) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = sz;
    p.targetX = tx; p.targetY = ty; 
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = duration; p.maxLife = duration; 
    p.color = color; p.size = size; 
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

// 4. SPIKES
export function spawnRisingSpikes(system: VFXSystem, x: number, y: number, count: number, radius: number, color: string, type: 'SHARD' | 'DEBRIS') {
    for(let i=0; i<count; i++) {
        const angle = Math.random() * Math.PI * 2;
        const dist = Math.random() * radius;
        const p = system.state.getParticle();
        p.x = x + Math.cos(angle) * dist;
        p.y = y + Math.sin(angle) * dist;
        p.z = -50; 
        p.vx = 0; p.vy = 0;
        p.vz = 300 + Math.random() * 200; 
        p.life = 2.0; p.maxLife = 2.0;
        p.color = color;
        p.size = 10 + Math.random() * 15;
        p.type = type;
        p.rotation = 0; 
        p.delay = dist * 0.005; 
        system.state.particles.push(p);
    }
}

// 5. STONE SPLATTER (Replaces Spark "Hedgehog" effect)
export function spawnStoneSplatter(system: VFXSystem, x: number, y: number, z: number, dirX: number, dirY: number, color: string) {
    const impactAngle = Math.atan2(dirY, dirX);

    // Cone width: Moderate spread for impact
    const spread = 1.0; 

    // Fewer particles, chunkier look
    const count = 5;

    for (let i = 0; i < count; i++) {
        // Direction: Mostly along impact vector (Exit wound style) or bounce back
        const isRicochet = Math.random() > 0.6;
        const baseAngle = isRicochet ? impactAngle + Math.PI : impactAngle;
        const angle = baseAngle + (Math.random() - 0.5) * spread;

        const speed = 250 + Math.random() * 300; 
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 200 + Math.random() * 300; // High arc

        p.life = 0.8 + Math.random() * 0.4; p.maxLife = p.life;
        p.type = 'ROCK';
        p.color = '#94a3b8'; // Default stone grey, ignores input color to look like physical debris
        p.size = 6 + Math.random() * 8; // Chunky sizes

        p.vRotation = (Math.random() - 0.5) * 15; // Heavy spin
        p.delay = 0;

        system.state.particles.push(p);
    }

    // Small dust puff at impact point
    const smoke = system.state.getParticle();
    smoke.x = x; smoke.y = y; smoke.z = z;
    smoke.life = 0.4; smoke.maxLife = 0.4;
    smoke.color = '#cbd5e1'; 
    smoke.size = 20;
    smoke.type = 'SMOKE';
    system.state.particles.push(smoke);
}

// 6. UNIT DEATH
export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role, impulseX: number = 0, impulseY: number = 0) {
    const assets = SpriteManager.getUnitImages(role, team);
    const isBlue = team === Team.BLUE;

    const base = system.state.getParticle();
    base.x = x; base.y = y; base.z = 10;
    base.vx = impulseX * 0.8; base.vy = impulseY * 0.8;
    base.vz = 150 + Math.random() * 100;
    base.life = 2.0; base.maxLife = 2.0;
    base.color = '#fff'; base.size = 50; 
    base.type = 'SPRITE'; base.image = assets.base;
    base.vRotation = (Math.random() - 0.5) * 10;
    system.state.particles.push(base);

    const icon = system.state.getParticle();
    icon.x = x; icon.y = y; icon.z = 40; 
    icon.vx = impulseX * 1.2; icon.vy = impulseY * 1.2;
    icon.vz = 300 + Math.random() * 200;
    icon.life = 2.0; icon.maxLife = 2.0;
    icon.color = '#fff'; icon.size = 64; 
    icon.type = 'SPRITE'; icon.image = assets.icon;
    icon.vRotation = (Math.random() - 0.5) * 20; 
    system.state.particles.push(icon);

    spawnExplosion(system, x, y, 30, 12, isBlue ? '#94a3b8' : '#52525b', 1.5, 2.0, 'DEBRIS');

    const flash = system.state.getParticle();
    flash.x = x; flash.y = y; flash.z = 40;
    flash.life = 0.3; flash.maxLife = 0.3;
    flash.color = '#fff'; flash.size = 80;
    flash.type = 'BLAST';
    system.state.particles.push(flash);
}

// 7. TELEPORT
export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    const beam = system.state.getParticle();
    beam.x = x; beam.y = y; beam.z = 0;
    beam.life = 0.5; beam.maxLife = 0.5;
    beam.color = color; beam.size = 40; beam.type = 'PILLAR';
    system.state.particles.push(beam);

    spawnShockwave(system, x, y, color, 0.5);
}

// 8. LINGERING FOG
export function spawnLingeringField(system: VFXSystem, x: number, y: number, color: string, type: string, duration: number, delay: number) {
    const count = 5;
    for(let i=0; i<count; i++) {
        const p = system.state.getParticle();
        const r = 20;
        p.x = x + (Math.random()-0.5)*r;
        p.y = y + (Math.random()-0.5)*r;
        p.z = 5;
        p.vx = (Math.random()-0.5) * 10;
        p.vy = (Math.random()-0.5) * 10;
        p.vz = 10 + Math.random() * 10; 
        p.life = duration + Math.random(); p.maxLife = p.life;
        p.color = color;
        p.size = 30 + Math.random() * 20; 
        p.type = 'SMOKE';
        p.delay = delay + (i * 0.1); 
        system.state.particles.push(p);
    }
}

// 9. CAST INTERRUPT
export function spawnCastBreak(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    const blast = system.state.getParticle();
    blast.x = x; blast.y = y; blast.z = 40;
    blast.life = 0.25; blast.maxLife = 0.25;
    blast.color = '#00ffff'; blast.size = 80;
    blast.type = 'BLAST';
    system.state.particles.push(blast);

    for(let i=0; i<6; i++) {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = 40;
        p.vx = (Math.random()-0.5) * 150; p.vy = (Math.random()-0.5) * 150;
        p.life = 0.4; p.maxLife = 0.4;
        p.color = '#ff00ff'; p.size = 5; p.type = 'CHIP'; 
        system.state.particles.push(p);
    }
}

// 10. GRID IMPACT
export function spawnGridImpact(system: VFXSystem, x: number, y: number, color: string, team: Team, delay: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.life = 1.0; p.maxLife = 1.0;
    p.color = color;
    p.size = 36; 
    p.type = 'GRID_FIELD'; 
    p.delay = delay;
    system.state.particles.push(p);
}

// 11. CONNECTOR SLASH
export function spawnConnectorSlash(system: VFXSystem, x1: number, y1: number, x2: number, y2: number, color: string, visual: string) {
    const p = system.state.getParticle();
