        p.vz = 50 + Math.random() * 100;
        p.life = 1.5; p.maxLife = 1.5;
        p.color = color;
        p.size = 20 + Math.random() * 10;
        p.type = 'SMOKE';
        system.state.particles.push(p);
    }
}

import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";

// Modular Spawners
import * as Generic from "../vfx/spawners/generic";
import * as Imperial from "../vfx/spawners/imperial";
import * as Covenant from "../vfx/spawners/covenant";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                }
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'IMPACT_AOE':
                if (event.skill) {
                    const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                    const radius = event.skill.aoeRadius || 1;
                    const affectedHexes = HexUtils.range(centerHex, radius);

                    const id = event.skill.id;
                    const color = event.color || '#fff';

                    // IMPERIAL (BLUE)
                    if (id === 'tb_u1') { Imperial.spawnImperialSanctuary(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.7); return; }
                    if (id === 'tb_u2') { Imperial.spawnImperialKingsBlessing(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }
                    if (id === 'wb_u1') { Imperial.spawnImperialThunder(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.6); return; }
                    if (id === 'wb_u2') { Imperial.spawnImperialDaybreak(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.8); return; }
                    if (id === 'rb_u1') { Imperial.spawnImperialCrystalArrow(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.6); return; }
                    if (id === 'rb_u2') { Imperial.spawnImperialStarfall(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.4); return; }
                    if (id === 'mb_u1') { Imperial.spawnImperialBlackHole(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.5); return; }
                    if (id === 'mb_u2') { Imperial.spawnImperialFrostfall(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.5); return; }
                    if (id === 'sb_u1') { Imperial.spawnImperialIntervention(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }
                    if (id === 'sb_u2') { Imperial.spawnImperialResurrection(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.4); return; }

                    // COVENANT (RED)
                    if (id === 'tr_u1') { Covenant.spawnCovenantGuillotine(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.8); return; }
                    if (id === 'tr_u2') { Covenant.spawnCovenantUndeadArmy(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.5); return; }
                    if (id === 'wr_u1') { Covenant.spawnCovenantRagnarok(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.9); return; }
                    if (id === 'wr_u2') { Covenant.spawnCovenantBloodStorm(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.6); return; }
                    if (id === 'rr_u1') { Covenant.spawnCovenantRailgun(vfx, event.pos.x - 200, event.pos.y, event.pos.x, event.pos.y, color); camera.addTrauma(0.8); return; }
                    if (id === 'rr_u2') { Covenant.spawnCovenantNuke(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.8); return; }
                    if (id === 'mr_u1') { Covenant.spawnCovenantMeteor(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.7); return; }
                    if (id === 'mr_u2') { Covenant.spawnCovenantDeathFinger(vfx, event.pos.x, event.pos.y - 200, event.pos.x, event.pos.y, color); camera.addTrauma(0.7); return; }
                    if (id === 'sr_u1') { Covenant.spawnCovenantSoulLink(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }
                    if (id === 'sr_u2') { Covenant.spawnCovenantAncestors(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }

                    // Generic Grid Reaction (Ground Cracks/Fields)
                    affectedHexes.forEach(h => {
                        if (engine.map.isValid(h.q, h.r)) {
                            const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                            const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                            const tileVisualY = tilePos.y - hHeight;
                            const dist = HexUtils.dist(centerHex, h);
                            const delay = dist * 0.06;

                            Generic.spawnGridImpact(vfx, tilePos.x, tileVisualY, event.color || '#fff', Team.BLUE, delay);
                        }
                    });
                }

                // Generic Fallback
                Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 0, 20, event.color || '#fff', 2.0, 0.6, 'SPARK');
                Generic.addImpact(vfx, event.pos.x, visualGroundY, 0, event.color || '#fff', 'BLAST', 0.5);
                Generic.spawnShockwave(vfx, event.pos.x, visualGroundY, event.color || '#fff', 0.6);
                camera.addTrauma(0.25); 
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                } else {
                    const hitColor = event.skill?.color || '#fff';
                    Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 20, 8, hitColor, 1.0, 0.3, 'SPARK');
                }
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) {
                    const vx = dAgent.physics.vx || 0;
                    const vy = dAgent.physics.vy || 0;
                    Generic.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role, vx, vy);
                }
                camera.addTrauma(0.15); 
                break;

            case 'SPAWN':
                Generic.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                Generic.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                Generic.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                if (event.skill?.id === 'mr_u2') {
                    Generic.spawnDeathRay(vfx, source.px, source.py - sH - 45, event.pos.x, visualGroundY - 30, event.color || '#be123c');
                    return;
                }

                Generic.spawnBeam(vfx, source.px, source.py - sH - 40, 0, event.pos.x, visualGroundY - 30, 0, event.color || '#fff');
                Generic.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    // NEW: Replace Directional Impact with Stone Splatter
                    // This creates rocky debris instead of sparks
                    Generic.spawnStoneSplatter(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, '#94a3b8');
                }
            }
        } else {
            // Unknown source (e.g. DoT tick), explode upwards
            Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
        }

        if (dmg > 50) camera.addTrauma(0.05); 
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.15); 

            if (skill && skill.id === 'mr_u2') {
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#000', 3.0, 0.5, 'SPARK');
                Generic.addImpact(vfx, event.pos.x, visualY, 20, '#be123c', 'BLAST', 0.5);
                Generic.spawnShockwave(vfx, event.pos.x, visualY, '#000', 0.5);
                return; 
            }

            if (faction === Team.BLUE) {
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.5, 0.8, 'SPARK');
                Generic.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 0.8);
            } else {
                Generic.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            if (skill && skill.id === 'wr_u1') { // Ragnarok Hit
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#991b1b', 2.0, 1.0, 'DEBRIS');
                Generic.addImpact(vfx, event.pos.x, visualY, 0, '#ef4444', 'BLAST', 0.8);
                camera.addTrauma(0.5);
            } 

        } else {
            // Standard Hit Logic with Direction
            let dx = 0, dy = 0;
            if (source) {
                const len = Math.sqrt((event.pos.x - source.px)**2 + (event.pos.y - source.py)**2) || 1;
                dx = (event.pos.x - source.px) / len;
                dy = (event.pos.y - source.py) / len;
            }

            if (visualType === 'SMASH') {
                Generic.addImpact(vfx, event.pos.x, centerVisualY, 0, color, 'SHOCKWAVE', 0.4);
                // Directional debris (Changed to Stone)
                Generic.spawnStoneSplatter(vfx, event.pos.x, centerVisualY, 10, dx, dy, color);
            } 
            else if (visualType === 'SLASH') {
                if (source) {
                    // Directional debris (Changed to Stone)
                    Generic.spawnStoneSplatter(vfx, event.pos.x, visualY, 30, dx, dy, color);
                } else {
                    Generic.spawnExplosion(vfx, event.pos.x, visualY, 30, 8, color, 1.5, 0.4, 'SPARK');
                }
            }
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                Generic.addImpact(vfx, event.pos.x, visualY, 20, color, 'BLAST', 0.5);
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 20, 5, color, 0.5, 1.0, 'SMOKE');
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 20, 8, '#fff', 1.0, 0.3, 'SPARK');
            }
            else {
                // Magic Bolt / Arrow
                Generic.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.4);
                if (dx !== 0 || dy !== 0) {
                    // Magic hits still create stone debris for impact feel
                    Generic.spawnStoneSplatter(vfx, event.pos.x, visualY, 30, dx, dy, color);
                } else {
                    Generic.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 2.0, 0.4, 'SPARK');
                }
            }
        }
    }
}

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { SpriteManager } from "../../sprites";
import { Team } from "../../../types";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";

// =================================================================================
// 🧚 UNIT VISUAL EFFECTS (Flight, Casting, Status)
// =================================================================================

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171';

    const feetX = physX;
    const feetY = physY - physZ; 

    ctx.save();

    // 1. Ground Anchor (The Base)
    ctx.save();
    ctx.scale(1, 0.58); 
    ctx.lineDashOffset = -t * 20;

    // Outer dashed ring (Tech style)
    ctx.globalAlpha = 0.6;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.setLineDash([8, 4]);
    ctx.beginPath();
    ctx.arc(0, 0, 18, 0, Math.PI * 2);
    ctx.stroke();

    // Inner solid ring/plate
    ctx.setLineDash([]);
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.3;
    ctx.beginPath();
    ctx.arc(0, 0, 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // 2. Holographic Tether (The Lift)
    if (physZ > 5) {
        const grad = ctx.createLinearGradient(0, 0, feetX, feetY);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent'); 

        ctx.strokeStyle = grad;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.5;

        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(feetX, feetY);
        ctx.stroke();

        const pulseCount = 3;
        ctx.fillStyle = isBlue ? '#e0f2fe' : '#fecaca';
        ctx.globalAlpha = 0.8;

        for(let i=0; i<pulseCount; i++) {
            const p = (t * 0.8 + i / pulseCount) % 1.0; 
            const px = feetX * p;
            const py = feetY * p;
            const scale = 1 - p * 0.5;
            ctx.beginPath();
            ctx.ellipse(px, py, 4 * scale, 2 * scale, 0, 0, Math.PI*2);
            ctx.fill();
        }
    }

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 

    ctx.save();
    ctx.translate(0, 5); 
    ctx.scale(1, 0.5); 

    // Rotating Wind/Energy Swirl at Feet
    ctx.rotate(t * 8); 

    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.6;
    ctx.stroke();

    ctx.beginPath();
    for(let i=0; i<3; i++) {
        const offset = i * (Math.PI * 2 / 3);
        const arcLen = Math.PI / 2;
        ctx.moveTo(Math.cos(offset) * 18, Math.sin(offset) * 18);
        ctx.arc(0, 0, 18, offset, offset + arcLen);
    }

    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.5 + Math.sin(t * 20) * 0.2; 
    ctx.stroke();

    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    if (skill.tag === 'ULT') {
        drawUltimateChantVFX(ctx, agent, t);
        return;
    }

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    // 1. Rising Energy Lines (Smooth curves, not spikes)
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';

    const lineCount = 4; 
    for(let i=0; i<lineCount; i++) {
        const pOffset = (t * 2 + i * 0.5) % 1;
        const y = -pOffset * 60;
        const x = Math.sin(y * 0.1 + t * 5) * 10;
        const alpha = Math.sin(pOffset * Math.PI);

        ctx.globalAlpha = alpha * progress;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x, y - 10);
        ctx.stroke();
    }

    // 2. Hand Glow
    ctx.globalAlpha = 0.6 + (Math.sin(t * 15) * 0.2);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(0, -35, 5 + progress * 10, 0, Math.PI*2); ctx.fill();

    ctx.restore();
}

export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    ctx.translate(0, -40); // Chest height

    // 1. Sphere of Power
    ctx.globalCompositeOperation = 'screen';
    const size = 50 * (0.2 + progress * 0.8);

    const grad = ctx.createRadialGradient(0, 0, size * 0.5, 0, 0, size);
    grad.addColorStop(0, 'rgba(255,255,255,0.8)');
    grad.addColorStop(0.5, color);
    grad.addColorStop(1, 'transparent');

    ctx.fillStyle = grad;
    ctx.globalAlpha = 0.6;
    ctx.beginPath(); ctx.arc(0, 0, size, 0, Math.PI*2); ctx.fill();

    // 2. Orbiting Electrons
    const orbits = 3;
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    for(let i=0; i<orbits; i++) {
        ctx.save();
        ctx.rotate(t * 2 + i * (Math.PI/orbits));
        ctx.scale(1, 0.3);
        ctx.beginPath(); ctx.arc(0, 0, size, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    ctx.restore();
}

export function drawSkillGroundIndicator(ctx: CanvasRenderingContext2D, x: number, y: number, color: string, t: number, progress: number, skillRadius: number, type: 'BASIC' | 'ACTIVE' | 'ULT', isAOE: boolean) {
    SurfaceAssets.drawUnitRune(ctx, x, y, color, t, progress);
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, -110);

            const glow = AssetManager.getGlowSprite(skill.color);
            ctx.globalCompositeOperation = 'lighter';
            const pulse = 0.5 + Math.sin(t * 10) * 0.1;
            ctx.globalAlpha = 0.3 * pulse;
            ctx.drawImage(glow, -40, -40, 80, 80);

            ctx.restore();
        }
    }
}

// ♻️ REWRITTEN STATUS EFFECTS
// Removed all jagged lines and "hedgehog" geometry.
export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    const HEAD_Y = -65; 

    // 1. FROZEN - Ice Block (Clean Geometry)
    if (agent.visualStatus === 'FROZEN') {
        ctx.save();
        ctx.translate(0, -40); 
        const w = 25; const h = 45;

        ctx.globalCompositeOperation = 'hard-light';
        const grad = ctx.createLinearGradient(-w, -h, w, h);
        grad.addColorStop(0, 'rgba(255,255,255,0.7)');
        grad.addColorStop(0.5, 'rgba(186, 230, 253, 0.4)');
        grad.addColorStop(1, 'rgba(56, 189, 248, 0.6)');

        ctx.fillStyle = grad;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;

        // Hexagonal prism shape
        ctx.beginPath();
        ctx.moveTo(0, -h-5); 
        ctx.lineTo(w, -h+10); ctx.lineTo(w, h-10); 
        ctx.lineTo(0, h+5); 
        ctx.lineTo(-w, h-10); ctx.lineTo(-w, -h+10);
        ctx.closePath();
        ctx.fill(); 
        ctx.stroke();

        // Glint
        ctx.globalCompositeOperation = 'overlay';
        ctx.beginPath(); ctx.moveTo(0, -h-5); ctx.lineTo(0, h+5); ctx.stroke();

        ctx.restore();
    }

    // 2. BANISH / GHOST (Smooth Fade + Outline)
    if (agent.banished && agent.visualStatus !== 'POLYMORPH' && agent.visualStatus !== 'STASIS') {
        // No extra geometry needed, the unit itself is transparent/ghostly in UnitRenderSystem
        // Just add a subtle ring
        ctx.translate(0, -30);
        ctx.strokeStyle = '#c084fc';
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.5 + Math.sin(t * 5) * 0.2;
        ctx.beginPath();
        ctx.ellipse(0, 0, 20, 40, 0, 0, Math.PI*2);
        ctx.stroke();
    }

    // 3. STUN - Golden Halo (Replaces Stars)
    if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
        ctx.translate(0, HEAD_Y);

        // Rotating Halo Ring
        ctx.save();
        ctx.scale(1, 0.3); // Flatten to look like a halo
        ctx.beginPath();
        ctx.arc(0, 0, 20, 0, Math.PI*2);
        ctx.lineWidth = 3;
        ctx.strokeStyle = '#facc15'; // Gold
        ctx.shadowColor = '#fde047';
        ctx.shadowBlur = 10;
        ctx.stroke();
        ctx.restore();

        // Spinning Orbiters (Small dots)
        const count = 3;
        for(let i=0; i<count; i++) {
            const angle = t * 5 + (i * (Math.PI*2/count));
            const x = Math.cos(angle) * 20;
            const y = Math.sin(angle) * 6; // Flattened Y

            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
        }
    }

    // 4. SILENCE - Speech Bubble
    if (agent.silenceTimer > 0) {
        ctx.translate(0, HEAD_Y - 20);
        const float = Math.sin(t * 3) * 3;
        ctx.translate(0, float);

        ctx.fillStyle = '#1e1b4b'; 
        ctx.strokeStyle = '#a855f7';
        ctx.lineWidth = 2;

        // Bubble shape
        ctx.beginPath();
        ctx.roundRect(-15, -10, 30, 20, 6);
        ctx.fill(); ctx.stroke();

        // "..." text
        ctx.fillStyle = '#a855f7';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.font = 'bold 16px sans-serif';
        ctx.fillText('...', 0, 2);
    }

    // 5. DoT - Rising Bubbles (No geometry on body)
    if (agent.dotTimer > 0) {
        // Draw rising bubbles in world space logic usually, but here relative to unit is fine
        ctx.translate(0, -20); // Start at feet/waist
        const count = 3;
        for(let i=0; i<count; i++) {
            const phase = (t + i * 0.33) % 1; // 0 to 1
            const y = -phase * 50; // Move up
            const x = Math.sin(phase * 10 + i) * 10; // Wiggle
            const alpha = 1 - phase;

            ctx.fillStyle = i%2===0 ? '#10b981' : '#ef4444'; // Green or Red
            ctx.globalAlpha = alpha * 0.6;
            ctx.beginPath(); ctx.arc(x, y, 3 + phase * 2, 0, Math.PI*2); ctx.fill();
        }
    }

    // 6. HoT - Rising Crosses
    if (agent.hotTimer > 0) {
        ctx.translate(0, -30);
        const phase = (t * 0.8) % 1;
        const y = -phase * 40;

        ctx.fillStyle = '#4ade80';
        ctx.globalAlpha = 1 - phase;
        ctx.font = 'bold 14px sans-serif';
        ctx.fillText('+', 10, y);
    }

    ctx.restore();
}

