import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET, THEME_IMPERIAL, THEME_COVENANT } from "../../../constants";

// Modular Spawners
import * as Generic from "../vfx/spawners/generic";
import * as Imperial from "../vfx/spawners/imperial";
import * as Covenant from "../vfx/spawners/covenant";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                }
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'IMPACT_AOE':
                if (event.skill) {
                    const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                    const radius = event.skill.aoeRadius || 1;
                    const affectedHexes = HexUtils.range(centerHex, radius);

                    const id = event.skill.id;
                    const color = event.color || '#fff';

                    // IMPERIAL (BLUE)
                    if (id === 'tb_u1') { Imperial.spawnImperialSanctuary(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.7); return; }
                    if (id === 'tb_u2') { Imperial.spawnImperialKingsBlessing(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }
                    if (id === 'wb_u1') { Imperial.spawnImperialThunder(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.6); return; }
                    if (id === 'wb_u2') { Imperial.spawnImperialDaybreak(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.8); return; }
                    if (id === 'rb_u1') { Imperial.spawnImperialCrystalArrow(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.6); return; }
                    if (id === 'rb_u2') { Imperial.spawnImperialStarfall(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.4); return; }
                    if (id === 'mb_u1') { Imperial.spawnImperialBlackHole(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.5); return; }
                    if (id === 'mb_u2') { Imperial.spawnImperialFrostfall(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.5); return; }
                    if (id === 'sb_u1') { Imperial.spawnImperialIntervention(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }
                    if (id === 'sb_u2') { Imperial.spawnImperialResurrection(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.4); return; }

                    // COVENANT (RED)
                    if (id === 'tr_u1') { Covenant.spawnCovenantGuillotine(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.8); return; }
                    if (id === 'tr_u2') { Covenant.spawnCovenantUndeadArmy(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.5); return; }
                    if (id === 'wr_u1') { Covenant.spawnCovenantRagnarok(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.9); return; }
                    if (id === 'wr_u2') { Covenant.spawnCovenantBloodStorm(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.6); return; }
                    if (id === 'rr_u1') { Covenant.spawnCovenantRailgun(vfx, event.pos.x - 200, event.pos.y, event.pos.x, event.pos.y, color); camera.addTrauma(0.8); return; }
                    if (id === 'rr_u2') { Covenant.spawnCovenantNuke(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.8); return; }
                    if (id === 'mr_u1') { Covenant.spawnCovenantMeteor(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.7); return; }
                    if (id === 'mr_u2') { Covenant.spawnCovenantDeathFinger(vfx, event.pos.x, event.pos.y - 200, event.pos.x, event.pos.y, color); camera.addTrauma(0.7); return; }
                    if (id === 'sr_u1') { Covenant.spawnCovenantSoulLink(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }
                    if (id === 'sr_u2') { Covenant.spawnCovenantAncestors(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }

                    // Generic Grid Reaction (Ground Cracks/Fields)
                    affectedHexes.forEach(h => {
                        if (engine.map.isValid(h.q, h.r)) {
                            const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                            const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                            const tileVisualY = tilePos.y - hHeight;
                            const dist = HexUtils.dist(centerHex, h);
                            const delay = dist * 0.06;

                            Generic.spawnGridImpact(vfx, tilePos.x, tileVisualY, event.color || '#fff', Team.BLUE, delay);
                        }
                    });
                }

                // Generic Fallback
                Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 0, 20, event.color || '#fff', 2.0, 0.6, 'SPARK');
                Generic.addImpact(vfx, event.pos.x, visualGroundY, 0, event.color || '#fff', 'BLAST', 0.5);
                Generic.spawnShockwave(vfx, event.pos.x, visualGroundY, event.color || '#fff', 0.6);
                camera.addTrauma(0.25); 
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                } else {
                    const hitColor = event.skill?.color || '#fff';
                    Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 20, 8, hitColor, 1.0, 0.3, 'SPARK');
                }
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) {
                    const vx = dAgent.physics.vx || 0;
                    const vy = dAgent.physics.vy || 0;
                    Generic.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role, vx, vy);
                }
                camera.addTrauma(0.15); 
                break;

            case 'SPAWN':
                Generic.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                Generic.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                Generic.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                if (event.skill?.id === 'mr_u2') {
                    Generic.spawnDeathRay(vfx, source.px, source.py - sH - 45, event.pos.x, visualGroundY - 30, event.color || '#be123c');
                    return;
                }

                Generic.spawnBeam(vfx, source.px, source.py - sH - 40, 0, event.pos.x, visualGroundY - 30, 0, event.color || '#fff');
                Generic.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    // NEW: Color coding based on VICTIM TEAM
                    // Blue Team = Blue chips/blood
                    // Red Team = Red chips/blood
                    const isVictimBlue = t.team === Team.BLUE;
                    const debrisColor = isVictimBlue ? THEME_IMPERIAL.energy : THEME_COVENANT.secondary;

                    Generic.spawnPhysicsSplatter(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, debrisColor);
                }
            }
        } else {
            // Unknown source (e.g. DoT tick)
            Generic.spawnPhysicsSplatter(vfx, event.pos.x, visualGroundY, 20, 0, -1, event.color || '#94a3b8');
        }

        if (dmg > 50) camera.addTrauma(0.05); 
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.15); 

            if (skill && skill.id === 'mr_u2') {
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#000', 3.0, 0.5, 'SPARK');
                Generic.addImpact(vfx, event.pos.x, visualY, 20, '#be123c', 'BLAST', 0.5);
                Generic.spawnShockwave(vfx, event.pos.x, visualY, '#000', 0.5);
                return; 
            }

            if (faction === Team.BLUE) {
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.5, 0.8, 'SPARK');
                Generic.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 0.8);
            } else {
                Generic.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            if (skill && skill.id === 'wr_u1') { // Ragnarok Hit
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#991b1b', 2.0, 1.0, 'DEBRIS');
                Generic.addImpact(vfx, event.pos.x, visualY, 0, '#ef4444', 'BLAST', 0.8);
                camera.addTrauma(0.5);
            } 

        } else {
            // Standard Hit Logic
            let dx = 0, dy = 0;
            let debrisColor = color; 

            if (event.targetId) {
                const t = engine.agents.find(a => a.id === event.targetId);
                if (t) {
                    const isVictimBlue = t.team === Team.BLUE;
                    debrisColor = isVictimBlue ? THEME_IMPERIAL.energy : THEME_COVENANT.secondary;
                }
            }

            if (source) {
                const len = Math.sqrt((event.pos.x - source.px)**2 + (event.pos.y - source.py)**2) || 1;
                dx = (event.pos.x - source.px) / len;
                dy = (event.pos.y - source.py) / len;
            }

            if (visualType === 'SMASH') {
                Generic.addImpact(vfx, event.pos.x, centerVisualY, 0, color, 'SHOCKWAVE', 0.4);
                // Smash creates heavy splatter using VICTIM color
                Generic.spawnPhysicsSplatter(vfx, event.pos.x, centerVisualY, 10, dx, dy, debrisColor);
            } 
            else if (visualType === 'SLASH') {
                if (source) {
                    Generic.spawnPhysicsSplatter(vfx, event.pos.x, visualY, 30, dx, dy, debrisColor);
                } else {
                    Generic.spawnExplosion(vfx, event.pos.x, visualY, 30, 8, color, 1.5, 0.4, 'SPARK');
                }
            }
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                Generic.addImpact(vfx, event.pos.x, visualY, 20, color, 'BLAST', 0.5);
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 20, 5, color, 0.5, 1.0, 'SMOKE');
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 20, 8, '#fff', 1.0, 0.3, 'SPARK');
            }
            else {
                // Magic Bolt / Arrow
                Generic.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.4);
                if (dx !== 0 || dy !== 0) {
                    Generic.spawnPhysicsSplatter(vfx, event.pos.x, visualY, 30, dx, dy, debrisColor);
                } else {
                    Generic.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 2.0, 0.4, 'SPARK');
                }
            }
        }
    }
}

import { Agent, GameEngine } from "../game";
import { Projectile, Skill, BattleField } from "../../types";
import { ProjectileSystem } from "./combat/ProjectileSystem";
import { SkillResolutionSystem } from "./combat/SkillResolutionSystem";
import { HexUtils, Vector } from "../utils";
import { HEX_SIZE } from "../../constants";
import * as GenericVFX from "./vfx/spawners/generic";

const FIELD_TICK_RATE = 0.5; // Damage every 0.5s

export class CombatSystem {
    public projectileSystem: ProjectileSystem;
    public skillResolution: SkillResolutionSystem;

    constructor() {
        this.projectileSystem = new ProjectileSystem();
        this.skillResolution = new SkillResolutionSystem();
    }

    // Proxy for accessors to maintain GameEngine compatibility
    get projectiles(): Projectile[] { return this.projectileSystem.projectiles; }
    set projectiles(v: Projectile[]) { this.projectileSystem.projectiles = v; }

    public reset() {
        this.projectileSystem.projectiles = [];
    }

    public update(dt: number, engine: GameEngine) {
        // 1. Casting Updates (Logic)
        engine.agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.castingSkillIdx !== -1) {
                this.skillResolution.updateCasting(a, dt, engine);
            }
        });

        // 2. Projectile Physics & Impacts
        this.projectileSystem.update(dt, engine, this.skillResolution);

        // 3. Update Persistent Ground Fields (Poison clouds, etc.)
        this.updateFields(dt, engine);

        // 4. Update Field Physics (Gravity/Suction - Per Frame)
        this.updateFieldPhysics(dt, engine);
    }

    private updateFields(dt: number, engine: GameEngine) {
        // Reverse iterate to remove expired fields safely
        for (let i = engine.fields.length - 1; i >= 0; i--) {
            const field = engine.fields[i];

            field.duration -= dt;
            field.tickTimer -= dt;

            // Handle Logic Tick
            if (field.tickTimer <= 0) {
                field.tickTimer = FIELD_TICK_RATE;
                this.resolveFieldTick(field, engine);
            }

            // Expiry
            if (field.duration <= 0) {
                engine.fields.splice(i, 1);
            }
        }
    }

    private updateFieldPhysics(dt: number, engine: GameEngine) {
        // Optimized physics loop for continuous effects (Black Hole / Gravity)
        // This runs every frame, unlike damage ticks.

        for (const field of engine.fields) {
            // Only 'PULL' fields generate gravity
            if (field.skill.ccType !== 'PULL' && field.skill.ccType2 !== 'PULL') continue;

            const rPxSq = field.radiusPx * field.radiusPx;
            const pullForce = (field.skill.ccForce || 5) * 150; // Base force multiplier

            engine.agents.forEach(agent => {
                if (agent.hp <= 0 || agent.banished || agent.team === field.team) return;

                const dx = field.pos.x - agent.px;
                const dy = field.pos.y - agent.py;
                const distSq = dx * dx + dy * dy;

                if (distSq <= rPxSq && distSq > 100) { // Don't pull if already at center (jitter fix)
                    // 1. GRAVITY: Apply force towards center
                    // We calculate a normalized vector
                    const dist = Math.sqrt(distSq);
                    const nx = dx / dist;
                    const ny = dy / dist;

                    // Apply continuous acceleration
                    // We rely on PhysicsEngine damping to prevent infinite speed
                    agent.physics.vx += nx * pullForce * dt;
                    agent.physics.vy += ny * pullForce * dt;

                    // 2. EVENT HORIZON: Massive Slow
                    // If you are in a black hole, you can barely walk away
                    agent.moveSpeedMult = 0.3; // 70% Slow override
                }
            });
        }
    }

    private resolveFieldTick(field: BattleField, engine: GameEngine) {
        const source = engine.agents.find(a => a.id === field.sourceId);

        const rPx = field.radiusPx * field.radiusPx;

        engine.agents.forEach(agent => {
            if (agent.hp <= 0 || agent.banished || agent.team === field.team) return; // Friendly fire OFF

            const dx = agent.px - field.pos.x;
            const dy = agent.py - field.pos.y;
            const distSq = dx * dx + dy * dy;

            if (distSq <= rPx) {
                // Determine damage. 
                // Use ccForce if available, otherwise 20% of power.
                // For Black Holes, damage is usually low per tick but high utility.
                const damage = (field.skill.power * 0.2) || 10;

                // Direct HP modification
                agent.hp = Math.max(0, agent.hp - damage);

                // Add tiny floating text
                engine.events.push({ 
                    type: 'DAMAGE', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: -Math.floor(damage), 
                    color: field.color 
                });

                // Apply Status Effect if applicable (Refresh DoT timer)
                // Note: We don't apply PULL here, that's handled in updateFieldPhysics
                if (field.skill.ccType && field.skill.ccType !== 'PULL') {
                    this.skillResolution.applyCC(
                        source || agent, agent, field.skill, 
                        field.skill.ccType, 1.0, 0, undefined, engine
                    );
                }
            }
        });
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        this.projectileSystem.spawnProjectile(source, skill, engine);
    }

    public spawnField(source: Agent, skill: Skill, pos: {x: number, y: number}, engine: GameEngine) {
        // Convert radius to pixels
        const radiusGrid = skill.aoeRadius || 1;
        const radiusPx = radiusGrid * HEX_SIZE * 1.5; // Approximation for coverage

        // Determine Duration: Use ccDur if > 0, else default 5s
        const duration = (skill.ccDur && skill.ccDur > 0) ? skill.ccDur : 5.0;

        // Calculate Q, R from Pos for Grid Lookup
        const hex = HexUtils.fromPx(pos.x, pos.y, engine.mapConfig);

        const field: BattleField = {
            id: Math.random().toString(36).substr(2, 5),
            pos: pos,
            q: hex.q, 
            r: hex.r, 
            radius: radiusGrid,
            radiusPx: radiusPx,
            skill: skill,
            sourceId: source.id,
            team: source.team,
            duration: duration,
            tickTimer: 0, // Tick immediately on spawn
            visualType: skill.visual || 'SMOKE',
            color: skill.color
        };

        engine.fields.push(field);

        // 1. Initial Puff
        GenericVFX.spawnLingeringField(engine.renderer!.vfx, pos.x, pos.y, skill.color, 'SMOKE', 1.0, 0);

        // 2. Persistent Ground Effect (Visual)
        // CRITICAL: This was missing, causing fields to be invisible.
        if (engine.renderer) {
            const p = engine.renderer.vfx.state.getParticle();
            p.type = 'GRID_FIELD';
            p.life = duration; 
            p.maxLife = duration;
            // Align perfectly with grid center to prevent offset issues
            const pPos = HexUtils.toPx(hex.q, hex.r, engine.mapConfig);
            p.x = pPos.x; 
            p.y = pPos.y; 
            p.z = 0; // Will be lifted by Renderer to terrain height
            p.color = skill.color;
            p.size = radiusGrid;
            engine.renderer.vfx.state.particles.push(p);
        }
    }
}

import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { isChaosStyle } from "../systems/vfx/utils";
import { Skill } from "../../types";

// Precomputed Hex for Geometry
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

const VISIBLE_FACES = [0, 1, 5]; 

export const SurfaceAssets = {

    pathHex(ctx: CanvasRenderingContext2D, x: number, y: number, scale: number = 1.0) {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const c = HEX_CORNERS[i];
            if (i === 0) ctx.moveTo(x + c.x * scale, y + c.y * scale);
            else ctx.lineTo(x + c.x * scale, y + c.y * scale);
        }
        ctx.closePath();
    },

    resolveFieldVisual(skill: Skill, visualType: string): string {
        // Detect Black Holes / Gravity
        if (skill.ccType === 'PULL' || skill.name.includes('黑洞') || skill.name.includes('視界') || skill.name.includes('Gravity')) return 'GRAVITY';

        // Detect Poison / Fog / Clouds
        if (skill.ccType === 'DOT' || skill.name.includes('酸') || skill.name.includes('毒') || skill.name.includes('霧') || skill.name.includes('腐化')) return 'POISON_FOG';

        // Detect Blood / Liquids
        if (skill.name.includes('血') || skill.name.includes('池')) return 'BLOOD_POOL';

        // Detect Lava / Fire
        if (skill.name.includes('熔岩') || skill.name.includes('火') || skill.name.includes('Magma')) return 'LAVA_POOL';

        // Detect Ice
        if (skill.name.includes('冰') || skill.name.includes('雪') || skill.name.includes('Frost')) return 'ICE_FIELD';

        // Detect Cracks
        if (skill.visual === 'SMASH' || skill.name.includes('震') || skill.name.includes('裂')) return 'CRACK';

        return visualType; // Fallback
    },

    // 1. LIQUID SURFACE (Blood, Lava, Acid)
    // Concept: Wobbly meniscus inside the hex, specular highlights
    drawLiquidSurface(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); // Flatten to isometric plane

        // Wobbly Circle Base
        ctx.beginPath();
        const r = HEX_SIZE * 0.9;
        const segments = 12;
        for (let i = 0; i <= segments; i++) {
            const angle = (i / segments) * Math.PI * 2;
            // Noise offset based on time and angle to create surface tension wobble
            const noise = Math.sin(angle * 3 + time * 2) * 3 + Math.cos(angle * 5 - time) * 2;
            const px = Math.cos(angle) * (r + noise);
            const py = Math.sin(angle) * (r + noise);
            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();

        // Fluid Body
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.8 * intensity;
        ctx.fill();

        // Inner darker pool (Depth)
        ctx.globalCompositeOperation = 'multiply';
        ctx.beginPath();
        ctx.arc(0, 0, r * 0.6, 0, Math.PI * 2);
        ctx.fillStyle = color; // Darker version via multiply
        ctx.globalAlpha = 0.5;
        ctx.fill();

        // Specular Highlights (Surface Tension)
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.6;
        ctx.fillStyle = '#fff';

        // Highlight 1 (Top Edge Reflection)
        ctx.beginPath();
        ctx.ellipse(0, -r * 0.6, r * 0.4, 4, 0, 0, Math.PI*2);
        ctx.fill();

        // Highlight 2 (Bubble)
        const bubbleX = Math.sin(time) * r * 0.3;
        const bubbleY = Math.cos(time) * r * 0.3;
        ctx.beginPath(); ctx.arc(bubbleX, bubbleY, 3, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    // 2. VOLUMETRIC FOG (Poison, Smoke)
    // Concept: Multiple drifting cloud puffs with soft gradients to simulate volume
    drawVolumetricFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        ctx.save();
        ctx.translate(x, y);

        // Create cloud puffs
        const puffs = 5;
        for(let i=0; i<puffs; i++) {
            const tOffset = i * 1.5;

            // Orbiting motion around center of tile
            const angle = time * 0.5 + i * (Math.PI * 2 / puffs);
            const dist = Math.sin(time * 0.2 + i) * 15;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist * ISO_SCALE_Y - 15; // Floating slightly up

            // Breath (Scale)
            const scale = 1.0 + Math.sin(time + i) * 0.2;
            const radius = 25 * scale;

            const grad = ctx.createRadialGradient(px, py, 0, px, py, radius);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.globalAlpha = 0.3; // Low alpha for stacking
            ctx.globalCompositeOperation = 'screen'; // Additive blending for gas
            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.arc(px, py, radius, 0, Math.PI*2);
            ctx.fill();
        }

        // Ground Haze (Base layer)
        ctx.globalCompositeOperation = 'source-over';
        ctx.scale(1, ISO_SCALE_Y);
        ctx.globalAlpha = 0.2;
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    // 3. GROUND CRACKS (Smash, Earthquake)
    // Concept: Jagged fractal lines radiating from center
    drawGroundCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.strokeStyle = color; // Lava color or Energy color
        ctx.lineWidth = 2 * intensity;
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';
        ctx.globalCompositeOperation = 'lighter'; // Glowing cracks

        const branches = 4;
        for(let i=0; i<branches; i++) {
            const angle = (i / branches) * Math.PI * 2 + (Math.random()*0.5);
            ctx.beginPath();
            ctx.moveTo(0, 0);

            // Jagged segments
            let cx = 0, cy = 0;
            const len = HEX_SIZE * intensity;
            const steps = 3;
            for(let j=0; j<steps; j++) {
                const stepLen = len / steps;
                cx += Math.cos(angle) * stepLen + (Math.random()-0.5) * 8;
                cy += Math.sin(angle) * stepLen + (Math.random()-0.5) * 8;
                ctx.lineTo(cx, cy);
            }
            ctx.stroke();
        }

        // Glowing Core
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, 0, 8 * intensity, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    // Original Extruded Hex (Kept for basic fields/walls/indicators)
    drawExtrudedHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        height: number,
        color: string,
        opacity: number,
        isHollow: boolean = false
    ) {
        const topY = y - height;
        const bottomY = y;

        ctx.save();
        ctx.globalAlpha = opacity * 0.6;

        for (const i of VISIBLE_FACES) {
            const idx1 = i;
            const idx2 = (i + 1) % 6;

            const c1 = HEX_CORNERS[idx1];
            const c2 = HEX_CORNERS[idx2];

            let shade = 1.0;
            if (i === 5) shade = 0.7; 
            if (i === 0) shade = 0.5; 
            if (i === 1) shade = 0.9; 

            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c2.x, topY + c2.y);
            ctx.lineTo(x + c2.x, bottomY + c2.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.closePath();

            const oldAlpha = ctx.globalAlpha;
            ctx.globalAlpha = oldAlpha * shade;
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.8;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.stroke();

            ctx.globalAlpha = oldAlpha;
        }

        if (!isHollow) {
            ctx.globalAlpha = opacity;
            ctx.fillStyle = color;
            this.pathHex(ctx, x, topY, 1.0);
            ctx.fill();

            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = opacity * 0.5;
            this.pathHex(ctx, x, topY, 0.8);
            ctx.fill();
            ctx.globalCompositeOperation = 'source-over';
        }

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        this.pathHex(ctx, x, topY, 1.0);
        ctx.stroke();

        ctx.restore();
    },

    drawTacticalGrid(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        progress: number, 
        isCenter: boolean
    ) {
        ctx.save();
        const isChaos = isChaosStyle(color);
        const alpha = 0.6 + Math.sin(Date.now() * 0.01) * 0.2;

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over';
            ctx.lineWidth = 2;
            ctx.strokeStyle = color;
            ctx.globalAlpha = alpha;
            this.pathHex(ctx, x, y, 0.9);
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(x - 15, y - 10); ctx.lineTo(x + 15, y + 10);
            ctx.moveTo(x + 15, y - 10); ctx.lineTo(x - 15, y + 10);
            ctx.stroke();
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.2;
            ctx.fill();
        } else {
            const height = 10 * progress;
            this.drawExtrudedHex(ctx, x, y, height, color, 0.4, true); 
            const topY = y - height;
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.8;
            this.pathHex(ctx, x, topY, 1.0);
            ctx.stroke();
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.1;
            this.pathHex(ctx, x, topY, 0.9);
            ctx.fill();
        }
        ctx.restore();
    },

    drawTexture(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        color: string,
        globalTime: number
    ) {
        ctx.save();
        ctx.fillStyle = color;
        ctx.strokeStyle = color;
        const n = Math.sin(q * 12.9898 + r * 78.233) * 43758.5453;
        const seed = n - Math.floor(n);

        if (type === 'MAGMA') {
            if (seed > 0.5) {
                ctx.globalAlpha = 0.6;
                ctx.beginPath();
                ctx.moveTo(cx - 10, cy);
                ctx.lineTo(cx, cy + 5);
                ctx.lineTo(cx + 10, cy - 2);
                ctx.stroke();
            }
        } else if (type === 'VOID') {
            if (seed > 0.7) {
                ctx.fillStyle = '#38bdf8';
                ctx.globalAlpha = 0.4;
                ctx.fillRect(cx - 2, cy - 2, 4, 4);
                ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx+10, cy-5); ctx.stroke();
            }
        }
        ctx.restore();
    },

    drawUnitRune(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        t: number, 
        progress: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 
        const r = HEX_SIZE * 0.8 * progress; 
        ctx.globalAlpha = 0.8;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.stroke();
        ctx.rotate(t * 2);
        ctx.lineWidth = 4;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI/4); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, 0, r, Math.PI, Math.PI + Math.PI/4); ctx.stroke();
        ctx.restore();
    }
};

import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { AssetManager } from "../../../assets";
import { ISO_SCALE_Y } from "../../../../constants";
import { SurfaceAssets } from "../../../graphics/SurfaceAssets";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // 1. POSITIONING
        // Some effects are grid-locked (Tiles), others are free-floating
        const isGridLocked = ['GRID_FIELD', 'DOMAIN', 'SHOCKWAVE', 'PILLAR'].includes(p.type);

        if (isGridLocked) {
            ctx.translate(Math.round(p.x), Math.round(p.y));
        } else {
            ctx.translate(p.x, p.y);
        }

        const now = Date.now() / 1000;

        // --- RENDER LOGIC BY TYPE ---

        if (p.type === 'GRID_FIELD') {
            // 🌍 GROUND FIELD REFACTOR
            // NOTE: The Z-offset (Terrain Height) is applied in VFXRenderer via translation before calling this.
            // So we draw at local (0,0) which corresponds to the Top Face of the tile.

            // Heuristic detection based on color/name isn't perfect, but we use color as primary key here.
            // Dark colors = Gravity/Black Hole
            const isDark = p.color === '#000000' || p.color === '#0f172a' || p.color.includes('#1e');

            if (isDark) {
                // ⚫ GRAVITY WELL / BLACK HOLE
                // Draw a dark spiral on the ground
                ctx.scale(1, ISO_SCALE_Y);
                ctx.globalAlpha = 0.8;
                ctx.fillStyle = '#000';
                ctx.beginPath(); ctx.arc(0, 0, 25, 0, Math.PI*2); ctx.fill();

                // Accretion Disk
                ctx.rotate(now * 2);
                ctx.strokeStyle = '#4f46e5'; // Indigo/Purple
                ctx.lineWidth = 2;
                ctx.beginPath();
                for(let i=0; i<3; i++) {
                    const r = 10 + i * 8;
                    const a = i * (Math.PI*2/3);
                    ctx.arc(0, 0, r, a, a + Math.PI);
                }
                ctx.stroke();

            } else if (p.color === '#be123c' || p.color === '#7f1d1d' || p.color.includes('red') || p.color.includes('blood')) {
                // 🩸 BLOOD POOL (Liquid)
                SurfaceAssets.drawLiquidSurface(ctx, 0, 0, '#991b1b', now, progress);
            } else if (p.color === '#a3e635' || p.color.includes('green') || p.color.includes('purple')) {
                // ☣️ POISON FOG (Volumetric)
                SurfaceAssets.drawVolumetricFog(ctx, 0, 0, p.color, now);
            } else if (p.color === '#ea580c' || p.color.includes('orange')) {
                // 🌋 LAVA / MAGMA (Liquid + Glow + Cracks)
                SurfaceAssets.drawLiquidSurface(ctx, 0, 0, '#ea580c', now, progress);
                SurfaceAssets.drawGroundCracks(ctx, 0, 0, '#fdba74', progress);
            } else {
                // 🧱 GENERIC BLOCK (Fallback)
                const height = 15 * progress;
                SurfaceAssets.drawExtrudedHex(ctx, 0, 0, height, p.color, 0.6, false);
            }

        } else if (p.type === 'ROCK') {
            // 🪨 STONE DEBRIS (Polished)
            ctx.rotate(p.rotation);
            // Default to grey if color is white/default, else tint it
            const fill = (p.color === '#fff' || p.color === '#ffffff') ? '#94a3b8' : p.color;
            ctx.fillStyle = fill;

            // Draw irregular polygon (Rock shape)
            ctx.beginPath();
            const s = p.size;
            // 5-point random shape
            ctx.moveTo(-s, -s*0.5);
            ctx.lineTo(0, -s);
            ctx.lineTo(s, -s*0.2);
            ctx.lineTo(s*0.6, s*0.8);
            ctx.lineTo(-s*0.6, s*0.6);
            ctx.closePath();
            ctx.fill();

            // Rim Light (Highlight) based on rotation
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.moveTo(-s, -s*0.5);
            ctx.lineTo(0, -s);
            ctx.lineTo(s, -s*0.2);
            ctx.stroke();

        } else if (p.type === 'BEAM' || p.type === 'DEATH_RAY') {
            // ⚡ HIGH ENERGY BEAM (Railgun / Laser)
            if (p.targetX !== undefined) {
                const dx = p.targetX - p.x;
                const dy = p.targetY! - p.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                const angle = Math.atan2(dy, dx);

                ctx.rotate(angle);

                // Dynamic Width: Pulse based on life (Expansion -> Hold -> Collapse)
                const lifeRatio = p.life / p.maxLife;
                const widthMod = Math.sin(lifeRatio * Math.PI); 
                const baseWidth = p.size * widthMod;

                if (baseWidth > 0.5) {
                    ctx.lineCap = 'round';

                    // 1. Aura (Wide, Transparent)
                    ctx.globalCompositeOperation = isChaos ? 'source-over' : 'lighter';
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = baseWidth * 4;
                    ctx.globalAlpha = 0.2 * widthMod;
                    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

                    // 2. Core (Intense White)
                    ctx.globalCompositeOperation = 'lighter';
                    ctx.lineWidth = baseWidth;
                    ctx.strokeStyle = '#fff';
                    ctx.shadowColor = p.color;
                    ctx.shadowBlur = 20; 
                    ctx.globalAlpha = 0.9;
                    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();
                    ctx.shadowBlur = 0;

                    // 3. Shock Rings (Sonic Boom along beam)
                    const ringCount = Math.floor(dist / 40);
                    ctx.lineWidth = 2;
                    ctx.strokeStyle = p.color;
                    ctx.globalAlpha = 0.6 * widthMod;

                    for(let i=1; i<ringCount; i++) {
                        const rx = i * 40 + (Date.now() * 0.2) % 40; 
                        if (rx > dist) continue;
                        const rw = baseWidth * 2;
                        const rh = baseWidth * 4; 
                        ctx.beginPath(); ctx.ellipse(rx, 0, rw, rh, 0, 0, Math.PI*2); ctx.stroke();
                    }

                    // 4. Lightning Arcs (Chaos/Death Ray only)
                    if (isChaos || p.type === 'DEATH_RAY') {
                        ctx.beginPath(); ctx.moveTo(0, 0);
                        const segments = 10;
                        for(let i=1; i<=segments; i++) {
                            const lx = (dist / segments) * i;
                            const ly = (Math.random() - 0.5) * baseWidth * 4;
                            ctx.lineTo(lx, ly);
                        }
                        ctx.strokeStyle = p.color; ctx.lineWidth = 2; ctx.stroke();
                    }
                }
            }

        } else if (p.type === 'PILLAR') {
            // 🏛️ ORBITAL STRIKE
            const h = 1200; 
            const w = p.size; 

            let alpha = 1.0;
            let currentH = h;

            if (progress < 0.1) currentH = h * (progress / 0.1);
            if (progress > 0.8) alpha = 1 - (progress - 0.8) / 0.2;

            ctx.globalCompositeOperation = 'screen';

            // Ground Impact Ring
            ctx.save();
            ctx.scale(1, ISO_SCALE_Y);
            ctx.fillStyle = p.color;
            ctx.globalAlpha = alpha * 0.3;
            ctx.beginPath(); ctx.arc(0, 0, w * 1.5, 0, Math.PI*2); ctx.fill();

            const shockR = w * (1 + (Date.now() * 0.005) % 1);
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = alpha * (1 - ((shockR - w)/w));
            ctx.beginPath(); ctx.arc(0, 0, shockR, 0, Math.PI*2); ctx.stroke();
            ctx.restore();

            // Shaft
            const grad = ctx.createLinearGradient(0, 0, 0, -currentH);
            grad.addColorStop(0, '#fff'); 
            grad.addColorStop(0.1, p.color);
            grad.addColorStop(1, 'transparent'); 

            ctx.fillStyle = grad;
            ctx.globalAlpha = alpha * 0.8;
            ctx.fillRect(-w/2, -currentH, w, currentH);

            // Core
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = alpha;
            ctx.fillRect(-w/4, -currentH, w/2, currentH);

            // Energy Spirals
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 3;
            ctx.globalAlpha = alpha * 0.5;
            ctx.beginPath();
            const spiralFreq = 0.05;
            const timeOffset = Date.now() * 0.5;
            for(let y = 0; y < currentH; y += 20) {
                const xOffset = Math.sin(y * spiralFreq - timeOffset) * w;
                if (y===0) ctx.moveTo(xOffset, -y);
                else ctx.lineTo(xOffset, -y);
            }
            ctx.stroke();

        } else if (p.type === 'BLAST') {
            // 💥 STARBURST
            const scale = p.size * (Math.pow(progress, 0.5)); 

            ctx.scale(scale, scale * ISO_SCALE_Y); 
            ctx.globalCompositeOperation = 'lighter';

            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - progress; 

            ctx.beginPath();
            const spikes = 16; 
            for(let i=0; i<spikes*2; i++) {
                const angle = (i / (spikes*2)) * Math.PI * 2;
                const r = (i % 2 === 0) ? 1.0 : 0.2;
                ctx.lineTo(Math.cos(angle) * r, Math.sin(angle) * r);
            }
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 0.1; 
            ctx.beginPath(); ctx.arc(0, 0, 0.6, 0, Math.PI*2); ctx.stroke();

        } else if (p.type === 'SMOKE') {
            // ☁️ CLUSTER SMOKE
            const growth = 1.0 + progress; 
            const alpha = (1 - progress); 

            ctx.scale(growth, growth);
            ctx.rotate(p.rotation + progress); 

            ctx.globalAlpha = alpha * 0.5;

            if (isChaos) {
                ctx.globalCompositeOperation = 'source-over';
                ctx.fillStyle = p.color; 
            } else {
                ctx.globalCompositeOperation = 'screen';
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, p.size);
                grad.addColorStop(0, p.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
            }

            ctx.beginPath();
            ctx.arc(0, 0, p.size, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'SPARK') {
            // ✨ STREAK SPARKS
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy);
            const stretch = Math.min(5.0, 1.0 + speed / 80); 
            const angle = Math.atan2(p.vy, p.vx); 

            ctx.rotate(angle);
            ctx.scale(stretch, 0.4); 

            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = 1.0 - progress; 

            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.ellipse(0, 0, p.size, p.size, 0, 0, Math.PI*2); ctx.fill();

            ctx.fillStyle = p.color;
            ctx.globalAlpha = (1.0 - progress) * 0.7;
            ctx.beginPath(); ctx.ellipse(-p.size*2, 0, p.size * 4, p.size*2, 0, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'DOMAIN') {
            const maxH = 120;
            const h = maxH * Math.sin(progress * Math.PI); 
            const alpha = Math.min(1, Math.sin(progress * Math.PI) * 1.5);
            SurfaceAssets.drawExtrudedHex(ctx, 0, 0, h, p.color, alpha * 0.2, true); 
            ctx.globalCompositeOperation = 'screen';
            SurfaceAssets.drawUnitRune(ctx, 0, 0, p.color, Date.now() * 0.001, 1.0);

        } else if (p.type === 'SHOCKWAVE') {
            const r = progress * p.size; 
            ctx.globalAlpha = 1 - progress; 
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 4;

            if (isChaos) ctx.globalCompositeOperation = 'source-over';
            else ctx.globalCompositeOperation = 'screen';

            SurfaceAssets.pathHex(ctx, 0, 0, r / 32); 
            ctx.stroke();

        } else if (p.type === 'GLOW') {
            const img = AssetManager.getGlowSprite(p.color);
            const scale = (p.size / 64) * (0.8 + Math.sin(progress * Math.PI) * 0.2); 
            ctx.globalAlpha = 1 - progress;
            ctx.globalCompositeOperation = 'screen';
            ctx.scale(scale, scale);
            ctx.drawImage(img, -32, -32);

        } else if (['DEBRIS', 'SHARD', 'CHIP'].includes(p.type)) {
            // Physical debris chips
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;
            ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
        }

        ctx.restore();
    }
};

import { Agent } from "../game";
import { COLORS, UNIT_VISUAL_HEIGHT, HUD_PADDING } from "../../constants";
import { HexUtils, MapConfig } from "../utils";
import { AssetManager } from "../assets";
import { Team } from "../../types";

// --- Constants ---
const GRAVITY = 200;
const TEXT_LIFESPAN = 1.0;
const BAR_WIDTH = 44;
const BAR_HEIGHT = 6;
const BAR_PADDING = 3;

interface FloatingText {
    active: boolean;
    x: number; 
    y: number;
    vx: number; 
    vy: number;
    text: string; 
    color: string;
    life: number; 
    maxLife: number;
    size: number;
    type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK';
    isUlt: boolean; 
}

export class HUDSystem {
    // Active Texts
    damageNumbers: FloatingText[] = [];

    // Memory Pool
    private pool: FloatingText[] = [];

    constructor() {
        for(let i=0; i<50; i++) this.pool.push(this.createEmpty());
    }

    public reset() {
        for (const d of this.damageNumbers) {
            this.release(d);
        }
        this.damageNumbers.length = 0;
    }

    private createEmpty(): FloatingText {
        return {
            active: false,
            x: 0, y: 0, vx: 0, vy: 0,
            text: '', color: '#fff', life: 0, maxLife: 0, size: 0,
            type: 'DAMAGE', isUlt: false
        };
    }

    public addFloatingText(x: number, y: number, text: string, color: string, size: number, type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' | 'KILL_STREAK' = 'DAMAGE', isUlt: boolean = false) {
        if (type === 'KILL_STREAK') {
            for (let i = this.damageNumbers.length - 1; i >= 0; i--) {
                if (this.damageNumbers[i].type === 'KILL_STREAK') {
                    this.release(this.damageNumbers[i]);
                    this.damageNumbers.splice(i, 1);
                }
            }
        }

        let vx = 0;
        let vy = 0;
        let life = TEXT_LIFESPAN;

        if (type === 'SHOUT') {
            if (isUlt) {
                vy = -5; 
                life = 2.5; 
                size = 24; 
            } else {
                vy = -20; 
                life = 1.2;
                size = 14; 
            }
        } else if (type === 'CC') {
            vy = -20; 
            life = 1.5;
        } else if (type === 'KILL_STREAK') {
            vx = 0;
            vy = -30;
            life = 3.5; 
            size = 32; 
        } else {
            vx = (Math.random() - 0.5) * 60; 
            vy = -100; 
        }

        let ft: FloatingText;
        if (this.pool.length > 0) {
            ft = this.pool.pop()!;
        } else {
            ft = this.createEmpty();
        }

        ft.active = true;
        ft.x = x; ft.y = y;
        ft.vx = vx; ft.vy = vy;
        ft.text = text; ft.color = color;
        ft.life = life; ft.maxLife = life;
        ft.size = size; ft.type = type;
        ft.isUlt = isUlt;

        this.damageNumbers.push(ft);
    }

    private release(ft: FloatingText) {
        ft.active = false;
        this.pool.push(ft);
    }

    update(dt: number) {
        for (let i = this.damageNumbers.length - 1; i >= 0; i--) { 
            const d = this.damageNumbers[i]; 
            d.life -= dt; 

            d.x += d.vx * dt;
            d.y += d.vy * dt; 

            if (d.type === 'DAMAGE' || d.type === 'HEAL') {
                d.vy += GRAVITY * dt;
            } else if (d.type === 'SHOUT' || d.type === 'CC') {
                d.vy *= 0.95; 
            } else if (d.type === 'KILL_STREAK') {
                d.vy *= 0.92; 
            }

            if (d.life <= 0) {
                this.release(d);
                this.damageNumbers.splice(i, 1); 
            }
        }
    }

    draw(ctx: CanvasRenderingContext2D, agents: Agent[], getTerrainHeight: (q: number, r: number) => number, mapConfig: MapConfig, highlight: Agent | null, time: number) {
        agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.spawnTimer > 0) return; 

            let h = 0;
            if (a.isMoving && a.path.length > 0) {
                const startH = getTerrainHeight(a.q, a.r);
                const endHex = a.path[0];
                const endH = getTerrainHeight(endHex.q, endHex.r);
                h = HexUtils.lerp(startH, endH, a.moveProgress);
            } else {
                const visualHex = HexUtils.fromPx(a.px, a.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            }

            const groundY = a.py - h;
            const physicsOffsetY = a.physics.y - a.physics.z; 
            const anchorY = groundY - UNIT_VISUAL_HEIGHT + physicsOffsetY - HUD_PADDING;
            const headX = a.px + a.physics.x;

            const isSelected = (a === highlight);
            this.drawUnitBars(ctx, a, headX, anchorY, isSelected, time);
            this.drawUnitStatusGauges(ctx, a, headX, anchorY);
        });

        this.drawFloatingText(ctx);
    }

    private drawUnitStatusGauges(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number) {
        let activeTimer = 0;
        let maxTimer = 0;
        let iconType = '';
        let gaugeColor = '';

        if (agent.banished) {
            activeTimer = agent.banishTimer;
            maxTimer = agent.banishMax || activeTimer;

            if (agent.visualStatus === 'POLYMORPH') {
                iconType = 'POLYMORPH'; gaugeColor = '#d8b4fe';
            } else if (agent.visualStatus === 'STASIS') {
                iconType = 'STASIS'; gaugeColor = '#facc15';
            } else {
                iconType = 'BANISH'; gaugeColor = '#7e22ce';
            }
        } else if (agent.stunTimer > 0) {
            activeTimer = agent.stunTimer;
            maxTimer = agent.stunMax || activeTimer;
            iconType = 'STUN'; gaugeColor = '#fbbf24';
        } else if (agent.silenceTimer > 0) {
            activeTimer = agent.silenceTimer;
            maxTimer = agent.silenceMax || activeTimer;
            iconType = 'SILENCE'; gaugeColor = '#94a3b8';
        } else if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                this.drawCircularGauge(ctx, x, y, progress, skill.visual || 'BOLT', skill.color, true);
                return;
            }
        }

        if (iconType && maxTimer > 0) {
            const progress = activeTimer / maxTimer;
            this.drawCircularGauge(ctx, x, y, progress, iconType, gaugeColor, false);
        }
    }

    // 1. FACTION-BASED HP BARS REFACTOR
    private drawUnitBars(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, isSelected: boolean, time: number) {
        const hasMp = agent.maxMp > 0;

        const contentW = BAR_WIDTH;
        const hpHeight = BAR_HEIGHT;
        const mpHeight = hasMp ? 3 : 0;
        const gap = hasMp ? 2 : 0;

        const contentH = hpHeight + gap + mpHeight;
        const totalW = contentW + BAR_PADDING * 2;
        const totalH = contentH + BAR_PADDING * 2;

        const startX = x - totalW / 2;
        const startY = y - 5; 

        // Container
        ctx.save();
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(startX, startY, totalW, totalH, 6);
        else ctx.rect(startX, startY, totalW, totalH);

        // Dark Glass BG
        ctx.fillStyle = 'rgba(2, 6, 23, 0.7)'; 
        ctx.fill();

        // Team-colored Border Highlight
        const teamBorder = agent.team === Team.BLUE ? '#3b82f6' : '#ef4444';
        ctx.lineWidth = 1;
        ctx.strokeStyle = isSelected ? teamBorder : 'rgba(255, 255, 255, 0.15)';
        ctx.stroke();

        if (isSelected) {
            ctx.shadowColor = teamBorder;
            ctx.shadowBlur = 10;
            ctx.stroke();
            ctx.shadowBlur = 0;
        }
        ctx.restore();

        const barX = startX + BAR_PADDING;
        const barY = startY + BAR_PADDING;

        // HP Bar - Faction Colored
        const hpPct = Math.max(0, agent.hp / agent.maxHp);
        let hpTop, hpBot, hpGlow;

        if (agent.team === Team.BLUE) {
            // IMPERIAL CYAN/BLUE
            hpTop = '#22d3ee';
            hpBot = '#0284c7';
            hpGlow = 'rgba(6, 182, 212, 0.5)';
        } else {
            // COVENANT RED/ORANGE
            hpTop = '#f87171';
            hpBot = '#dc2626';
            hpGlow = 'rgba(220, 38, 38, 0.5)';
        }

        this.drawFluidBar(ctx, barX, barY, contentW, hpHeight, hpPct, hpTop, hpBot, hpGlow);

        // MP Bar - Always Blue/Purple
        if (hasMp) {
            const mpPct = Math.max(0, agent.mp / agent.maxMp);
            const mpY = barY + hpHeight + gap;
            this.drawFluidBar(ctx, barX, mpY, contentW, mpHeight, mpPct, '#a78bfa', '#7c3aed', 'rgba(139, 92, 246, 0.4)');
        }
    }

    private drawFluidBar(ctx: CanvasRenderingContext2D, bx: number, by: number, bw: number, bh: number, pct: number, colTop: string, colBot: string, glow: string) {
        if (pct <= 0.01) return;
        const fillW = Math.max(bh, bw * pct); 

        ctx.save();
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh, bh/2);
        else ctx.rect(bx, by, fillW, bh);

        const grad = ctx.createLinearGradient(bx, by, bx, by + bh);
        grad.addColorStop(0, colTop);
        grad.addColorStop(1, colBot);
        ctx.fillStyle = grad;

        ctx.shadowColor = glow;
        ctx.shadowBlur = 5;
        ctx.fill();
        ctx.shadowBlur = 0;

        // Gloss
        ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(bx, by, fillW, bh * 0.4, bh/2);
        else ctx.rect(bx, by, fillW, bh * 0.4);
        ctx.fill();

        ctx.restore();
    }

    private drawCircularGauge(ctx: CanvasRenderingContext2D, x: number, y: number, pct: number, visualKey: string, color: string, isSkill: boolean) {
        const radius = 14;
        const iconY = y - 24; 

        ctx.save();
        ctx.beginPath();
        ctx.arc(x, iconY, radius, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(2, 6, 23, 0.8)';
        ctx.fill();
        ctx.save();
        ctx.clip();

        let icon;
        if (isSkill) {
            icon = AssetManager.getSkillIcon(visualKey, color);
        } else {
            icon = AssetManager.getStatusIcon(visualKey);
        }

        ctx.globalAlpha = 0.8;
        if (icon) ctx.drawImage(icon, x - radius, iconY - radius, radius * 2, radius * 2);
        ctx.restore();

        ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
        ctx.lineWidth = 2;
        ctx.stroke();

        const safePct = Math.max(0, Math.min(1, pct));
        if (safePct > 0) {
            ctx.beginPath();
            ctx.arc(x, iconY, radius, -Math.PI / 2, -Math.PI / 2 + (Math.PI * 2 * safePct));
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.shadowColor = color;
            ctx.shadowBlur = 8;
            ctx.stroke();
        }

        ctx.restore();
    }

    private drawFloatingText(ctx: CanvasRenderingContext2D) {
        this.damageNumbers.forEach(d => {
            if (!d.active) return;

            const lifePct = d.life / d.maxLife;
            const alpha = lifePct < 0.3 ? lifePct / 0.3 : 1.0;

            ctx.globalAlpha = alpha;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.shadowBlur = 0; 

            if (d.type === 'KILL_STREAK') {
                ctx.save();
                ctx.translate(d.x, d.y);
                const pop = Math.min(1, (1 - lifePct) * 5); 
                const pulse = 1 + Math.sin(lifePct * 10) * 0.1;
                const scale = pop * pulse * 1.5; 
                ctx.scale(scale, scale);
                ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                const grad = ctx.createLinearGradient(0, -d.size/2, 0, d.size/2);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.5, d.color);
                grad.addColorStop(1, '#000000');

                ctx.lineWidth = 4;
                ctx.lineJoin = 'round';
                ctx.strokeStyle = '#000';
                ctx.strokeText(d.text, 0, 0);
                ctx.fillStyle = grad;
                ctx.fillText(d.text, 0, 0);
                ctx.restore();

            } else if (d.type === 'SHOUT') {
                // ... (Existing Shout Logic kept for brevity, it works fine) ...
                if (d.isUlt) {
                    const scale = 1 + (1 - lifePct) * 0.1; 
                    ctx.save();
                    ctx.translate(d.x, d.y);
                    ctx.scale(scale, scale);
                    ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;
                    const textMetrics = ctx.measureText(d.text);
                    const w = textMetrics.width / 2 + 25;
                    const h = d.size + 12;

                    const bgGrad = ctx.createLinearGradient(-w - 20, 0, w + 20, 0);
                    bgGrad.addColorStop(0, 'rgba(0,0,0,0)');
                    bgGrad.addColorStop(0.3, 'rgba(2, 6, 23, 0.85)'); 
                    bgGrad.addColorStop(0.7, 'rgba(2, 6, 23, 0.85)');
                    bgGrad.addColorStop(1, 'rgba(0,0,0,0)');

                    ctx.fillStyle = bgGrad;
                    ctx.fillRect(-w - 20, -h/2, w*2 + 40, h);

                    ctx.strokeStyle = d.color;
                    ctx.lineWidth = 2;
                    ctx.globalAlpha = alpha * 0.8;

                    ctx.beginPath(); ctx.moveTo(-w, -h/2); ctx.lineTo(w, -h/2); ctx.stroke();
                    ctx.beginPath(); ctx.moveTo(-w * 0.8, h/2); ctx.lineTo(w * 0.8, h/2); ctx.stroke();

                    ctx.globalAlpha = alpha;
                    ctx.shadowColor = d.color; ctx.shadowBlur = 15;
                    ctx.fillStyle = '#fff';
                    ctx.fillText(d.text, 0, 0);
                    ctx.restore();
                } else {
                    ctx.font = `bold ${d.size}px "Segoe UI", sans-serif`;
                    const textMetrics = ctx.measureText(d.text);
                    const padX = 12;
                    const padY = 6;
                    const w = textMetrics.width;
                    const h = d.size;

                    ctx.fillStyle = 'rgba(15, 23, 42, 0.75)'; 
                    ctx.beginPath();
                    if (ctx.roundRect) ctx.roundRect(d.x - w/2 - padX, d.y - h/2 - padY, w + padX*2, h + padY*2, 8);
                    else ctx.rect(d.x - w/2 - padX, d.y - h/2 - padY, w + padX*2, h + padY*2);
                    ctx.fill();

                    ctx.strokeStyle = `rgba(255,255,255,0.15)`;
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    ctx.shadowColor = d.color; ctx.shadowBlur = 8;
                    ctx.fillStyle = '#fff'; 
                    ctx.fillText(d.text, d.x, d.y);
                    ctx.shadowBlur = 0;
                }

            } else {
                // DAMAGE / HEAL / CC
                ctx.font = `900 ${d.size}px "Segoe UI", sans-serif`;

                // Outline to make it readable on any background
                ctx.lineWidth = 3;
                ctx.strokeStyle = 'rgba(0,0,0,0.8)';
                ctx.strokeText(d.text, d.x, d.y);

                ctx.fillStyle = d.color; 
                ctx.fillText(d.text, d.x, d.y);
            }

            ctx.globalAlpha = 1.0;
        });
    }
}

import { GameEvent, GameEventType } from "../../../types";
import { GameEngine } from "../../game";
import { HUDSystem } from "../hud";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { HUD_TEXT_OFFSET, KILL_STREAK_WINDOW } from "../../../constants";

export class EventHUDMapper {
    private killStreaks = new Map<string, { count: number, lastTime: number }>();
    private firstBlood = false;

    public reset() {
        this.killStreaks.clear();
        this.firstBlood = false;
    }

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        hud: HUDSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        if (engine.battleTime < 0.1) this.reset();

        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'DAMAGE':
            case 'HEAL':
            case 'CC_APPLIED':
                this.handleCombatText(event, visualGroundY, hud);
                break;
            case 'CAST_START':
                this.handleCastText(event, visualGroundY, hud);
                break;
            case 'KILL':
                this.handleKillStreak(event, engine, grid, hud, camera);
                break;
        }
    }

    private handleCombatText(event: GameEvent, visualY: number, hud: HUDSystem) {
        const baseY = visualY - HUD_TEXT_OFFSET; 
        let text = "";
        let color = "#fff";
        let size = 16;
        let type: 'DAMAGE' | 'HEAL' | 'CC' = 'DAMAGE';
        let xOffset = 0;

        if (event.type === 'DAMAGE') {
            const val = Math.abs(event.value || 0);
            text = val.toString();
            const isCrit = val > 100;

            // 2. TEXT COLORING LOGIC
            // Check if damage comes from DOT (Poison/Burn/Bleed)
            const isDot = event.skill?.ccType === 'DOT';

            if (isDot) {
                color = '#a3e635'; // Lime Green for Poison/Dot
            } else if (isCrit) {
                color = '#ef4444'; // Red for Crit
            } else {
                color = '#fff';    // White for normal
            }

            size = isCrit ? 24 : 16;
            type = 'DAMAGE';
            xOffset = (Math.random() - 0.5) * 10;

        } else if (event.type === 'HEAL') {
            text = "+" + Math.abs(event.value || 0);
            color = '#4ade80';
            type = 'HEAL';
            xOffset = (Math.random() - 0.5) * 10;
        } else {
            text = event.text || "";
            color = event.color || "#fff";
            type = 'CC';
            size = 14;
            xOffset = -45;
        }

        if (text) hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
    }

    private handleCastText(event: GameEvent, visualY: number, hud: HUDSystem) {
        if (event.skill && event.skill.tag !== 'BASIC') {
            const isUlt = event.skill.tag === 'ULT';
            const baseY = visualY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
            const xOffset = 55; 
            hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
        }
    }

    private handleKillStreak(event: GameEvent, engine: GameEngine, grid: GridSystem, hud: HUDSystem, camera: CameraSystem) {
        if (!event.sourceId) return;

        const now = engine.battleTime;
        const killer = event.sourceId;
        const killerAgent = engine.agents.find(a => a.id === killer);

        if (!killerAgent) return;

        // Visual Position for Streak Text
        const kHex = HexUtils.fromPx(killerAgent.px, killerAgent.py, engine.mapConfig);
        const kH = grid.getTerrainHeight(kHex.q, kHex.r, engine);
        const textY = killerAgent.py - kH - HUD_TEXT_OFFSET;

        if (!this.firstBlood) {
            this.firstBlood = true;
            hud.addFloatingText(killerAgent.px, textY - 60, "FIRST BLOOD", "#ef4444", 36, 'KILL_STREAK');
            camera.addTrauma(0.3);
        }

        let streak = 1;
        const existing = this.killStreaks.get(killer);
        if (existing && now - existing.lastTime <= KILL_STREAK_WINDOW) streak = existing.count + 1;

        this.killStreaks.set(killer, { count: streak, lastTime: now });

        if (streak >= 2) {
            let streakText = "DOUBLE KILL";
            let streakColor = "#cbd5e1";

            if (streak === 3) { streakText = "TRIPLE KILL"; streakColor = "#fcd34d"; }
            else if (streak === 4) { streakText = "QUADRA KILL"; streakColor = "#fb923c"; }
            else if (streak >= 5) { streakText = "PENTA KILL"; streakColor = "#ef4444"; }

            hud.addFloatingText(killerAgent.px, textY - 40, streakText, streakColor, 32 + (streak * 4), 'KILL_STREAK');
            camera.addTrauma(0.2 + streak * 0.1);
        }
    }
}

import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";

export const ZoneRenderer = {

    draw(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Center of the tile face
        size: number,
        color: string,
        type: 'CAST' | 'FIELD',
        visual: string,
        progress: number, 
        globalTime: number,
        dist: number, 
        maxRadius: number
    ) {
        // 3. RIPPLE & RIM LOGIC

        // Setup shared styles
        ctx.save();
        ctx.translate(x, y); // Local center of the tile face
        ctx.scale(1, ISO_SCALE_Y); // Flatten to isometric plane

        if (type === 'CAST') {
            // --- AOE TELEGRAPH: EXPANDING RIPPLE ---
            // Calculate ripple radius relative to the whole area
            // progress 0 -> 1. 
            // Max Radius in pixels approx = maxRadius * HEX_SIZE * 1.5
            const totalRadiusPx = Math.max(1, maxRadius) * HEX_SIZE * 1.5;

            // Current wave position (0 to 1)
            // progress is (1 - castTimer/max), so it goes 0 to 1
            const wavePos = progress; 

            // Distance of THIS tile from the center of the AOE (in hex distance unit)
            // Convert dist (hex steps) to approx pixel distance from center
            const tileDistPx = dist * HEX_SIZE * 1.5; 

            // Normalize tile distance relative to total area
            const normalizedDist = tileDistPx / totalRadiusPx;

            // Band width logic
            // If the wave is passing through this tile right now
            const bandWidth = 0.2; 
            const diff = Math.abs(normalizedDist - wavePos);

            if (diff < bandWidth) {
                // Inside the ripple band
                const alpha = (1 - diff / bandWidth) * 0.8;

                ctx.beginPath();
                ctx.arc(0, 0, size * 0.8, 0, Math.PI*2);
                ctx.fillStyle = color;
                ctx.globalAlpha = alpha * 0.3; // Low fill
                ctx.fill();

                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.globalAlpha = alpha;
                ctx.stroke();
            } else {
                // Background faint indicator to show it's threatened
                ctx.beginPath();
                ctx.arc(0, 0, size * 0.2, 0, Math.PI*2); // Small dot
                ctx.fillStyle = color;
                ctx.globalAlpha = 0.2;
                ctx.fill();
            }

            // Always draw a faint rim to define the hex grid
            ctx.beginPath();
            ctx.arc(0, 0, size * 0.9, 0, Math.PI*2);
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.1;
            ctx.stroke();

        } else if (type === 'FIELD') {
            // --- PERSISTENT FIELD: RIM GLOW ONLY ---
            // Do NOT fill the center, so ground VFX (particles) can be seen.

            const intensity = Math.sin(globalTime * 3 + dist * 0.5) * 0.3 + 0.7;

            // 1. Glowing Rim
            ctx.beginPath();
            const r = size * 0.9;
            // Draw Hex shape manually or circle approximation
            // Using circle for smoother look on fields
            ctx.arc(0, 0, r, 0, Math.PI*2);

            ctx.strokeStyle = color;
            ctx.lineWidth = 2 * intensity;
            ctx.globalAlpha = 0.8;
            ctx.stroke();

            // 2. Inner Glow (Gradient fade inward, but very short)
            const grad = ctx.createRadialGradient(0, 0, r * 0.7, 0, 0, r);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(1, color);

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.3 * intensity;
            ctx.fill();

            // 3. Rotating Runes/Debris (Subtle)
            // if it's a field, we might want some floating debris indication
            ctx.rotate(globalTime * 0.5 + dist);
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.6;
            ctx.beginPath();
            ctx.arc(r, 0, 2, 0, Math.PI*2); // Orbiting dot
            ctx.fill();
        }

        ctx.restore();
    }
};

import { TerrainRenderer } from "./TerrainRenderer";
import { ZoneRenderer } from "./ZoneRenderer";

// Updated Interface matching GridSystem
interface ZoneInfo {
    type: 'CAST' | 'FIELD';
    color: string;
    visual: string;
    progress: number;
    centerQ: number;
    centerR: number;
    radius: number;
    dist: number;
}

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Visual top Y
        size: number,
        specialStatus: string | undefined,
        zoneInfo: ZoneInfo | undefined, // Replaces dangerInfo
        lightColor: string | null,
        lightIntensity: number,
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,
        q: number, r: number,
        globalTime: number
    ) {
        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        // 1. SPECIAL STATUS FLOOR EFFECT
        if (specialStatus) {
            trace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            if (specialStatus === 'FROZEN') {
                ctx.fillStyle = '#bae6fd'; 
                ctx.globalAlpha = 0.6;
            } else if (specialStatus === 'POLYMORPH') {
                ctx.fillStyle = '#d8b4fe'; 
                ctx.globalAlpha = 0.5;
            } else if (specialStatus === 'STASIS') {
                ctx.fillStyle = '#fde047';
                ctx.globalAlpha = 0.5;
            }
            ctx.fill(); 
            ctx.restore();
        }

        // 2. ZONE RENDERING (Cast Ripple / Persistent Fields)
        if (zoneInfo) {
            ZoneRenderer.draw(
                ctx, x, y, size,
                zoneInfo.color,
                zoneInfo.type,
                zoneInfo.visual,
                zoneInfo.progress,
                globalTime,
                zoneInfo.dist,
                zoneInfo.radius
            );
        }

        // 3. Dynamic Lighting
        if (lightColor && lightIntensity > 0) {
            trace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = lightIntensity * 0.8; 
            ctx.fillStyle = lightColor;
            ctx.fill();
            ctx.restore();
        }

        // 4. Interactive Highlights
        if (isRange || isHover || hasUnit) {
            ctx.save();
            trace(); 

            // 4. RANGE INDICATOR - VISIBILITY FIX
            // Only draw STROKE mainly, with very faint fill
            if (isRange) { 
                // Border
                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 1.5; 
                ctx.globalAlpha = 0.6; 
                ctx.stroke();

                // Fill (Very transparent to show ground)
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.05; 
                ctx.fill();
            }

            if (isHover) { 
                ctx.fillStyle = 'rgba(255,255,255,0.1)'; 
                ctx.globalAlpha = 1.0;
                ctx.fill(); 
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 2; 
                ctx.stroke(); 
            }

            if (hasUnit && !isHover && !zoneInfo) {
                ctx.strokeStyle = 'rgba(255,255,255,0.15)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { SpriteManager } from "../../sprites";
